def qr_image(text, px=360, dark="#000000", light="#ffffff"):
    """📱 7.63 : QR code (segno, niveau de correction M) -> QImage carrée d'environ px pixels, marge de 4 modules.
    None si segno manque (l'adresse reste affichée en texte)."""
    try:
        import segno
    except Exception:  # noqa: BLE001
        return None
    q = segno.make(text, error="m", micro=False)
    rows = [list(r) for r in q.matrix]
    n = len(rows) + 8
    sc = max(2, px // n)
    img = QtGui.QImage(n * sc, n * sc, QtGui.QImage.Format.Format_RGB32)
    img.fill(QtGui.QColor(light))
    p = QtGui.QPainter(img)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QtGui.QColor(dark))
    for y, r in enumerate(rows):
        for x, v in enumerate(r):
            if v:
                p.drawRect((x + 4) * sc, (y + 4) * sc, sc, sc)
    p.end()
    return img


class HistoryDialog(QtWidgets.QDialog):
    """🕘 7.63 : historique des modifications de la liste : heure, qui (PC / téléphone / plan suivi), quoi, avant,
    après ; filtre, export CSV. Gardé dans le show."""

    COLS = ["Heure", "Qui", "Quoi", "Micro", "Avant", "Après"]

    def __init__(self, owner):
        super().__init__(owner)
        self.owner = o = owner
        self.setWindowTitle("Historique des modifications")
        lay = QtWidgets.QVBoxLayout(self)
        self.q = QtWidgets.QLineEdit()
        self.q.setPlaceholderText("🔎 Filtrer : nom, fréquence, qui…")
        self.q.setClearButtonEnabled(True)
        self.q.textChanged.connect(lambda *_: self.fill())
        lay.addWidget(self.q)
        self.table = QtWidgets.QTableWidget(0, len(self.COLS))
        self.table.setHorizontalHeaderLabels(self.COLS)
        self.table.verticalHeader().setVisible(False)
        self.table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.horizontalHeader().setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeMode.Stretch)
        self.table.setToolTip("Chaque changement de ta liste : ajout, retrait, fréquence, nom, statut, scène › groupe.\n"
                              "« 📱 nom » = fait depuis la page Tech d'un téléphone. Le plus récent en haut.")
        lay.addWidget(self.table, 1)
        self.msg = QtWidgets.QLabel("")
        exp = QtWidgets.QPushButton("Exporter en CSV…")
        exp.setToolTip("Pour l'archiver ou l'envoyer (tableur).")
        exp.clicked.connect(lambda *_: self.export())
        clr = QtWidgets.QPushButton("Vider l'historique")
        clr.setToolTip("Efface l'historique de ce show (la liste ne change pas).")
        clr.clicked.connect(lambda *_: self.clear())
        close = QtWidgets.QPushButton("Fermer")
        close.clicked.connect(self.close)
        lay.addLayout(o._row(self.msg, None, exp, clr, close))
        self.resize(820, 520)
        self.fill()

    def rows(self):
        q = self.q.text().strip().lower()
        out = []
        for x in reversed(self.owner.mod_history):
            vals = (datetime.fromtimestamp(x["t"]).strftime("%d/%m %H:%M:%S"), x["who"], TR(HIST_WHAT.get(x["what"], x["what"])),
                    x["name"], x["old"], x["new"])
            if q and q not in " ".join(vals).lower():
                continue
            out.append(vals)
        return out

    def fill(self):
        rows = self.rows()
        self.table.setRowCount(len(rows))
        for r, vals in enumerate(rows):
            for c, v in enumerate(vals):
                self.table.setItem(r, c, QtWidgets.QTableWidgetItem(v))
        self.msg.setText(TR("{} changement(s)").format(len(rows)))

    def export(self, path=None):
        if path is None:
            path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Exporter l'historique", "historique.csv", "CSV (*.csv)")
            if not path:
                return False
        with open(path, "w", encoding="utf-8-sig", newline="") as fh:
            wr = csv.writer(fh, delimiter=";")
            wr.writerow([TR(c) for c in self.COLS])
            wr.writerows(self.rows())
        return True

    def clear(self):
        r = QtWidgets.QMessageBox.question(self, APP_NAME, TR("Vider l'historique des modifications de ce show ?"))
        if r == QtWidgets.QMessageBox.StandardButton.Yes:
            self.owner.mod_history = []
            self.fill()


class QrDialog(QtWidgets.QDialog):
    """📱 7.63 : QR code de la page web : l'équipe le scanne avec l'appareil photo du téléphone et arrive sur la bonne
    vue (accueil, mur, alarmes, régie, Tech…), sans avoir à dicter l'adresse. Enregistrable en PNG pour l'imprimer."""

    def __init__(self, owner):
        super().__init__(owner)
        self.owner = o = owner
        self.setWindowTitle("QR code pour les téléphones")
        lay = QtWidgets.QVBoxLayout(self)
        self.info = QtWidgets.QLabel("Scanne ce code avec l'appareil photo du téléphone (même Wi-Fi / réseau que ce PC) : "
                                     "la page s'ouvre directement sur la vue choisie.")
        self.info.setWordWrap(True)
        lay.addWidget(self.info)
        self.ip_combo = QtWidgets.QComboBox()
        self.ip_combo.setToolTip("Adresse de ce PC sur le réseau (s'il y en a plusieurs : celle du réseau de l'équipe).")
        self.view_combo = QtWidgets.QComboBox()
        self.view_combo.setToolTip("Vue ouverte en arrivant (seulement les vues partagées dans 📣 Alertes et page web).")
        lay.addLayout(o._row("Adresse :", self.ip_combo, "Ouvrir sur :", self.view_combo, None))
        self.qr = QtWidgets.QLabel("")
        self.qr.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.qr.setMinimumSize(300, 300)
        lay.addWidget(self.qr, 1)
        self.url = QtWidgets.QLabel("")
        self.url.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.url.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
        f = self.url.font()
        f.setPointSizeF(f.pointSizeF() * 1.3)
        self.url.setFont(f)
        lay.addWidget(self.url)
        self.web_btn = QtWidgets.QPushButton("📣 Activer la page web…")
        self.web_btn.setToolTip("La page web est coupée : l'activer dans 📣 Alertes et page web.")
        self.web_btn.clicked.connect(lambda *_: o.open_alerts())
        copy = QtWidgets.QPushButton("Copier l'adresse")
        copy.setToolTip("Copie l'adresse dans le presse-papiers (pour un message à l'équipe).")
        copy.clicked.connect(lambda *_: QtWidgets.QApplication.clipboard().setText(self.link()))
        save = QtWidgets.QPushButton("Enregistrer en PNG…")
        save.setToolTip("Image à imprimer et coller en régie ou au plateau.")
        save.clicked.connect(lambda *_: self.save_png())
        close = QtWidgets.QPushButton("Fermer")
        close.clicked.connect(self.close)
        lay.addLayout(o._row(self.web_btn, None, copy, save, close))
        self.ip_combo.currentIndexChanged.connect(lambda *_: self.draw())
        self.view_combo.currentIndexChanged.connect(lambda *_: self.draw())
        self.fill()
        self.resize(460, 560)

    def fill(self):
        o = self.owner
        self.ip_combo.blockSignals(True)
        self.view_combo.blockSignals(True)
        self.ip_combo.clear()
        for ip in local_ips() or ["127.0.0.1"]:
            self.ip_combo.addItem(ip, ip)
        self.view_combo.clear()
        self.view_combo.addItem("🏠 Accueil", "")
        views = (o.web_cfg or {}).get("views") or {}
        for k, ic, name, _d in WEB_VIEWS:
            if views.get(k, k not in WEB_VIEWS_HIDDEN):
                self.view_combo.addItem(f"{ic} {name}", k)
        self.ip_combo.blockSignals(False)
        self.view_combo.blockSignals(False)
        self.draw()

    def link(self):
        o = self.owner
        port = o.web.port if o.web is not None else int((o.web_cfg or {}).get("port", 8080) or 8080)
        return web_link(self.ip_combo.currentData() or "127.0.0.1", port, self.view_combo.currentData() or "")

    def draw(self):
        on = self.owner.web is not None
        self.web_btn.setVisible(not on)
        url = self.link()
        self.url.setText(url if on else TR("Page web coupée : active-la pour que ce code fonctionne."))
        img = qr_image(url, 360)
        self._img = img
        if img is None:
            self.qr.setText("(QR code indisponible : ouvre l'adresse ci-dessous à la main)")
        else:
            self.qr.setPixmap(QtGui.QPixmap.fromImage(img))
        self.qr.setEnabled(on)

    def save_png(self, path=None):
        if self._img is None:
            return False
        if path is None:
            path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Enregistrer le QR code", "tinysa_qr.png", "Image PNG (*.png)")
            if not path:
                return False
        return bool(self._img.save(path, "PNG"))


class MapNode(QtWidgets.QGraphicsObject):
    """🗺 Une carte de la vue Carte : une scène (état de ses micros) ou un tinySA (en ligne / perdu). Glissable,
    aimantée à la grille ; déposer un tinySA sur une scène = la lui rattacher."""

    def __init__(self, owner, key):
        super().__init__()
        self.owner, self.key = owner, key
        self.kind, self.name = key.split(":", 1)
        self.w, self.h = (260.0, 100.0) if self.kind == "scene" else (230.0, 84.0)
        self.title, self.sub, self.col, self.stripe = self.name, "", "#888888", "#888888"
        self.pill, self.dots, self.extra = "", [], ""  # pastille d'état, un point par micro, ligne du bas
        sh = QtWidgets.QGraphicsDropShadowEffect()
        sh.setBlurRadius(18)
        sh.setOffset(0, 3)
        sh.setColor(QtGui.QColor(0, 0, 0, 110))
        self.setGraphicsEffect(sh)
        self.setFlag(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsMovable, True)
        self.setFlag(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
        self.setFlag(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges, True)
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setZValue(10)
        self.setAcceptHoverEvents(True)

    def boundingRect(self):
        return QtCore.QRectF(-8, -8, self.w + 16, self.h + 16)

    def center(self):
        return self.pos() + QtCore.QPointF(self.w / 2, self.h / 2)

    def port(self, top):
        """Point d'accroche des liens : haut (scène) ou bas (tinySA) de la tuile."""
        return self.pos() + QtCore.QPointF(self.w / 2, 0.0 if top else self.h)

    def paint(self, p, opt, widget=None):
        th = self.owner.theme
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing, True)
        r = QtCore.QRectF(0, 0, self.w, self.h)
        sel = self.isSelected()
        card = blend(th["ui_text"], th["ui_base"], 0.05)
        edge = th["ui_accent"] if sel else blend(self.col, card, 0.55)
        p.setPen(QtGui.QPen(QtGui.QColor(edge), 2.5 if sel else 1.2))
        p.setBrush(QtGui.QColor(card))
        p.drawRoundedRect(r, 12, 12)
        p.setPen(Qt.PenStyle.NoPen)                    # bande de couleur de la scène / du tinySA
        p.setBrush(QtGui.QColor(self.stripe))
        path = QtGui.QPainterPath()
        path.addRoundedRect(QtCore.QRectF(0, 0, 14, self.h), 12, 12)
        clip = QtGui.QPainterPath()
        clip.addRect(QtCore.QRectF(0, 0, 6, self.h))
        p.drawPath(path.intersected(clip))
        base = QtGui.QFont(p.font())
        fp = QtGui.QFont(base)                         # pastille d'état (en haut à droite)
        fp.setBold(True)
        fp.setPointSizeF(8.0)
        fmp = QtGui.QFontMetrics(fp)
        pw = fmp.horizontalAdvance(self.pill) + 24
        pr = QtCore.QRectF(self.w - pw - 10, 10, pw, 20)
        p.setBrush(QtGui.QColor(blend(self.col, card, 0.22)))
        p.setPen(QtGui.QPen(QtGui.QColor(self.col), 1.0))
        p.drawRoundedRect(pr, 10, 10)
        p.setBrush(QtGui.QColor(self.col))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(QtCore.QPointF(pr.left() + 9, pr.center().y()), 3.2, 3.2)
        p.setFont(fp)
        p.setPen(QtGui.QColor(self.col))
        p.drawText(pr.adjusted(18, 0, -4, 0), Qt.AlignmentFlag.AlignCenter, self.pill)
        ft = QtGui.QFont(base)                         # titre
        ft.setBold(True)
        ft.setPointSizeF(12.5)
        p.setFont(ft)
        p.setPen(QtGui.QColor(th["ui_text"]))
        tw = int(self.w - pw - 34)
        p.drawText(QtCore.QRectF(18, 8, tw, 24), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   QtGui.QFontMetrics(ft).elidedText(self.title, Qt.TextElideMode.ElideRight, tw))
        fs = QtGui.QFont(base)                         # sous-titre (texte secondaire)
        fs.setPointSizeF(9.5)
        p.setFont(fs)
        p.setPen(QtGui.QColor(blend(th["ui_text"], card, 0.62)))
        p.drawText(QtCore.QRectF(18, 36, self.w - 30, 20), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   QtGui.QFontMetrics(fs).elidedText(self.sub, Qt.TextElideMode.ElideRight, int(self.w - 30)))
        if self.kind == "scene":                       # un point par micro, à sa couleur d'état
            x, y = 22.0, self.h - 22.0
            for c in self.dots[:20]:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QtGui.QColor(c))
                p.drawEllipse(QtCore.QPointF(x, y), 5.0, 5.0)
                x += 13.0
            if len(self.dots) > 20:
                p.setPen(QtGui.QColor(blend(th["ui_text"], card, 0.62)))
                p.drawText(QtCore.QRectF(x - 4, y - 9, 40, 18), Qt.AlignmentFlag.AlignVCenter, f"+{len(self.dots) - 20}")
            if not self.dots:
                p.setPen(QtGui.QColor(blend(th["ui_text"], card, 0.45)))
                p.drawText(QtCore.QRectF(18, self.h - 32, self.w - 30, 20), Qt.AlignmentFlag.AlignVCenter,
                           TR("aucun micro dans cette scène"))
        else:
            p.setPen(QtGui.QColor(blend(th["ui_text"], card, 0.62)))
            p.drawText(QtCore.QRectF(18, self.h - 30, self.w - 30, 20), Qt.AlignmentFlag.AlignVCenter,
                       QtGui.QFontMetrics(fs).elidedText(self.extra, Qt.TextElideMode.ElideRight, int(self.w - 30)))


    def itemChange(self, change, value):
        if change == QtWidgets.QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged and self.scene() is not None:
            self.scene().update_links()
        return super().itemChange(change, value)

    def mouseReleaseEvent(self, e):
        super().mouseReleaseEvent(e)
        sc = self.scene()
        if sc is not None:
            sc.node_dropped(self)

    def mouseDoubleClickEvent(self, e):
        sc = self.scene()
        if sc is not None:
            sc.node_open(self)


class MapScene(QtWidgets.QGraphicsScene):
    """🗺 7.64 : la carte du site (façon canevas réseau) : grille, scènes et tinySA en cartes glissables, liens tinySA →
    scènes surveillées, plan du site en fond (facultatif), points de la carte de chaleur. Modèle = owner.map_cfg."""

    def __init__(self, owner):
        super().__init__()
        self.owner = owner
        self.nodes, self.links, self.heat_items, self.hot_item = {}, [], [], None
        self.arrow_info = None
        self.bg_item = None
        self.heat_f = None                    # fréquence affichée en chaleur (None = toutes)
        self.show_heat = True
        self.setSceneRect(-2000, -2000, 6000, 4000)

    # --- contenu
    def _keys_all_base(self):
        o = self.owner
        return [map_key("scene", sc["name"]) for sc in o.scenes] + [map_key("dev", d) for d in o.dev_list()]

    def keys_all(self):
        if rf_mode_norm(getattr(self.owner, "rf_mode", "tiny")) == "tiny":      # mode tinySA seul : pas de SDR sur la carte
            return self._keys_all_base()
        return self._keys_all_base() + [map_key("sdr", p["id"]) for p in sdr_posts_norm(self.owner.sdr_cfg.get("posts"))]

    def _label_base(self, key):
        kind, name = key.split(":", 1)
        o = self.owner
        return name if kind == "scene" else f"{dev_ord(int(name))} tinySA · {o.dev_name(int(name))}"

    def label(self, key):
        kind, name = key.split(":", 1)
        if kind != "sdr":
            return self._label_base(key)
        e = (getattr(self.owner, "sdr_engs", None) or {}).get(int(name))
        return f"📡 {e.name() if e else 'SDR ' + name}"

    def sync(self):
        """Ajoute / retire les cartes selon les scènes / tinySA et les positions enregistrées."""
        o = self.owner
        pos = o.map_cfg["pos"]
        want = [k for k in self.keys_all() if k in pos]
        for k in list(self.nodes):
            if k not in want:
                self.removeItem(self.nodes.pop(k))
        for k in want:
            n = self.nodes.get(k)
            if n is None:
                n = MapNode(o, k)
                self.nodes[k] = n
                self.addItem(n)
            n.setPos(QtCore.QPointF(*pos[k]))
        self.sync_bg()
        self.refresh()
        self.sync_heat()

    def unplaced(self):
        pos = self.owner.map_cfg["pos"]
        return [k for k in self.keys_all() if k not in pos]

    def place(self, key, x, y):
        self.owner.map_cfg["pos"][key] = map_snap(x, y)
        self.sync()

    def auto_place(self):
        cfg = self.owner.map_cfg
        cfg["pos"].update(map_auto_place(self.keys_all(), cfg["pos"]))
        self.sync()

    def remove(self, key):
        self.owner.map_cfg["pos"].pop(key, None)
        self.sync()

    # --- état en direct
    def _scene_state_base(self, name):
        o = self.owner
        ws = [w for w in o.watch if w.get("scene") == name and not w.get("off")]
        tones = [o.sig_view(w)[1] for w in ws]
        al = sum(1 for a in o.alarms.active.values() if any(abs((a.get("freq") or -1) - w["freq"]) < 0.0015 for w in ws))
        if not o.is_running():
            tone = "none"
        elif al or "bad" in tones:
            tone = "bad"
        elif "warn" in tones:
            tone = "warn"
        else:
            tone = "ok"
        sub = TR("{} micro(s)").format(len(ws))
        pill = (TR("Arrêté") if not o.is_running() else TR("{} alarme(s)").format(al) if al
                else TR("À surveiller") if tone in ("bad", "warn") else TR("OK"))
        dots = [o.tone_color(t) if o.is_running() else o.theme["st_none"] for t in tones]
        # 7.65 (audit) : état de la SURVEILLANCE de la scène, séparé de l'état RF de ses micros : un vieil état vert ne
        # doit jamais passer pour une surveillance qui marche (tinySA perdus, mesures périmées)
        mon = map_scene_monitor(o.is_running(), self.scene_devs(name), [w.get("state") for w in ws])
        if mon == "lost":
            tone, pill = "warn", TR("Surveillance perdue")
            dots = [o.theme["st_none"]] * len(tones)
        elif mon == "nodata":
            tone, pill = "warn", TR("Pas de mesure")
            dots = [o.theme["st_none"]] * len(tones)
        elif mon == "partial":
            n_ = sum(1 for w in ws if w.get("state") is None)
            sub = TR("{} micro(s)").format(len(ws)) + " · " + TR("{} sans mesure").format(n_)
            if tone == "ok":
                tone, pill = "warn", TR("Mesure partielle")
            dots = [o.theme["st_none"] if w.get("state") is None else c_ for w, c_ in zip(ws, dots)]
        return tone, sub, pill, dots

    def scene_state(self, name):
        """Une scène surveillée par un SDR en marche n'est pas « Arrêtée », même si les tinySA ne tournent pas."""
        o = self.owner
        live = [e for e in (getattr(o, "sdr_engs", None) or {}).values()
                if _v8_post_live(e) and (not e.post()["scenes"] or name in e.post()["scenes"])]
        if o.is_running() or not live:
            return self._scene_state_base(name)
        ws = [w for w in o.watch if w.get("scene") == name and not w.get("off")]
        tones = [o.sig_view(w)[1] for w in ws]
        al = sum(1 for a in o.alarms.active.values() if any(abs((a.get("freq") or -1) - w["freq"]) < 0.0015 for w in ws))
        tone = "bad" if (al or "bad" in tones) else ("warn" if "warn" in tones else "ok")
        pill = (TR("{} alarme(s)").format(al) if al else TR("À surveiller") if tone in ("bad", "warn") else TR("OK"))
        sub = TR("{} micro(s)").format(len(ws)) + " · 📡 " + ", ".join(e.name() for e in live)
        return tone, sub, pill, [o.tone_color(t) for t in tones]

    def scene_devs(self, name):
        """[(n° du tinySA, en ligne ?)] qui surveillent cette scène : ceux qui lui sont rattachés, sinon tous."""
        o = self.owner
        devs = o.dev_list()
        att = [d for d in devs if name in o.dev_scenes.get(d, [])]
        return [(d, d < len(o.dev_live) and bool(o.dev_live[d])) for d in (att or devs)]

    def _refresh_base(self):
        o = self.owner
        th = o.theme
        for k, n in self.nodes.items():
            if n.kind == "scene":
                tone, sub, n.pill, n.dots = self.scene_state(n.name)
                sc = o.scene_by_name(n.name)
                n.col, n.sub = o.tone_color(tone), sub
                n.stripe = sc["color"] if sc else th["st_none"]
                n.title = n.name
            else:
                d = int(n.name)
                live = o.is_running() and d < len(o.dev_live) and bool(o.dev_live[d])
                n.title = o.dev_name(d)
                n.col = th["st_free"] if live else (th["st_occ"] if o.is_running() else th["st_none"])
                scs = o.dev_scenes.get(d, [])
                n.pill = TR("En ligne") if live else (TR("Perdu") if o.is_running() else TR("Arrêté"))
                cyc = o.dev_cycle.get(d) if live else None
                n.sub = f"{dev_ord(d)} tinySA" + (f" · {TR('tour de')} {cyc:.1f} s" if cyc and cyc >= 0.1 else "")
                n.extra = TR("Surveille : {}").format(", ".join(scs) if scs else TR("tout le site"))
                n.stripe = th["ui_accent"]
            n.update()
        self.update_links()

    def refresh(self):
        self._refresh_base()
        o, th = self.owner, self.owner.theme
        for k, n in self.nodes.items():
            if n.kind != "sdr":
                continue
            e = (getattr(o, "sdr_engs", None) or {}).get(int(n.name))
            live = _v8_post_live(e)
            n.title = f"📡 {e.name()}" if e else n.name
            n.col = th["st_free"] if live else (th["st_occ"] if e is not None and e.running() else th["st_none"])
            n.pill = TR("En ligne") if live else (TR("Pas de flux") if e is not None and e.running() else TR("Arrêté"))
            m = e.model() if e else None
            n.sub = (m["name"] if m else "SDR") + (f" · A {e.a:.3f}" if e is not None and e.a is not None else "")
            scs = e.post()["scenes"] if e else []
            n.extra = TR("Surveille : {}").format(", ".join(scs) if scs else TR("tout le site"))
            n.stripe = "#64d2ff"
            n.update()
        self._v8_sdr_links()

    def _update_links_base(self):
        for it in self.links:
            self.removeItem(it)
        self.links = []
        o = self.owner
        for d in o.dev_list():
            a = self.nodes.get(map_key("dev", d))
            if a is None:
                continue
            live = o.is_running() and d < len(o.dev_live) and bool(o.dev_live[d])
            for scn in o.dev_scenes.get(d, []):
                b = self.nodes.get(map_key("scene", scn))
                if b is None:
                    continue
                pa = a.port(False) if b.pos().y() >= a.pos().y() + a.h else a.port(True)
                pb = b.port(True) if b.pos().y() >= a.pos().y() + a.h else b.port(False)
                path = QtGui.QPainterPath(pa)
                dy = max(40.0, abs(pb.y() - pa.y()) / 2) * (1 if pb.y() >= pa.y() else -1)
                path.cubicTo(QtCore.QPointF(pa.x(), pa.y() + dy), QtCore.QPointF(pb.x(), pb.y() - dy), pb)
                pen = QtGui.QPen(QtGui.QColor(o.theme["ui_accent"]), 2.6)
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                if not live:
                    pen.setStyle(Qt.PenStyle.DashLine)
                it = self.addPath(path, pen)
                it.setZValue(5)
                self.links.append(it)
                for q in (pa, pb):                     # points d'accroche
                    dot = self.addEllipse(QtCore.QRectF(q.x() - 5, q.y() - 5, 10, 10),
                                          QtGui.QPen(QtGui.QColor(o.theme["ui_bg"]), 2.0),
                                          QtGui.QBrush(QtGui.QColor(o.theme["ui_accent"])))
                    dot.setZValue(12)
                    self.links.append(dot)

    def update_links(self):
        self._update_links_base()
        self._v8_sdr_links()

    # --- plan de fond (facultatif)
    def sync_bg(self):
        cfg = self.owner.map_cfg
        if self.bg_item is not None:
            self.removeItem(self.bg_item)
            self.bg_item = None
        if not cfg["bg"]:
            return
        pm = QtGui.QPixmap(cfg["bg"])
        if pm.isNull():
            return
        self.bg_item = self.addPixmap(pm)
        self.bg_item.setZValue(-10)
        self.bg_item.setOpacity(cfg["bg_op"])
        self.bg_item.setScale(cfg["bg_scale"])
        self.bg_item.setPos(QtCore.QPointF(*cfg["bg_pos"]))
        self.bg_item.setTransformationMode(Qt.TransformationMode.SmoothTransformation)

    # --- carte de chaleur
    def sync_heat(self):
        for it in self.heat_items:
            self.removeItem(it)
        self.heat_items = []
        if self.hot_item is not None:
            self.removeItem(self.hot_item)
            self.hot_item = None
        if not self.show_heat:
            return
        o = self.owner
        pts = heat_for(o.map_cfg["heat"], self.heat_f, 0.05)
        if not pts:
            return
        lo, hi = heat_scale([p["level"] for p in pts])
        # 1) le dégradé continu, calculé entre les points (une seule image lissée, sous les tuiles)
        cell = 8.0
        reach = float(o.map_cfg.get("heat_reach", HEAT_REACH))
        x0 = min(p["x"] for p in pts) - reach
        y0 = min(p["y"] for p in pts) - reach
        w = max(p["x"] for p in pts) + reach - x0
        h = max(p["y"] for p in pts) + reach - y0
        field, alpha = heat_field(pts, x0, y0, w, h, cell, reach)
        st = heat_stops(o.map_cfg.get("heat_pal", HEAT_PAL_DEFAULT), o.theme["ui_accent"])
        rgba = np.ascontiguousarray(heat_rgba(field, alpha, lo, hi, float(o.map_cfg.get("heat_op", 0.55)), st))
        img = QtGui.QImage(rgba.data, rgba.shape[1], rgba.shape[0], rgba.shape[1] * 4,
                           QtGui.QImage.Format.Format_RGBA8888).copy()
        pm = QtGui.QPixmap.fromImage(img.scaled(img.width() * 4, img.height() * 4,
                                                Qt.AspectRatioMode.IgnoreAspectRatio,
                                                Qt.TransformationMode.SmoothTransformation))
        it = self.addPixmap(pm)
        it.setTransformationMode(Qt.TransformationMode.SmoothTransformation)
        it.setScale(cell / 4.0)
        it.setPos(x0, y0)
        it.setZValue(-5)
        self.heat_items.append(it)
        th = o.theme
        # 1 bis) courbes de niveau tous les 5 dB (facultatif)
        if o.map_cfg.get("heat_iso", True) and len(pts) >= 2:
            ink = QtGui.QColor(th["ui_text"])
            for lev, segs in heat_isolines(field, alpha, x0, y0, cell, 5.0):
                path = QtGui.QPainterPath()
                for xa, ya, xb, yb in segs:
                    path.moveTo(xa, ya)
                    path.lineTo(xb, yb)
                c = QtGui.QColor(ink)
                c.setAlphaF(0.30)
                pen = QtGui.QPen(c, 1.1)
                pen.setCosmetic(True)
                li = self.addPath(path, pen)
                li.setZValue(-4.6)
                li.setToolTip(TR("Courbe de niveau : {}").format(o.lvl(lev, suffix=True)))
                self.heat_items.append(li)
        # 1 ter) parcours de la chasse (facultatif) : trace fine et lissée, plus nette vers les derniers points
        if o.map_cfg.get("heat_path", False) and len(pts) >= 2:
            route = heat_path(pts)
            n = len(route)
            for k in range(n - 1):
                p0 = route[max(0, k - 1)]
                p1, p2 = route[k], route[k + 1]
                p3 = route[min(n - 1, k + 2)]
                path = QtGui.QPainterPath(QtCore.QPointF(*p1))
                path.cubicTo(QtCore.QPointF(p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6),
                             QtCore.QPointF(p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6),
                             QtCore.QPointF(*p2))
                c = QtGui.QColor(th["ui_text"])
                c.setAlphaF(0.12 + 0.43 * (k + 1) / (n - 1))
                pen = QtGui.QPen(c, float(o.map_cfg.get("heat_trail", 2.0)), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)
                pen.setCosmetic(True)
                li = self.addPath(path, pen)
                li.setZValue(-4.5)
                li.setToolTip(TR("Parcours de la chasse (dans l'ordre des points)"))
                self.heat_items.append(li)
        # 2) les points de mesure : petits, nets, avec leur niveau
        hot = heat_hot(pts)
        font = QtGui.QFont(self.font())
        font.setPointSizeF(8.5)
        font.setBold(True)
        fm = QtGui.QFontMetricsF(font)
        for p in pts:
            r_, g_, b_ = heat_rgb(p["level"], lo, hi, st)
            is_hot = p is hot
            rad = (6.5 if is_hot else 4.5) * float(o.map_cfg.get("heat_dot", 1.0))
            dot = self.addEllipse(QtCore.QRectF(p["x"] - rad, p["y"] - rad, 2 * rad, 2 * rad),
                                  QtGui.QPen(QtGui.QColor(blend(th["ui_text"], th["ui_bg"], 0.65)), 1.4),
                                  QtGui.QBrush(QtGui.QColor(r_, g_, b_)))
            dot.setZValue(-4)
            when = datetime.fromtimestamp(p["t"]).strftime("%H:%M:%S") if p.get("t") else ""
            dot.setToolTip(f"{o.lvl(p['level'], suffix=True)} · {p['f']:.3f} MHz · {when}")
            self.heat_items.append(dot)
            if not (is_hot or o.map_cfg.get("heat_labels", True)):
                continue                       # niveaux écrits : le plus fort seulement
            txt = fmt_level(p["level"], o.unit, 0, False)
            tw = fm.horizontalAdvance(txt) + 10
            box = QtCore.QRectF(p["x"] - tw / 2, p["y"] + (rad * 2.3 if is_hot else rad + 3), tw, fm.height() + 2)
            path = QtGui.QPainterPath()
            path.addRoundedRect(box, 6, 6)
            bg = self.addPath(path, QtGui.QPen(Qt.PenStyle.NoPen),
                              QtGui.QBrush(QtGui.QColor(r_, g_, b_) if is_hot else QtGui.QColor(th["ui_base"])))
            bg.setOpacity(0.92)
            bg.setZValue(-3.9)
            lab = self.addSimpleText(txt, font)
            lab.setBrush(QtGui.QColor("#111111" if is_hot else th["ui_text"]))
            lab.setPos(box.left() + 5, box.top() + 1)
            lab.setZValue(-3.8)
            self.heat_items += [bg, lab]
        if hot is not None:
            hr = 13 * float(o.map_cfg.get("heat_dot", 1.0))
            self.hot_item = self.addEllipse(QtCore.QRectF(hot["x"] - hr, hot["y"] - hr, 2 * hr, 2 * hr),
                                            QtGui.QPen(QtGui.QColor(*heat_rgb(hot["level"], lo, hi, st)), 2.0))
            self.hot_item.setZValue(-3)
            self.hot_item.setToolTip(TR("Le plus fort : {} dBm").format(f"{hot['level']:.1f}"))
        # 3) « par là » (facultatif) : « tu es ici » sur le dernier point + chevrons ››› vers le plus fort + « +N dB »
        self.arrow_info = heat_arrow(pts) if o.map_cfg.get("heat_arrow", True) else None
        ar = self.arrow_info
        if ar:
            acc = QtGui.QColor(heat_dir_color(o.map_cfg.get("heat_dir", "accent"), th["ui_accent"],
                                              heat_rgb(hot["level"], lo, hi, st) if hot else None))
            last = max(pts, key=lambda p_: float(p_.get("t") or 0.0))
            lx, ly = float(last["x"]), float(last["y"])
            halo = QtGui.QRadialGradient(QtCore.QPointF(lx, ly), 22)
            c0, c1 = QtGui.QColor(acc), QtGui.QColor(acc)
            c0.setAlphaF(0.32)
            c1.setAlphaF(0.0)
            halo.setColorAt(0.0, c0)
            halo.setColorAt(1.0, c1)
            items = [self.addEllipse(QtCore.QRectF(lx - 22, ly - 22, 44, 44), QtGui.QPen(Qt.PenStyle.NoPen),
                                     QtGui.QBrush(halo)),
                     self.addEllipse(QtCore.QRectF(lx - 9, ly - 9, 18, 18), QtGui.QPen(acc, 2.0))]
            if ar.get("here"):
                tip = TR("📍 Ta dernière mesure est la plus forte : cherche autour d'ici")
            else:
                ang = math.atan2(ar["y1"] - ar["y0"], ar["x1"] - ar["x0"])
                ux, uy = math.cos(ang), math.sin(ang)
                for k, (d, a_) in enumerate(((27, 0.95), (42, 0.65), (57, 0.35))):
                    cx, cy = lx + ux * d, ly + uy * d
                    path = QtGui.QPainterPath(QtCore.QPointF(cx - ux * 6 - uy * 8, cy - uy * 6 + ux * 8))
                    path.lineTo(cx + ux * 2, cy + uy * 2)
                    path.lineTo(cx - ux * 6 + uy * 8, cy - uy * 6 - ux * 8)
                    c = QtGui.QColor(acc)
                    c.setAlphaF(a_)
                    pen = QtGui.QPen(c, 3.0, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
                    items.append(self.addPath(path, pen))
                txt = f"+{ar['gain']:.0f} dB"
                fnt = QtGui.QFont(self.font())
                fnt.setPointSizeF(8.5)
                fnt.setBold(True)
                fm2 = QtGui.QFontMetricsF(fnt)
                tw, tht = fm2.horizontalAdvance(txt) + 12, fm2.height() + 3
                cx, cy = lx + ux * 80, ly + uy * 80
                box = QtCore.QRectF(cx - tw / 2, cy - tht / 2, tw, tht)
                pp = QtGui.QPainterPath()
                pp.addRoundedRect(box, tht / 2, tht / 2)
                items.append(self.addPath(pp, QtGui.QPen(Qt.PenStyle.NoPen), QtGui.QBrush(acc)))
                lab = self.addSimpleText(txt, fnt)
                lab.setBrush(QtGui.QColor("#111111" if acc.lightnessF() > 0.62 else "#ffffff"))
                lab.setPos(box.left() + 6, box.top() + 1.5)
                items.append(lab)
                tip = TR("Par là : le point le plus fort est {} dB au-dessus de ta dernière mesure").format(f"{ar['gain']:.0f}")
            for it in items:
                it.setZValue(-3.5)
                it.setToolTip(tip)
                self.heat_items.append(it)

    # --- glisser-déposer
    def _node_dropped_base(self, n):
        o = self.owner
        p = map_snap(n.pos().x(), n.pos().y())
        n.setPos(QtCore.QPointF(*p))
        o.map_cfg["pos"][n.key] = p
        if n.kind == "dev":                    # tinySA posé SUR une scène = rattaché à elle
            for k, m in self.nodes.items():
                if m.kind == "scene" and m.sceneBoundingRect().intersects(n.sceneBoundingRect()):
                    d = int(n.name)
                    if m.name not in o.dev_scenes.get(d, []):
                        o.toggle_dev_scene(d, m.name, True)
                        o.set_status(TR("📡 {} surveille maintenant « {} » (glissé sur la carte).").format(
                            self.label(n.key), m.name))
                    n.setPos(QtCore.QPointF(p[0], m.pos().y() + m.h + MAP_STEP))
                    o.map_cfg["pos"][n.key] = [n.pos().x(), n.pos().y()]
                    break
        self.refresh()

    def node_dropped(self, n):
        if n.kind != "sdr":
            return self._node_dropped_base(n)
        o = self.owner
        p = map_snap(n.pos().x(), n.pos().y())
        n.setPos(QtCore.QPointF(*p))
        o.map_cfg["pos"][n.key] = p
        for _k, m in self.nodes.items():                   # SDR posé SUR une scène = il la surveille
            if m.kind == "scene" and m.sceneBoundingRect().intersects(n.sceneBoundingRect()):
                ps = sdr_posts_norm(o.sdr_cfg.get("posts"))
                for pp in ps:
                    if pp["id"] == int(n.name) and m.name not in pp["scenes"]:
                        pp["scenes"].append(m.name)
                        o.sdr_cfg["posts"] = ps
                        o._sdr_posts_sync()
                        o.set_status(TR("📡 {} surveille maintenant « {} » (glissé sur la carte).").format(
                            self.label(n.key), m.name))
                n.setPos(QtCore.QPointF(p[0], m.pos().y() + m.h + MAP_STEP))
                o.map_cfg["pos"][n.key] = [n.pos().x(), n.pos().y()]
                break
        self.refresh()

    def _node_open_base(self, n):
        o = self.owner
        if n.kind == "scene":
            o.set_scope([(n.name, None)])
            o.set_status(TR("🗺 Vue sur « {} » (liste et spectre).").format(n.name))
        else:
            o.open_devices()

    def node_open(self, n):
        if n.kind != "sdr":
            return self._node_open_base(n)
        o = self.owner
        pid = int(n.name)
        if o.rf_mode == "tiny":
            o.set_rf_mode("sdr")
        for d in o.post_docks.get(pid, {}).values():
            if d.isHidden() and d is not o.post_docks[pid].get("wf"):
                d.show()
            d.raise_()
        e = o.sdr_engs.get(pid)
        if e is not None and not e.running():
            e.start()

    def mark(self, x, y, who=""):
        """📍 Point de chaleur à (x, y) avec le niveau actuel de la chasse. -> point, ou None (pas de chasse en cours)."""
        o = self.owner
        h = o._hunt
        if h is None or not h.go_btn.isChecked() or h.level is None:
            return None
        pt = dict(x=round(float(x), 1), y=round(float(y), 1), level=round(float(h.level), 1),
                  f=round(float(h.f_spin.value()), 4), t=time.time())
        o.map_cfg["heat"].append(pt)
        del o.map_cfg["heat"][:-HEAT_MAX]
        self.heat_f = pt["f"]
        self.sync_heat()
        return pt


class MapView(QtWidgets.QGraphicsView):
    """Vue de la carte : grille en points, molette = zoom, glisser le fond = se déplacer, clic pendant une chasse = point noté."""

    def __init__(self, sc, win):
        super().__init__(sc)
        self.win = win
        self.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        self.setDragMode(QtWidgets.QGraphicsView.DragMode.ScrollHandDrag)
        self.setTransformationAnchor(QtWidgets.QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        for pol in (self.setHorizontalScrollBarPolicy, self.setVerticalScrollBarPolicy):
            pol(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)      # on se déplace en glissant le fond
        self.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.setToolTip("Glisse les tuiles pour les placer · dépose un tinySA sur une scène pour la lui rattacher ·\n"
                        "molette = zoom · glisser le fond = se déplacer · double-clic sur une scène = la voir · clic droit = options")

    def drawBackground(self, p, rect):
        th = self.win.owner.theme
        p.fillRect(rect, QtGui.QColor(th["ui_bg"]))
        if not self.win.owner.map_cfg.get("grid", True):
            return
        step = MAP_STEP if self.transform().m11() >= 0.45 else MAP_STEP * 3
        p.setPen(QtGui.QPen(QtGui.QColor(blend(th["ui_text"], th["ui_bg"], 0.22)), 2.2))
        pts = []
        x0 = math.floor(rect.left() / step) * step
        y = math.floor(rect.top() / step) * step
        while y < rect.bottom():
            x = x0
            while x < rect.right():
                pts.append(QtCore.QPointF(x, y))
                x += step
            y += step
        if len(pts) < 40000:                   # grille en points discrets (façon canevas)
            p.drawPoints(pts)

    def wheelEvent(self, e):
        k = 1.15 if e.angleDelta().y() > 0 else 1 / 1.15
        if self.win.bg_move.isChecked() and e.modifiers() & Qt.KeyboardModifier.ControlModifier:
            self.win.wheel_bg(k)                   # Ctrl + molette : agrandir / réduire le plan
            return
        sc = self.transform().m11() * k
        if 0.15 <= sc <= 4.0:
            self.scale(k, k)

    def mousePressEvent(self, e):
        self._press = e.position().toPoint()
        super().mousePressEvent(e)

    def mouseReleaseEvent(self, e):
        super().mouseReleaseEvent(e)
        p0 = getattr(self, "_press", None)
        pos = e.position().toPoint()
        if (p0 is not None and e.button() == Qt.MouseButton.LeftButton and self.win.marking()
                and (pos - p0).manhattanLength() < 6 and not isinstance(self.itemAt(pos), MapNode)):
            pt = self.mapToScene(pos)          # un simple clic (pas un glisser) pendant la chasse = point noté
            self.win.mark_at(pt.x(), pt.y())
        self._press = None

    def contextMenuEvent(self, e):
        it = self.itemAt(e.pos())
        self.win.context_menu(it if isinstance(it, MapNode) else None, self.mapToScene(e.pos()), e.globalPos())


class MapHeatLegend(QtWidgets.QWidget):
    """Légende de la carte de chaleur (posée sur la carte, en bas à gauche) : dégradé bleu → rouge + niveaux."""

    def __init__(self, parent, owner):
        super().__init__(parent)
        self.owner, self.lo, self.hi, self.n = owner, -100.0, -40.0, 0
        self.setFixedSize(230, 54)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

    def set_range(self, lo, hi, n):
        self.lo, self.hi, self.n = lo, hi, n
        self.setVisible(n > 0)
        self.update()

    def paintEvent(self, e):
        th = self.owner.theme
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        card = blend(th["ui_text"], th["ui_base"], 0.05)
        p.setPen(QtGui.QPen(QtGui.QColor(blend(th["ui_text"], card, 0.18)), 1.0))
        p.setBrush(QtGui.QColor(card))
        p.drawRoundedRect(QtCore.QRectF(0.5, 0.5, self.width() - 1, self.height() - 1), 10, 10)
        g = QtGui.QLinearGradient(12, 0, self.width() - 12, 0)
        st = heat_stops(self.owner.map_cfg.get("heat_pal", HEAT_PAL_DEFAULT), th["ui_accent"])
        for t in (0.0, 0.25, 0.5, 0.75, 1.0):
            g.setColorAt(t, QtGui.QColor(*heat_rgb(self.lo + t * (self.hi - self.lo), self.lo, self.hi, st)))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QBrush(g))
        p.drawRoundedRect(QtCore.QRectF(12, 26, self.width() - 24, 10), 5, 5)
        f = QtGui.QFont(self.font())
        f.setPointSizeF(8.5)
        p.setFont(f)
        p.setPen(QtGui.QColor(th["ui_text"]))
        p.drawText(QtCore.QRectF(12, 4, self.width() - 24, 20), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   TR("🔥 Chaleur · {} point(s)").format(self.n))
        sub = QtGui.QColor(blend(th["ui_text"], card, 0.62))
        p.setPen(sub)
        p.drawText(QtCore.QRectF(12, 36, 90, 16), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   f"{self.lo:.0f} dBm")
        p.drawText(QtCore.QRectF(self.width() - 102, 36, 90, 16), Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                   f"{self.hi:.0f} dBm")


class MapWindow(QtWidgets.QWidget):
    """🗺 7.64 Carte du site, vraie fenêtre épurée : la carte prend toute la place ; scènes et tinySA posés tout seuls
    (on les déplace ensuite), barre fine (🖼 Plan, 🔥 Chaleur, ⋯), bulle d'aide flottante, zoom et légende sur la carte.
    Pendant une 🔎 chasse, un simple clic sur la carte note le niveau à cet endroit (carte de chaleur)."""

    def __init__(self, owner):
        super().__init__(owner, Qt.WindowType.Window)
        self.owner = o = owner
        self.setWindowTitle("Carte du site")
        self.heat_on, self._hint, self._hint_t = True, "", 0.0
        lay = QtWidgets.QVBoxLayout(self)
        lay.setContentsMargins(8, 8, 8, 8)
        lay.setSpacing(6)
        # --- 🖼 Plan (facultatif)
        self.plan_btn = QtWidgets.QToolButton()
        self.plan_btn.setText("🖼 Plan")
        self.plan_btn.setPopupMode(QtWidgets.QToolButton.ToolButtonPopupMode.InstantPopup)
        self.plan_btn.setToolTip("Facultatif : une image du plan du site sous les tuiles. Sans plan, la grille suffit.")
        pm = QtWidgets.QMenu(self.plan_btn)
        pm.addAction("Choisir une image…").triggered.connect(lambda *_: self.pick_bg())
        ow = QtWidgets.QWidget()
        ol = QtWidgets.QHBoxLayout(ow)
        ol.setContentsMargins(12, 4, 12, 4)
        ol.addWidget(QtWidgets.QLabel("Opacité"))
        self.op = QtWidgets.QSlider(Qt.Orientation.Horizontal)
        self.op.setRange(5, 100)
        self.op.setValue(int(o.map_cfg["bg_op"] * 100))
        self.op.setMinimumWidth(140)
        self.op.setToolTip("Transparence du plan de fond.")
        self.op.valueChanged.connect(lambda v: self._bg_param(bg_op=v / 100.0))
        ol.addWidget(self.op)
        wa = QtWidgets.QWidgetAction(pm)
        wa.setDefaultWidget(ow)
        pm.addAction(wa)
        self.bg_move = pm.addAction("Caler le plan (déplacer, Ctrl + molette = taille)")
        self.bg_move.setCheckable(True)
        self.bg_move.triggered.connect(lambda *_: self._bg_movable())
        pm.addSeparator()
        pm.addAction("Retirer le plan").triggered.connect(lambda *_: self.set_bg(""))
        self.plan_btn.setMenu(pm)
        # --- 🔥 Chaleur
        self.heat_btn = QtWidgets.QToolButton()
        self.heat_btn.setText("🔥 Chaleur")
        self.heat_btn.setPopupMode(QtWidgets.QToolButton.ToolButtonPopupMode.InstantPopup)
        self.heat_btn.setToolTip("Carte de chaleur de la chasse au brouilleur : bleu = faible, rouge = là où ça crie le plus.")
        self.heat_menu = QtWidgets.QMenu(self.heat_btn)
        self.heat_menu.aboutToShow.connect(self._build_heat_menu)
        self.heat_btn.setMenu(self.heat_menu)
        # --- infos, tout voir, ⋯
        self.count_lbl = QtWidgets.QLabel("")
        self.count_lbl.setStyleSheet(f"color:{blend(o.theme['ui_text'], o.theme['ui_bg'], 0.6)}")
        fit = QtWidgets.QPushButton("⤢ Tout voir")
        fit.setToolTip("Recadre la vue sur toutes les tuiles.")
        fit.clicked.connect(lambda *_: self.fit())
        more = QtWidgets.QToolButton()
        more.setText("⋯")
        more.setPopupMode(QtWidgets.QToolButton.ToolButtonPopupMode.InstantPopup)
        more.setToolTip("Plus d'options : grille, réorganiser, exporter.")
        mm = QtWidgets.QMenu(more)
        self.grid_act = mm.addAction("Grille")
        self.grid_act.setCheckable(True)
        self.grid_act.setChecked(o.map_cfg.get("grid", True))
        self.grid_act.triggered.connect(lambda *_: (o.map_cfg.__setitem__("grid", self.grid_act.isChecked()),
                                                    self.view.viewport().update()))
        mm.addAction("Réorganiser automatiquement").triggered.connect(lambda *_: self.relayout())
        mm.addSeparator()
        mm.addAction("Exporter en PNG…").triggered.connect(lambda *_: self.export_png())
        more.setMenu(mm)
        bar = QtWidgets.QHBoxLayout()
        bar.setSpacing(6)
        for w_ in (self.plan_btn, self.heat_btn):
            bar.addWidget(w_)
        bar.addStretch(1)
        bar.addWidget(self.count_lbl)
        bar.addWidget(fit)
        bar.addWidget(more)
        lay.addLayout(bar)
        # --- la carte
        self.view = MapView(o.map_scene(), self)
        lay.addWidget(self.view, 1)
        self.zoom_box = QtWidgets.QWidget(self.view)     # zoom (en haut à droite)
        zb = QtWidgets.QVBoxLayout(self.zoom_box)
        zb.setContentsMargins(0, 0, 0, 0)
        zb.setSpacing(4)
        for txt, tip, k in (("+", "Zoomer", 1.2), ("−", "Dézoomer", 1 / 1.2)):
            b = QtWidgets.QToolButton()
            b.setText(txt)
            b.setToolTip(tip)
            b.setFixedSize(32, 32)
            b.clicked.connect(lambda *_, k=k: self.view.scale(k, k))
            zb.addWidget(b)
        self.legend = MapHeatLegend(self.view, o)       # légende de chaleur (en bas à gauche)
        self.banner = QtWidgets.QLabel("", self.view)   # bulle d'aide (en haut, au centre)
        self.banner.setWordWrap(True)
        self.banner.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.banner.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.banner.hide()
        self.view.installEventFilter(self)
        self.resize(1100, 720)
        fit_dialog(self, 1100, 720)
        self.timer = QtCore.QTimer(self)
        self.timer.setInterval(1000)
        self.timer.timeout.connect(self.tick)
        self.timer.start()
        o.map_scene().sync()
        self.fill_heat()
        self.tick()
        QtCore.QTimer.singleShot(50, lambda: (self.fit(), self._place_overlays()))

    # --- aide flottante
    def hint(self, txt, secs=6.0):
        self._hint, self._hint_t = txt, time.time() + secs
        self._show_banner()

    def _show_banner(self):
        o = self.owner
        th = o.theme
        if self.marking():
            h = o._hunt
            txt = TR("🔎 Chasse en cours sur {} MHz · clique sur la carte là où tu es : le niveau y est noté").format(
                f"{h.f_spin.value():.3f}")
            ar = o.map_scene().arrow_info
            if ar and ar.get("here"):
                txt += "\n" + TR("📍 Ta dernière mesure est la plus forte : cherche autour d'ici")
            elif ar:
                txt += "\n" + TR("››› Va dans la direction des chevrons : environ {} dB de plus vers le point le plus fort").format(f"{ar['gain']:.0f}")
            col = th["ui_accent"]
        elif self._hint and time.time() < self._hint_t:
            txt, col = self._hint, th["ui_text"]
        else:
            self.banner.hide()
            return
        self.banner.setText(txt)
        self.banner.setStyleSheet(soft_style(col, th["ui_base"], th["ui_text"]) + "; padding:8px 14px; border-radius:14px")
        fm = self.banner.fontMetrics()
        tw = max(fm.horizontalAdvance(l_) for l_ in txt.split("\n")) + 40
        self.banner.setFixedWidth(max(200, min(tw, self.view.width() - 120)))
        self.banner.adjustSize()
        self.banner.show()
        self._place_overlays()

    def marking(self):
        h = self.owner._hunt
        try:
            return h is not None and h.go_btn.isChecked()
        except RuntimeError:
            return False

    # --- placement
    def relayout(self):
        o = self.owner
        o.map_cfg["pos"] = {}
        o.map_scene().auto_place()
        self.fit()

    def fit(self):
        """Cadre sur les tuiles (pas sur le plan de fond, souvent bien plus grand), zoom 1:1 au plus."""
        sc = self.owner.map_scene()
        r = QtCore.QRectF()
        for n in sc.nodes.values():
            r = r.united(n.sceneBoundingRect())
        for it in sc.heat_items:
            r = r.united(it.sceneBoundingRect())
        if r.isEmpty():
            r = sc.itemsBoundingRect()
        if r.isEmpty():
            r = QtCore.QRectF(-200, -150, 800, 500)
        self.view.resetTransform()
        self.view.fitInView(r.adjusted(-80, -150, 80, 80), Qt.AspectRatioMode.KeepAspectRatio)   # place pour la bulle
        if self.view.transform().m11() > 1.0:
            self.view.resetTransform()
            self.view.centerOn(r.center())

    def eventFilter(self, obj, e):
        if obj is self.view and e.type() == QtCore.QEvent.Type.Resize:
            self._place_overlays()
        return super().eventFilter(obj, e)

    def _place_overlays(self):
        vw = self.view.viewport().geometry()
        self.zoom_box.adjustSize()
        self.zoom_box.move(vw.right() - self.zoom_box.width() - 10, vw.top() + 10)
        self.legend.move(vw.left() + 10, vw.bottom() - self.legend.height() - 10)
        if self.banner.isVisible():
            self.banner.move(vw.left() + (vw.width() - self.banner.width()) // 2, vw.top() + 10)
        for w_ in (self.zoom_box, self.legend, self.banner):
            w_.raise_()

    # --- plan de fond
    def pick_bg(self, path=None):
        if path is None:
            path, _ = QtWidgets.QFileDialog.getOpenFileName(self, "Plan du site (image)", "",
                                                            "Images (*.png *.jpg *.jpeg *.bmp *.gif)")
            if not path:
                return False
        if QtGui.QPixmap(path).isNull():
            self.hint(TR("Image illisible."))
            return False
        self.set_bg(path)
        return True

    def set_bg(self, path):
        o = self.owner
        o.map_cfg["bg"] = path
        if path:
            pm = QtGui.QPixmap(path)
            r = QtCore.QRectF()
            for n in o.map_scene().nodes.values():
                r = r.united(n.sceneBoundingRect())
            w0 = max(r.width() + 200, 1200.0)
            o.map_cfg["bg_scale"] = round(w0 / max(1, pm.width()), 3)
            o.map_cfg["bg_pos"] = [r.left() - 100 if not r.isEmpty() else -200.0, r.top() - 100 if not r.isEmpty() else -150.0]
        o.map_scene().sync_bg()
        self._bg_movable()
        if path:
            self.hint(TR("Plan posé. 🖼 Plan › « Caler le plan » pour l'ajuster sous tes tuiles."))
        self.fit()

    def _bg_param(self, **kw):
        self.owner.map_cfg.update(kw)
        it = self.owner.map_scene().bg_item
        if it is not None and "bg_op" in kw:
            it.setOpacity(kw["bg_op"])

    def _bg_movable(self):
        it = self.owner.map_scene().bg_item
        if it is None:
            return
        on = self.bg_move.isChecked()
        it.setFlag(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsMovable, on)
        it.setZValue(20 if on else -10)
        if on:
            self.hint(TR("Glisse le plan, Ctrl + molette pour l'agrandir. Décoche « Caler le plan » pour le figer."), 10.0)

    def wheel_bg(self, k):
        o = self.owner
        it = o.map_scene().bg_item
        if it is not None:
            o.map_cfg["bg_scale"] = min(20.0, max(0.02, o.map_cfg["bg_scale"] * k))
            it.setScale(o.map_cfg["bg_scale"])

    # --- chaleur
    def _build_heat_menu(self):
        o = self.owner
        m = self.heat_menu
        m.clear()
        a = m.addAction("Afficher la carte de chaleur")
        a.setCheckable(True)
        a.setChecked(self.heat_on)
        a.triggered.connect(lambda *_, a=a: self._heat(a.isChecked()))
        m.addSection(TR("Apparence"))
        cm = m.addMenu(TR("🎨 Couleurs"))
        for k, name, _st in HEAT_PALETTES:
            b = cm.addAction(name)
            b.setCheckable(True)
            b.setChecked(o.map_cfg.get("heat_pal", HEAT_PAL_DEFAULT) == k)
            b.triggered.connect(lambda *_, k=k: self.set_heat_opt("heat_pal", k))
        ow = QtWidgets.QWidget()
        ol = QtWidgets.QHBoxLayout(ow)
        ol.setContentsMargins(12, 4, 12, 4)
        ol.addWidget(QtWidgets.QLabel(TR("Intensité")))
        sl = QtWidgets.QSlider(Qt.Orientation.Horizontal)
        sl.setRange(10, 95)
        sl.setValue(int(round(float(o.map_cfg.get("heat_op", 0.55)) * 100)))
        sl.setMinimumWidth(150)
        sl.setToolTip(TR("Plus ou moins opaque : à baisser pour bien voir le plan de fond sous la chaleur."))
        sl.valueChanged.connect(lambda v: self.set_heat_opt("heat_op", v / 100.0))
        ol.addWidget(sl)
        wa = QtWidgets.QWidgetAction(m)
        wa.setDefaultWidget(ow)
        m.addAction(wa)
        self.heat_slider = sl
        for title, key, opts in (("Taille des points", "heat_dot", HEAT_DOT_SIZES),
                                 ("Épaisseur du parcours", "heat_trail", HEAT_TRAIL_WIDTHS),
                                 ("Couleur de la direction", "heat_dir", tuple((v, t) for v, t in HEAT_DIR_COLORS))):
            sub = m.addMenu(TR(title))
            cur = o.map_cfg.get(key, MAP_DEFAULT[key])
            for v, txt in opts:
                b = sub.addAction(TR(txt))
                if isinstance(v, str) and v.startswith("#"):
                    pm = QtGui.QPixmap(12, 12)
                    pm.fill(QtGui.QColor(v))
                    b.setIcon(QtGui.QIcon(pm))
                b.setCheckable(True)
                b.setChecked(cur == v if isinstance(v, str) else abs(float(cur) - v) < 1e-6)
                b.triggered.connect(lambda *_, key=key, v=v: self.set_heat_opt(key, v))
        m.addSection(TR("Sur la carte"))
        for key, txt in (("heat_labels", "Niveaux écrits sur les points"),
                         ("heat_iso", "Courbes de niveau (tous les 5 dB)"),
                         ("heat_arrow", "Direction « par là » (vers le plus fort)"),
                         ("heat_path", "Parcours de la chasse")):
            b = m.addAction(txt)
            b.setCheckable(True)
            b.setChecked(bool(o.map_cfg.get(key, MAP_DEFAULT[key])))
            b.triggered.connect(lambda *_, key=key, b=b: self.set_heat_opt(key, b.isChecked()))
        sub = m.addMenu(TR("Étalement du dégradé"))
        for r, txt in zip(HEAT_REACHES, ("Serré (points rapprochés)", "Normal", "Large (points espacés)")):
            b = sub.addAction(txt)
            b.setCheckable(True)
            b.setChecked(abs(float(o.map_cfg.get("heat_reach", HEAT_REACH)) - r) < 1)
            b.triggered.connect(lambda *_, r=r: self.set_heat_opt("heat_reach", r))
        fs = heat_freqs(o.map_cfg["heat"])
        if fs:
            m.addSection(TR("Fréquence chassée"))
            cur = o.map_scene().heat_f
            for f in [None] + fs:
                b = m.addAction(TR("Toutes les fréquences") if f is None else f"{f:.3f} MHz")
                b.setCheckable(True)
                b.setChecked(cur == f)
                b.triggered.connect(lambda *_, f=f: self._set_heat_f(f))
            m.addSeparator()
            m.addAction("Effacer les points affichés").triggered.connect(lambda *_: self.clear_heat())
        m.addSeparator()
        m.addAction("Comment noter des points ?").triggered.connect(lambda *_: self.hint(TR(
            "Lance une 🔎 chasse au brouilleur, puis clique sur la carte là où tu es (PC portable), ou sur le téléphone : "
            "vue 🔎 Chasse › « Où suis-je ? »."), 12.0))

    def set_heat_opt(self, key, val):
        """Affichages de la chaleur (couleurs, intensité, niveaux, courbes, direction, parcours, étalement) : chacun se
        règle / se coupe à part ; gardé avec le show, et l'image du téléphone suit."""
        self.owner.map_cfg[key] = val
        self._heat(self.heat_on)
        self.legend.update()

    def _set_heat_f(self, f):
        self.owner.map_scene().heat_f = f
        self._heat(True)

    def fill_heat(self):
        """Après un nouveau point : on montre la fréquence chassée."""
        sc = self.owner.map_scene()
        fs = heat_freqs(self.owner.map_cfg["heat"])
        if sc.heat_f is not None and round(sc.heat_f, 3) not in fs:
            sc.heat_f = fs[0] if fs else None
        self._heat(self.heat_on)

    def _heat(self, on):
        self.heat_on = bool(on)
        sc = self.owner.map_scene()
        sc.show_heat = self.heat_on
        sc.sync_heat()
        pts = heat_for(self.owner.map_cfg["heat"], sc.heat_f, 0.05)
        lo, hi = heat_scale([p_["level"] for p_ in pts])
        self.legend.set_range(lo, hi, len(pts) if self.heat_on else 0)
        self._place_overlays()

    def mark_at(self, x, y):
        pt = self.owner.map_scene().mark(x, y)
        if pt is None:
            self.hint(TR("📍 Lance d'abord la chasse au brouilleur (🎚 Surveiller › 🔎) : le point note son niveau."))
            return None
        self.fill_heat()
        self.hint(TR("📍 Point noté : {} à {} MHz.").format(self.owner.lvl(pt["level"], suffix=True), f"{pt['f']:.3f}"), 3.0)
        return pt

    def clear_heat(self):
        o = self.owner
        f = o.map_scene().heat_f
        o.map_cfg["heat"] = [p for p in o.map_cfg["heat"] if f is not None and abs(p["f"] - f) > 0.05]
        o.map_scene().heat_f = None
        self.fill_heat()

    # --- menu des tuiles
    def context_menu(self, node, pt, gpos):
        o = self.owner
        m = QtWidgets.QMenu(self)
        acts = {}
        if node is not None and node.kind == "dev":
            d = int(node.name)
            sub = m.addMenu("📡 Surveille…")
            for sc in o.scenes:
                a = sub.addAction(sc["name"])
                a.setCheckable(True)
                a.setChecked(sc["name"] in o.dev_scenes.get(d, []))
                a.triggered.connect(lambda *_, n=sc["name"], a=a: (o.toggle_dev_scene(d, n, a.isChecked()),
                                                                   o.map_scene().refresh()))
            acts[m.addAction("🌐 Tout le site (aucune scène)")] = lambda: (o.set_dev_scenes(d, []), o.map_scene().refresh())
            acts[m.addAction("👋 Identifier ce tinySA")] = lambda: o.identify_device(d)
        if node is not None and node.kind == "scene":
            acts[m.addAction("🔍 Voir cette scène (liste et spectre)")] = lambda: o.map_scene().node_open(node)
        if node is None:
            acts[m.addAction("📍 Noter le niveau de la chasse ici")] = lambda: self.mark_at(pt.x(), pt.y())
            acts[m.addAction("⤢ Tout voir")] = lambda: self.fit()
        act = m.exec(gpos)
        if act in acts:
            acts[act]()

    def tick(self):
        if not self.isVisible():
            return
        o = self.owner
        sc = o.map_scene()
        if sc.unplaced():                      # nouvelle scène / nouveau tinySA : posé tout seul
            sc.auto_place()
        elif set(sc.keys_all()) != set(sc.nodes):
            sc.sync()
        else:
            sc.refresh()
        ns = sum(1 for n in sc.nodes.values() if n.kind == "scene")
        self.count_lbl.setText(TR("{} scène(s) · {} tinySA").format(ns, len(sc.nodes) - ns))
        self.view.setCursor(Qt.CursorShape.CrossCursor if self.marking() else Qt.CursorShape.ArrowCursor)
        self._show_banner()

    def export_png(self, path=None):
        if path is None:
            path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Exporter la carte", "carte_site.png", "Image PNG (*.png)")
            if not path:
                return False
        data, _r = self.owner.map_png(1800)
        if not data:
            return False
        Path(path).write_bytes(data)
        return True

    def closeEvent(self, e):
        bg = self.owner.map_scene().bg_item
        if bg is not None:                    # position du plan déplacé gardée
            self.owner.map_cfg["bg_pos"] = [bg.pos().x(), bg.pos().y()]
        super().closeEvent(e)


def spectrum_qimage(F, L, w=1600, h=560, thr=None, marks=(), tv=()):
    """Image du spectre pour le dossier de préparation (QPainter seul, sans pyqtgraph). 7.67.1 (PDF de Clément :
    spectre minuscule, 48 traits par-dessus, grand vide 700-820 MHz) : axe COUPÉ (axis_panels : une case par groupe de
    bandes, coupure grise entre deux), fréquences du plan = petits repères en haut, canaux TV grisés et numérotés.
    marks = [(MHz, nom)] ; tv = [(début, fin, canal)]."""
    img = QtGui.QImage(w, h, QtGui.QImage.Format.Format_RGB32)
    img.fill(QtGui.QColor("#ffffff"))
    F = np.asarray(F, dtype=float)
    L = np.asarray(L, dtype=float)
    ok = np.isfinite(F) & np.isfinite(L)
    if ok.sum() < 2:
        return img
    F, L = F[ok], L[ok]
    o = np.argsort(F)
    F, L = F[o], L[o]
    panels = axis_panels(scan_segments(F))
    y0 = math.floor((min(float(np.percentile(L, 1)), thr if thr is not None else 0) - 5) / 10.0) * 10
    y1 = math.ceil((float(L.max()) + 5) / 10.0) * 10
    ml, mr, mt, mb, brk = 62, 14, 34, 40, 18
    pw, ph = w - ml - mr - brk * (len(panels) - 1), h - mt - mb
    spans = [max(1e-6, b_ - a_) for a_, b_ in panels]
    ws_ = [max(0.12 * pw, pw * s_ / sum(spans)) for s_ in spans]
    ws_ = [x * pw / sum(ws_) for x in ws_]
    xs, x = [], float(ml)
    for wd in ws_:
        xs.append((x, wd))
        x += wd + brk
    Y = lambda v: mt + (y1 - v) / max(1e-9, y1 - y0) * ph          # noqa: E731

    def X(k, f):
        a_, b_ = panels[k]
        return xs[k][0] + (f - a_) / max(1e-9, b_ - a_) * xs[k][1]
    p = QtGui.QPainter(img)
    p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
    fnt = p.font()
    fnt.setPixelSize(17)
    p.setFont(fnt)
    grid, mut = QtGui.QColor("#dde2ea"), QtGui.QColor("#6e6e73")
    for v in range(int(y0), int(y1) + 1, 10):
        p.setPen(mut)
        p.drawText(QtCore.QRectF(0, Y(v) - 10, ml - 8, 20), Qt.AlignmentFlag.AlignRight, f"{v}")
    for k, (a_, b_) in enumerate(panels):
        x0_, wd = xs[k]
        for c0, c1, ch in tv:                         # canaux TV : bandeau gris + numéro
            lo_, hi_ = max(a_, c0), min(b_, c1)
            if hi_ > lo_:
                p.fillRect(QtCore.QRectF(X(k, lo_), mt, X(k, hi_) - X(k, lo_), ph), QtGui.QColor(120, 120, 130, 38))
                p.setPen(mut)
                p.drawText(QtCore.QRectF(X(k, lo_), mt + ph - 22, X(k, hi_) - X(k, lo_), 20),
                           Qt.AlignmentFlag.AlignHCenter, f"{ch}")
        p.setPen(QtGui.QPen(grid, 1))
        for v in range(int(y0), int(y1) + 1, 10):
            p.drawLine(QtCore.QPointF(x0_, Y(v)), QtCore.QPointF(x0_ + wd, Y(v)))
        span = b_ - a_
        nt = max(2, int(wd / 120))
        stepx = next((s_ for s_ in (1, 2, 5, 10, 20, 25, 50, 100, 200, 500) if span / s_ <= nt), 1000)
        f_ = math.ceil(a_ / stepx) * stepx
        while f_ <= b_ + 1e-9:
            p.setPen(QtGui.QPen(grid, 1))
            p.drawLine(QtCore.QPointF(X(k, f_), mt), QtCore.QPointF(X(k, f_), mt + ph))
            p.setPen(mut)
            p.drawText(QtCore.QRectF(X(k, f_) - 40, mt + ph + 6, 80, 20), Qt.AlignmentFlag.AlignHCenter, f"{f_:g}")
            f_ += stepx
        p.setPen(QtGui.QPen(QtGui.QColor("#c7ccd6"), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(QtCore.QRectF(x0_, mt, wd, ph))
        if thr is not None:
            p.setPen(QtGui.QPen(QtGui.QColor("#ff9f0a"), 1.6, Qt.PenStyle.DashLine))
            p.drawLine(QtCore.QPointF(x0_, Y(thr)), QtCore.QPointF(x0_ + wd, Y(thr)))
        m = (F >= a_ - 1e-9) & (F <= b_ + 1e-9)
        Fk, Lk = F[m], L[m]
        path = QtGui.QPainterPath()
        gaps = set(int(i) for i in scan_gaps(Fk)) if len(Fk) > 2 else set()
        for i in range(len(Fk)):
            pt = QtCore.QPointF(X(k, Fk[i]), Y(min(y1, max(y0, Lk[i]))))
            if i == 0 or i in gaps:                  # trou entre deux bandes : pas de trait par-dessus
                path.moveTo(pt)
            else:
                path.lineTo(pt)
        p.setPen(QtGui.QPen(QtGui.QColor("#0a5bd3"), 1.4))
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QColor("#e8590c"))
        for f, _n in marks:                          # fréquences du plan : petit triangle au-dessus du cadre
            if a_ <= f <= b_:
                xx = X(k, f)
                p.drawPolygon(QtGui.QPolygonF([QtCore.QPointF(xx - 5, mt - 14), QtCore.QPointF(xx + 5, mt - 14),
                                               QtCore.QPointF(xx, mt - 3)]))
        if k:                                        # coupure de l'axe
            bx = x0_ - brk
            p.setPen(QtGui.QPen(QtGui.QColor("#9aa0aa"), 1.4))
            for dx in (4, brk - 4):
                p.drawLine(QtCore.QPointF(bx + dx - 4, mt + ph + 6), QtCore.QPointF(bx + dx + 4, mt + ph - 6))
    p.setPen(mut)
    p.drawText(QtCore.QRectF(ml, h - 18, pw + brk * (len(panels) - 1), 18), Qt.AlignmentFlag.AlignRight, "MHz · dBm")
    p.drawText(QtCore.QRectF(ml, 0, pw, 18), Qt.AlignmentFlag.AlignLeft,
               TR("▼ fréquences du plan · gris = canaux TV · tirets = seuil « occupé »"))
    p.end()
    return img


class CoordScanDialog(QtWidgets.QDialog):
    """📏 7.67 (Clément : « qu'il faut un RBW fin ») : scan pour la coordination fait tout seul. RBW fine + points
    calés sur la RBW, pics remis à zéro, balayage N minutes, puis scan gardé dans Scans par lieu (avec sa RBW) et
    réglages de surveillance remis comme avant."""

    def __init__(self, owner):
        super().__init__(owner)
        self.owner = o = owner
        self.setWindowTitle("Scan pour la coordination")
        self.setModal(False)
        lay = QtWidgets.QVBoxLayout(self)
        info = QtWidgets.QLabel("Le tinySA balaye tes bandes avec une RBW fine et des points calés sur cette RBW (aucun "
                                "signal ne passe entre deux points), en gardant les pics, pendant le temps choisi. À la "
                                "fin, le scan est gardé dans Scans par lieu avec sa RBW, et tes réglages de surveillance "
                                "reviennent comme avant.")
        info.setWordWrap(True)
        lay.addWidget(info)
        f = QtWidgets.QFormLayout()
        self.rbw = QtWidgets.QComboBox()
        for v, lab in ((10, "10 kHz (très fin, très lent)"), (30, "30 kHz (conseillé)"), (100, "100 kHz (rapide, moins précis)")):
            self.rbw.addItem(lab, v)
        self.rbw.setCurrentIndex(1)
        self.rbw.setToolTip(COORD_RBW_TIP)
        self.minutes = QtWidgets.QSpinBox()
        self.minutes.setRange(1, 120)
        self.minutes.setValue(5)
        self.minutes.setSuffix(" min")
        self.minutes.setToolTip("Plus long = plus de chances d'attraper ce qui émet par moments (talkies, liaisons).")
        self.scene = QtWidgets.QComboBox()
        self.scene.setEditable(True)
        for sc in o.scenes:
            self.scene.addItem(sc["name"])
        one = {k[0] for k in o.scope or [] if k}
        self.scene.setEditText(next(iter(one)) if len(one) == 1 else (o.scenes[0]["name"] if o.scenes else "Site"))
        self.scene.setToolTip("Lieu (scène) où le scan sera rangé dans Scans par lieu.")
        self.label = QtWidgets.QLineEdit("")
        self.label.setPlaceholderText("ex. jardin, régie… (sinon l'heure)")
        self.label.setToolTip("Étiquette du scan (facultatif).")
        f.addRow("Finesse (RBW) :", self.rbw)
        f.addRow("Durée :", self.minutes)
        f.addRow("Lieu :", self.scene)
        f.addRow("Étiquette :", self.label)
        lay.addLayout(f)
        self.est = QtWidgets.QLabel("")
        self.est.setWordWrap(True)
        lay.addWidget(self.est)
        self.bar = QtWidgets.QProgressBar()
        self.bar.setRange(0, 1000)
        self.bar.hide()
        lay.addWidget(self.bar)
        self.msg = QtWidgets.QLabel("")
        self.msg.setWordWrap(True)
        lay.addWidget(self.msg)
        row = QtWidgets.QHBoxLayout()
        self.go = QtWidgets.QPushButton("▶ Lancer le scan")
        self.go.setToolTip("Règle la RBW et les points, efface les pics gardés et balaye le temps choisi.")
        self.go.clicked.connect(lambda *_: self.start() if self._state is None else self.stop(cancel=True))
        self.sites_btn = QtWidgets.QPushButton("📍 Scans par lieu…")
        self.sites_btn.setToolTip("Voir les scans gardés (comparer, exporter avec la RBW dans le nom).")
        self.sites_btn.clicked.connect(lambda *_: o.open_sites())
        b_close = QtWidgets.QPushButton("Fermer")
        b_close.clicked.connect(self.close)
        row.addWidget(self.go)
        row.addWidget(self.sites_btn)
        row.addStretch(1)
        row.addWidget(b_close)
        lay.addLayout(row)
        self._state = None
        self.timer = QtCore.QTimer(self)
        self.timer.timeout.connect(self._tick)
        self.rbw.currentIndexChanged.connect(lambda *_: self._estimate())
        self._estimate()
        fit_dialog(self, 560, 420)

    def _estimate(self):
        o = self.owner
        act = [b for b in o.bands if b["enabled"]] or o.bands
        total = sum(max(0.0, b["stop"] - b["start"]) for b in act)
        rbw = float(self.rbw.currentData())
        step = auto_scan_step(total, rbw, AUTO_BUDGET.get(0, 4500))
        n = int(total * 1000.0 / max(step, 0.001))
        self.est.setText(TR("Bandes balayées : {} MHz au total · pas de {} kHz ≈ {} points par tour (plus lent qu'en "
                            "surveillance : c'est normal).").format(f"{total:g}", f"{step:g}", n))

    def start(self):
        o = self.owner
        st = dict(rbw=o.rbw_combo.currentIndex(), pts=o.points_combo.currentIndex(), hold=o.hold_chk.isChecked(),
                  running=o.is_running(), t0=time.time(), dur=self.minutes.value() * 60.0, extra=0.0,
                  scene=self.scene.currentText().strip() or "Site", label=self.label.text().strip(),
                  rbw_v=float(self.rbw.currentData()))
        for i in range(o.rbw_combo.count()):
            v = o.rbw_combo.itemData(i)
            if v is not None and abs(float(v) - st["rbw_v"]) < 1e-6:
                o.rbw_combo.setCurrentIndex(i)
                break
        i_auto = o.points_combo.findData(0)
        if i_auto >= 0:
            o.set_points_choice(i_auto)
        o.hold_chk.setChecked(True)
        o.reset_max()
        self._state = st
        if not st["running"]:
            o.toggle_run(auto=True)
        self.go.setText(TR("■ Arrêter (sans garder)"))
        for w_ in (self.rbw, self.minutes, self.scene, self.label):
            w_.setEnabled(False)
        self.bar.setValue(0)
        self.bar.show()
        self.msg.setText(TR("Scan en cours… laisse le tinySA balayer."))
        self.timer.start(1000)

    def _tick(self):
        st, o = self._state, self.owner
        if st is None:
            return
        el = time.time() - st["t0"]
        tot = st["dur"] + st["extra"]
        self.bar.setValue(int(1000 * min(1.0, el / max(1.0, tot))))
        left = max(0, int(tot - el))
        self.msg.setText(TR("Scan en cours… encore {} min {} s.").format(left // 60, f"{left % 60:02d}"))
        if el > 8 and not o.is_running():
            self.stop(cancel=True, why=TR("La surveillance s'est arrêtée : scan abandonné."))
            return
        if el >= tot:
            F, L = o.fresh_FL(use_max=True, any_age=True)
            if F is None and st["extra"] < 180:
                st["extra"] += 30                 # pas encore un tour complet : on attend un peu
                return
            self.stop(cancel=F is None, F=F, L=L,
                      why=None if F is not None else TR("Aucun tour complet mesuré : scan abandonné."))

    def stop(self, cancel=False, F=None, L=None, why=None):
        st, o = self._state, self.owner
        if st is None:
            return
        self.timer.stop()
        self._state = None
        saved = None
        if not cancel and F is not None:
            names = {d["name"] for d in o.site_scans}
            name = snapshot_name(st["scene"], st["label"], names, time.strftime("%H:%M"))
            o.site_scans.append(site_scan_doc(name, F, L, time.time(), scene=st["scene"],
                                              dur=time.time() - st["t0"], rbw=st["rbw_v"]))
            saved = name
            o.undo_track()
            o.update_site_curve()
            o._bump()
        o.rbw_combo.setCurrentIndex(st["rbw"])        # réglages de surveillance comme avant
        o.set_points_choice(st["pts"])
        o.hold_chk.setChecked(st["hold"])
        if not st["running"] and o.is_running():
            o.toggle_run()
        for w_ in (self.rbw, self.minutes, self.scene, self.label):
            w_.setEnabled(True)
        self.go.setText(TR("▶ Lancer le scan"))
        self.bar.hide()
        if saved:
            line, _ok = rbw_coord_line(st["rbw_v"], False, TR, step=scan_step_khz(F))
            self.msg.setText(TR("✔ Scan gardé : « {} » ({}). Il est dans Scans par lieu, prêt pour la coordination "
                                "et l'export. Réglages de surveillance remis comme avant.").format(
                                    saved, fmt_duration(time.time() - st["t0"])) + "\n" + line)
            o.set_status(TR("📏 Scan pour la coordination gardé : {}").format(saved))
        else:
            self.msg.setText(why or TR("Scan arrêté sans rien garder. Réglages de surveillance remis comme avant."))

    def closeEvent(self, e):
        if self._state is not None:
            self.stop(cancel=True)
        super().closeEvent(e)


class RecurringDialog(QtWidgets.QDialog):
    """🔁 7.67 : perturbations qui reviennent à la même heure sur plusieurs jours, d'après les journaux automatiques."""

    def __init__(self, owner):
        super().__init__(owner)
        self.owner = o = owner
        self.setWindowTitle("Perturbations qui reviennent")
        lay = QtWidgets.QVBoxLayout(self)
        info = QtWidgets.QLabel("D'après les journaux automatiques (un fichier par jour) : ce qui se répète à la même "
                                "heure sur plusieurs jours. Ex. un talkie qui s'allume tous les soirs vers 19 h, un "
                                "micro qui décroche toujours au même moment.")
        info.setWordWrap(True)
        lay.addWidget(info)
        row = QtWidgets.QHBoxLayout()
        self.days = QtWidgets.QComboBox()
        for n in (3, 7, 14, 30, 90):
            self.days.addItem(TR("{} derniers jours").format(n), n)
        self.days.setCurrentIndex(1)
        self.days.setToolTip("Combien de journaux (jours) lire.")
        self.tol = QtWidgets.QSpinBox()
        self.tol.setRange(5, 120)
        self.tol.setValue(20)
        self.tol.setPrefix("± ")
        self.tol.setSuffix(" min")
        self.tol.setToolTip("« Même heure » à plus ou moins tant de minutes.")
        self.mind = QtWidgets.QSpinBox()
        self.mind.setRange(2, 30)
        self.mind.setValue(2)
        self.mind.setSuffix(TR(" jours mini"))
        self.mind.setToolTip("Nombre de jours différents où ça doit revenir.")
        self.occ = QtWidgets.QCheckBox("Inclure les signaux présents (OCCUPÉ)")
        self.occ.setChecked(True)
        self.occ.setToolTip("Un signal qui s'allume sur une fréquence sans statut (pas tes micros « doit émettre »).")
        for w_ in (self.days, self.tol, self.mind, self.occ):
            row.addWidget(w_)
        row.addStretch(1)
        lay.addLayout(row)
        self.table = QtWidgets.QTableWidget(0, 6)
        self.table.setHorizontalHeaderLabels(["Quoi", "Où", "MHz", "Vers", "Jours", "Fois"])
        self.table.horizontalHeader().setStretchLastSection(True)
        self.table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setToolTip("Double-clic : chasser ce signal (zoom sur sa fréquence).")
        self.table.cellDoubleClicked.connect(self._hunt)
        lay.addWidget(self.table, 1)
        self.msg = QtWidgets.QLabel("")
        self.msg.setWordWrap(True)
        lay.addWidget(self.msg)
        b = QtWidgets.QHBoxLayout()
        cp = QtWidgets.QPushButton("Copier")
        cp.setToolTip("Copie la liste en texte (message, rapport).")
        cp.clicked.connect(lambda *_: QtWidgets.QApplication.clipboard().setText("\n".join(self.lines)))
        cl = QtWidgets.QPushButton("Fermer")
        cl.clicked.connect(self.close)
        b.addWidget(cp)
        b.addStretch(1)
        b.addWidget(cl)
        lay.addLayout(b)
        self.pats, self.lines = [], []
        for w_ in (self.days, self.tol, self.mind):
            (w_.currentIndexChanged if isinstance(w_, QtWidgets.QComboBox) else w_.valueChanged).connect(
                lambda *_: self.refresh())
        self.occ.toggled.connect(lambda *_: self.refresh())
        fit_dialog(self, 820, 520)
        self.refresh()

    def refresh(self):
        o = self.owner
        rows, nfiles = o.journal_rows(self.days.currentData())
        kinds = [k for k in RECUR_KINDS if self.occ.isChecked() or k != "OCCUPÉ"]
        on = [s["name"] for s in o.statuses if s.get("on")]
        self.pats = recurring_events(rows, kinds, self.tol.value(), self.mind.value(), on)
        self.lines = [recurring_text(p_, TR) for p_ in self.pats]
        t = self.table
        t.setRowCount(len(self.pats))
        for r, p_ in enumerate(self.pats):
            vals = [TR(p_["kind"]) + " — " + TR(RECUR_LABELS.get(p_["kind"], "")), p_["name"],
                    f"{p_['mhz']:.3f}" if p_["mhz"] is not None else "—",
                    f"{p_['center'] // 60:02d}:{p_['center'] % 60:02d} ± {p_['spread']}'",
                    f"{p_['days']} / {p_['total_days']}", str(p_["count"])]
            for c, v in enumerate(vals):
                it = QtWidgets.QTableWidgetItem(v)
                it.setToolTip(TR("Jours : {}").format(", ".join(p_["dates"])))
                t.setItem(r, c, it)
        t.resizeColumnsToContents()
        if not nfiles:
            self.msg.setText(TR("Aucun journal automatique trouvé dans {} : coche « Journal auto (CSV / jour) » (onglet "
                                "Journal) pour que l'appli note chaque jour dans un fichier.").format(o.log_dir))
        elif not self.pats:
            self.msg.setText(TR("{} journal(aux) lu(s) : rien ne revient à la même heure sur plusieurs jours.").format(nfiles))
        else:
            self.msg.setText(TR("{} journal(aux) lu(s) · {} perturbation(s) qui reviennent.").format(nfiles, len(self.pats)))

    def _hunt(self, r, _c):
        if 0 <= r < len(self.pats) and self.pats[r]["mhz"] is not None:
            self.owner.open_hunt(self.pats[r]["mhz"])


class RfDiagDialog(QtWidgets.QDialog):
    """🩺 7.68 : diagnostic RF automatique. Lit le spectre en direct et la liste, dit en clair ce qui cloche dans la
    MESURE (saturation, bruit de fond, zones bruyantes, seuil, micros pile au seuil, micros dans un canal TV, signaux
    hors liste) et propose « Régler »."""

    def __init__(self, owner):
        super().__init__(owner)
        self.owner = owner
        self.setWindowTitle("Diagnostic RF")
        self.setModal(False)
        self.resize(760, 560)
        lay = QtWidgets.QVBoxLayout(self)
        self.head = QtWidgets.QLabel("")
        self.head.setStyleSheet("font-size:18px; font-weight:bold; padding:6px")
        lay.addWidget(self.head)
        intro = QtWidgets.QLabel("Ce que le tinySA voit en ce moment, relu pour toi : ce qui fausse la mesure et quoi "
                                 "faire. Les seuils de ce diagnostic sont des valeurs de départ : fie-toi aussi à ton "
                                 "oreille et au spectre.")
        intro.setWordWrap(True)
        lay.addWidget(intro)
        self.table = QtWidgets.QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(["", "Point", "Ce qui se passe · quoi faire"])
        self.table.verticalHeader().setVisible(False)
        self.table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.NoSelection)
        self.table.setWordWrap(True)
        hh = self.table.horizontalHeader()
        hh.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
        hh.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeMode.Interactive)
        hh.setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeMode.Stretch)
        self.table.setColumnWidth(1, 200)
        self.table.setToolTip("Chaque ligne = un point relevé dans la mesure. « Régler » applique ou ouvre la correction.")
        lay.addWidget(self.table, 1)
        row = QtWidgets.QHBoxLayout()
        self.again_btn = QtWidgets.QPushButton("↻ Relancer le diagnostic")
        self.again_btn.setToolTip("Relit le spectre et la liste maintenant (c'est aussi refait toutes les 5 s).")
        self.again_btn.clicked.connect(lambda *_: self.refresh())
        man = QtWidgets.QPushButton("❓ Manuel")
        man.setToolTip("Le chapitre du manuel sur les seuils et la lecture du spectre.")
        man.clicked.connect(lambda *_: owner.open_manual("seuils"))
        close = QtWidgets.QPushButton("Fermer")
        close.setToolTip("Ferme cette fenêtre.")
        close.clicked.connect(self.close)
        row.addWidget(self.again_btn)
        row.addWidget(man)
        row.addStretch(1)
        row.addWidget(close)
        lay.addLayout(row)
        self.msg = QtWidgets.QLabel("")
        self.msg.setWordWrap(True)
        lay.addWidget(self.msg)
        self.items = []
        self.timer = QtCore.QTimer(self)
        self.timer.timeout.connect(self.refresh)
        self.timer.start(5000)
        self.refresh()
        fit_dialog(self, 760, 560)

    def refresh(self):
        o = self.owner
        try:
            self.items = rf_diagnose(o.rf_diag_info())
        except Exception as e:  # noqa: BLE001
            self.msg.setText(TR("Diagnostic impossible : {}").format(e))
            return
        lvl, txt = rf_diag_summary(self.items)
        col = {"ok": o.theme.get("st_free", "#3fb950"), "warn": o.theme.get("st_weak", "#d29922"),
               "bad": o.theme.get("st_occ", "#f85149")}
        self.head.setText(TR(txt))
        self.head.setStyleSheet(f"font-size:18px; font-weight:bold; padding:6px; color:{col.get(lvl, '')}")
        t = self.table
        t.setRowCount(len(self.items))
        for r, c in enumerate(self.items):
            t.setItem(r, 0, QtWidgets.QTableWidgetItem(DIAG_ICONS.get(c["level"], "")))
            it = QtWidgets.QTableWidgetItem(TR(c["title"]))
            it.setToolTip(TR(c["title"]))
            t.setItem(r, 1, it)
            w = QtWidgets.QWidget()
            hl = QtWidgets.QHBoxLayout(w)
            hl.setContentsMargins(4, 2, 4, 2)
            tx = TR(c["text"]).replace("\n", " ")
            ad = TR(c["advice"]).replace("\n", " ") if c["advice"] else ""
            lb = QtWidgets.QLabel(html_esc(tx) + (f"<br><b>→</b> {html_esc(ad)}" if ad else ""))
            lb.setWordWrap(True)
            lb.setTextFormat(Qt.TextFormat.RichText)
            hl.addWidget(lb, 1)
            if c["fix"] and c["level"] != "ok" and hasattr(o, c["fix"]):
                b = QtWidgets.QPushButton("Régler")
                b.setToolTip("Applique la correction proposée ou ouvre le bon réglage.")
                b.clicked.connect(lambda *_, c=c: self.fix(c))
                hl.addWidget(b)
            t.setItem(r, 2, QtWidgets.QTableWidgetItem(""))
            t.setCellWidget(r, 2, w)
        t.resizeRowsToContents()

    def fix(self, c):
        o = self.owner
        try:
            fn = getattr(o, c["fix"])
            a = c.get("arg")
            if a is None:
                fn()
            elif isinstance(a, tuple):
                fn(*a)
            else:
                fn(a)
        except Exception as e:  # noqa: BLE001
            self.msg.setText(TR("Impossible : {}").format(e))
            return
        self.refresh()

    def closeEvent(self, e):
        self.timer.stop()
        super().closeEvent(e)


class ReplaceDialog(QtWidgets.QDialog):
    """🆘 7.62 Remplacer un micro brouillé : 3 propositions (son appareil, sa bande, compatibles avec tout le plan,
    libres d'après la mesure), un clic = remplacé + journal. Le calcul tourne en arrière-plan."""

    def __init__(self, owner, w):
        super().__init__(owner)
        self.owner, self.w = owner, w
        o = owner
        self.setWindowTitle("Remplacer un micro")
        lay = QtWidgets.QVBoxLayout(self)
        rx = o.rx_of(w)
        self.head = QtWidgets.QLabel(f"<b style='font-size:16px'>🆘 {_hesc(w['name'])} · {w['freq']:.3f} MHz</b><br>"
                                     + _hesc(TR("Appareil : {}").format(rx_short(rx) if rx else TR("réglages par défaut"))))
        self.head.setTextFormat(Qt.TextFormat.RichText)
        lay.addWidget(self.head)
        self.msg = QtWidgets.QLabel("")
        self.msg.setWordWrap(True)
        lay.addWidget(self.msg)
        self.box = QtWidgets.QVBoxLayout()
        lay.addLayout(self.box)
        self.done_lbl = QtWidgets.QLabel("")
        self.done_lbl.setWordWrap(True)
        lay.addWidget(self.done_lbl)
        again = QtWidgets.QPushButton("↻ Recalculer")
        again.setToolTip("Refait les propositions avec la mesure actuelle.")
        again.clicked.connect(lambda *_: self.compute())
        more = QtWidgets.QPushButton("Plus d'options (fréquence de secours)…")
        more.setToolTip("Recherche détaillée : plage, écart, intermod, spectre d'une scène…")
        more.clicked.connect(lambda *_: o.open_rescue())
        close = QtWidgets.QPushButton("Fermer")
        close.clicked.connect(self.close)
        lay.addLayout(o._row(again, more, None, close))
        self.resize(520, 300)
        self.found, self._job = [], None
        self.compute()

    def compute(self):
        o = self.owner
        if not any(x is self.w for x in o.watch):
            self.msg.setText("Ce micro n'est plus dans la liste.")
            return
        while self.box.count():
            it = self.box.takeAt(0)
            if it.widget() is not None:
                it.widget().deleteLater()
        a = o.replace_args(self.w)
        self._args = a
        self._job = o.run_heavy(lambda: o.replace_compute(a, 3), self._computed, self.msg, "Recherche des remplaçantes")

    def _computed(self, sg, err):
        o = self.owner
        self._job = None
        if err is not None:
            self.msg.setText(f"Calcul impossible : {err}")
            return
        self.found = o.replace_decorate(self._args, sg, self.w)
        if not self.found:
            self.msg.setText("Aucune fréquence libre et compatible trouvée avec ces règles"
                             + (TR(" dans la bande de l'appareil ({}–{} MHz)").format(*self._args["band"])
                                if self._args["band"] else "") + ". Essaie « Plus d'options ».")
            return
        bd = self._args["band"]
        relaxed = any(x.get("relaxed") for x in self.found)
        head = (TR("⚠ Rien ne passe avec toutes tes règles : propositions vérifiées en 2A − B SEULEMENT (A + B − C et "
                   "5ᵉ ordre NON vérifiés). Libres d'après la mesure")
                if relaxed else TR("Libres d'après la mesure, compatibles avec tout ton plan"))
        self.msg.setText(head + (TR(", dans la bande de l'appareil ({}–{} MHz)").format(*bd) if bd else "")
                         + TR(". Un clic = remplacer :"))
        self.msg.setStyleSheet("color:#e0a040" if relaxed else "")
        for x in self.found:
            lv = f" · {o.lvl(x['level'], suffix=True)}" if x["level"] is not None else ""
            b = QtWidgets.QPushButton(f"{x['f']:.3f} MHz   ({x['d'] * 1000:+.0f} kHz{lv})"
                                      + (f"   ⚠ {TR(x['tag'])}" if x["tag"] else ""))
            b.setMinimumHeight(40)
            b.setToolTip("Remplace la fréquence dans la liste et le note au journal.\nPense à régler l'émetteur ET le "
                         "récepteur.")
            b.clicked.connect(lambda *_, f=x["f"]: self.pick(f))
            self.box.addWidget(b)

    def pick(self, f):
        if self.owner.replace_watch(self.w, f):
            self.done_lbl.setText(TR("✔ Remplacé : {} est maintenant sur {} MHz. Règle l'émetteur ET le récepteur."
                                     ).format(self.w["name"], f"{f:.3f}"))
            while self.box.count():
                it = self.box.takeAt(0)
                if it.widget() is not None:
                    it.widget().deleteLater()

    def closeEvent(self, e):
        if self._job is not None:
            self._job["cancel"] = True
            self._job = None
        super().closeEvent(e)


class QuickAddDialog(QtWidgets.QDialog):
    """⌨ 7.62 Saisie express : on tape ou on colle « HF1 558.2, HF2 574, IEM 606.5 PSM » (ou un message, un tableau),
    l'aperçu se met à jour, « Ajouter » crée les micros dans la scène / le groupe choisis. Non modale."""

    def __init__(self, owner, text="", preset=("", "")):
        super().__init__(owner)
        self.owner = o = owner
        self.setWindowTitle("Ajouter des micros (saisie express)")
        lay = QtWidgets.QVBoxLayout(self)
        info = QtWidgets.QLabel("Tape ou colle tes fréquences, n'importe comment : « HF1 558.2, HF2 574, IEM 606.5 », "
                                "une par ligne, ou un message reçu (mail, SMS). Les nombres qui ne sont pas des "
                                "fréquences sont ignorés.")
        info.setWordWrap(True)
        lay.addWidget(info)
        self.edit = QtWidgets.QPlainTextEdit()
        self.edit.setPlaceholderText("HF1 558.2, HF2 574\nIEM 606.5 PSM\nGuitare 470.125")
        self.edit.setToolTip("Fréquences en MHz (558.2 ou 558,2) ou en kHz (558200). Le texte avant chaque\n"
                             "fréquence devient son nom ; sans nom, l'appli numérote (HF 1, HF 2…).")
        self.edit.setPlainText(text or "")
        self.edit.textChanged.connect(lambda *_: self.refresh())
        lay.addWidget(self.edit, 1)
        self.table = QtWidgets.QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(["Nom", "MHz", "Remarque"])
        self.table.verticalHeader().setVisible(False)
        self.table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.horizontalHeader().setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeMode.Stretch)
        self.table.setToolTip("Ce qui va être ajouté.")
        lay.addWidget(self.table, 1)
        self.scene = QtWidgets.QComboBox()
        self.scene.setEditable(True)
        self.scene.addItems([""] + [sc["name"] for sc in o.scenes])
        self.scene.setEditText(preset[0] or "")
        self.scene.setToolTip("Scène (facultatif ; une nouvelle est créée si tu tapes un nom).")
        self.group = QtWidgets.QComboBox()
        self.group.setEditable(True)
        self.group.setToolTip("Groupe dans la scène (facultatif).")
        self.scene.currentTextChanged.connect(lambda *_: self._groups())
        self._groups()
        self.group.setEditText(preset[1] or "")
        self.scene.setMinimumWidth(160)
        self.group.setMinimumWidth(130)
        self.status = QtWidgets.QComboBox()
        self.status.addItem("(aucun statut)", "")
        for st in o.statuses:
            self.status.addItem(st["name"], st["name"])
        self.status.setToolTip("Statut des nouveaux micros (« doit émettre » : alarme s'ils disparaissent).")
        self.prefix = QtWidgets.QLineEdit("HF")
        self.prefix.setMaximumWidth(90)
        self.prefix.setToolTip("Nom donné aux fréquences sans nom : HF 1, HF 2…")
        self.prefix.textChanged.connect(lambda *_: self.refresh())
        lay.addLayout(o._row("Scène :", self.scene, "Groupe :", self.group, "Statut :", self.status,
                             "Sans nom :", self.prefix, None))
        self.msg = QtWidgets.QLabel("")
        self.msg.setWordWrap(True)
        self.add_btn = QtWidgets.QPushButton("＋ Ajouter")
        self.add_btn.setToolTip("Ajoute ces micros à ta liste (Ctrl+Entrée).")
        self.add_btn.clicked.connect(lambda *_: self.add())
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+Return"), self, activated=self.add)
        close = QtWidgets.QPushButton("Fermer")
        close.clicked.connect(self.close)
        lay.addLayout(o._row(self.msg, None, self.add_btn, close))
        self.resize(640, 520)
        self.items = []
        self.refresh()

    def _groups(self):
        sc = self.owner.scene_by_name(self.scene.currentText().strip())
        cur = self.group.currentText()
        self.group.blockSignals(True)
        self.group.clear()
        self.group.addItems([""] + ([g["name"] for g in sc["groups"]] if sc else []))
        self.group.setEditText(cur)
        self.group.blockSignals(False)

    def refresh(self):
        o = self.owner
        self.items, ign = parse_quick_entry(self.edit.toPlainText())
        names = quick_names(self.items, self.prefix.text().strip() or "HF", {w["name"] for w in o.watch})
        have = {int(round(w["freq"] * 1000)) for w in o.watch}
        self.table.setRowCount(len(self.items))
        for r, (it, nm) in enumerate(zip(self.items, names)):
            it["final"] = nm
            dup = int(round(it["freq"] * 1000)) in have
            it["dup"] = dup
            rem = "déjà dans la liste : ignorée" if dup else ("" if o.in_scanned_band(it["freq"]) else
                                                                   "hors des bandes balayées (proposées après l'ajout)")
            if it.get("khz") and not dup:
                rem = TR("⚠ nombre lu en kHz : vérifie que c'est bien une fréquence") + (f" · {TR(rem)}" if rem else "")
            for c, v in enumerate((nm, f"{it['freq']:.3f}", rem)):
                cell = QtWidgets.QTableWidgetItem(v)
                if dup:
                    cell.setForeground(QtGui.QColor("#8b95a5"))
                self.table.setItem(r, c, cell)
        n = sum(1 for it in self.items if not it["dup"])
        self.add_btn.setText(TR("＋ Ajouter {} micro(s)").format(n) if n else TR("＋ Ajouter"))
        self.add_btn.setEnabled(n > 0)
        self.msg.setText(TR("Ignoré (pas de fréquence) : {}").format(" · ".join(ign[:4]) + (" …" if len(ign) > 4 else ""))
                         if ign else "")

    def add(self):
        o = self.owner
        new = [it for it in self.items if not it.get("dup")]
        if not new:
            return 0
        sc, gr = self.scene.currentText().strip(), self.group.currentText().strip()
        if sc:
            o.ensure_group(sc, gr)
        st = self.status.currentData() or ""
        for it in new:
            o._append_watch(it["final"], it["freq"], st, None, sc, gr if sc else "")
        o.sort_watch()
        o.rebuild_tree()
        o.rebuild_watch_table()
        o._update_markers()
        o.undo_track()
        o.set_status(TR("⌨ {} micro(s) ajouté(s).").format(len(new)))
        self.edit.clear()
        self.msg.setText(TR("✔ {} micro(s) ajouté(s). Tu peux en taper d'autres.").format(len(new)))
        o.offer_missing_bands()
        return len(new)


class ScanAddDialog(QtWidgets.QDialog):
    """📡 Ajouter depuis le scan : les signaux vus au-dessus d'un seuil deviennent des fréquences de la liste
    (à renommer, ranger, supprimer ensuite comme les autres)."""
