    def _devx_fill(self):
        t = getattr(self, "devx_table", None)
        if t is None:
            return
        t.blockSignals(True)
        t.setRowCount(len(self.devx))
        for r, x in enumerate(self.devx):
            on = QtWidgets.QTableWidgetItem(dev_ord(r + 2))
            on.setFlags(Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
            on.setCheckState(Qt.CheckState.Checked if x.get("on") else Qt.CheckState.Unchecked)
            t.setItem(r, 0, on)
            t.setItem(r, 1, QtWidgets.QTableWidgetItem(x.get("name", "")))
            t.setItem(r, 2, QtWidgets.QTableWidgetItem(x.get("addr", "")))
            t.setItem(r, 3, QtWidgets.QTableWidgetItem(f"{float(x.get('offset', 0.0)):+.1f}"))
        t.resizeColumnToContents(0)
        t.blockSignals(False)

    def _devx_from_table(self):
        t = self.devx_table
        out = []
        for r in range(t.rowCount()):
            def txt(c):
                it = t.item(r, c)
                return it.text().strip() if it is not None else ""
            try:
                off = float(txt(3).replace(",", ".") or 0)
            except ValueError:
                off = self.devx[r].get("offset", 0.0) if r < len(self.devx) else 0.0
            it0 = t.item(r, 0)
            out.append(dict(on=it0 is not None and it0.checkState() == Qt.CheckState.Checked, name=txt(1),
                            addr=txt(2), offset=off))
        self.devx = devx_norm(out, MAX_DEVS)
        self._dev2_changed()

    def devx_add(self):
        if self.is_running():
            self.set_status("Arrête d'abord la surveillance pour ajouter un tinySA.")
            return
        if len(self.devx) >= MAX_DEVS - 2:
            self.set_status(f"Au plus {MAX_DEVS} tinySA en même temps.")
            return
        if not self.dev2.get("on"):
            self.dev2_chk.setChecked(True)          # le 2ᵉ d'abord
        self.devx.append(dict(on=True, addr="", name="", offset=0.0))
        self._devx_fill()
        self.devx_table.setCurrentCell(len(self.devx) - 1, 2)
        self._dev2_changed()
        self.set_status(f"{dev_ord(len(self.devx) + 1)} tinySA ajouté : saisis son adresse (COM5, 192.168.1.21:5025 ou le "
                        "nom d'une adresse enregistrée), puis rattache-le à sa scène (📡 Scènes).")

    def devx_del(self):
        if self.is_running():
            self.set_status("Arrête d'abord la surveillance pour retirer un tinySA.")
            return
        r = self.devx_table.currentRow()
        if not 0 <= r < len(self.devx):
            return
        d = r + 2
        self.devx.pop(r)
        # les n° suivants descendent d'un cran : leurs scènes suivent
        sc = {}
        for k, v in self.dev_scenes.items():
            if k == d:
                continue
            sc[k - 1 if k > d else k] = v
        self.dev_scenes = sc
        self._devx_fill()
        self._dev2_changed()

    def set_dev_offset(self, d, v):
        if d == 1:
            self.dev2_off.setValue(v)
        elif d >= 2 and d - 2 < len(self.devx):
            self.devx[d - 2]["offset"] = round(float(v), 1)
            self._devx_fill()
            self._bump()

    def resolve_addr(self, a):
        """Adresse d'un tinySA : telle quelle, ou celle d'une adresse enregistrée portant ce nom."""
        a = str(a or "").strip()
        return next((p["addr"] for p in getattr(self, "net_profiles", []) if p["name"].lower() == a.lower()), a)

    def _dev2_ports(self):
        cur = self.dev2_addr.currentText()
        self.dev2_addr.blockSignals(True)
        self.dev2_addr.clear()
        for p in serial.tools.list_ports.comports():
            tag = "  ✔ tinySA" if (p.vid == TINYSA_VID and p.pid == TINYSA_PID) else ""
            self.dev2_addr.addItem(f"{p.device}{tag}", p.device)
        for k in SDR_KINDS:
            self.dev2_addr.addItem(k, k)                 # V8 : « hackrf », « rtlsdr » (ou « hackrf:n° de série »)
        for p in getattr(self, "net_profiles", []):     # 🌐 adresses enregistrées (Raspberry Pi…)
            self.dev2_addr.addItem(f"{p['addr']}  · {p['name']}", p["addr"])
        self.dev2_addr.setEditText(cur)
        self.dev2_addr.blockSignals(False)

    def _read_dev2(self):
        txt = self.dev2_addr.currentText().replace("✔ tinySA", "").split("  · ")[0].strip()   # « COM4  ✔ tinySA » -> « COM4 »
        self.dev2.update(on=self.dev2_chk.isChecked(), addr=txt, offset=float(self.dev2_off.value()),
                         div=self.div_chk.isChecked())

    def _dev2_changed(self):
        self._read_dev2()
        self._bump()
        self.update_band_dev_col()
        self.update_dev2_label()
        self.update_estimate()

    def update_dev2_label(self):
        if not hasattr(self, "dev2_lbl"):
            return
        d = self.dev2
        if not d["on"]:
            self.dev2_lbl.setText("Désactivé : un seul tinySA balaye tout.")
            return
        kind, url = parse_device_addr(d["addr"])
        where = {"serial": f"USB {d['addr']}", "net": f"réseau {url.split('://', 1)[-1]}"}.get(
            kind, "⚠ adresse à saisir (COM4 ou 192.168.1.20:5025)")
        if self.demo_chk.isChecked():
            where = "démo"
        run = self.is_running()
        st = ("✔ en ligne" if self.dev_live[1] else "⚠ liaison perdue (nouvel essai…)") if run else "prêt"
        more = [d for d in self.dev_list() if d >= 2]
        if more:
            lm = self.live_mask()
            st += "\n" + " · ".join(f"{self.dev_name(d)} : " + (("✔" if lm[d] else "⚠ perdu") if run else "prêt")
                                    for d in more)
        cyc = "  ·  ".join(f"{self.dev_name(k)} : {v:.1f} s" for k, v in sorted(self.dev_cycle.items())) if run else ""
        div = ""
        if self.diversity_on():
            now = time.time()
            srcs = [s_ for _F, s_, t in self.div_src.values() if now - t < 60]
            sh = diversity_share(srcs, MAX_DEVS)
            div = "\n🔀 Diversity" + (" · meilleur niveau : " + " · ".join(f"{self.dev_name(d)} {sh[d]} %"
                                                                          for d in self.dev_list())
                                     if run and srcs else " : tous balayent toutes les bandes")
        self.dev2_lbl.setText(f"{where} · {st}" + (f" · {self.dev2_info}" if run and self.dev2_info else "")
                              + (f"\nCycle  {cyc}" if cyc else "") + div)

    def start_calib(self):
        """Les deux tinySA balayent la même bande quelques cycles ; l'offset du 2e est ajusté sur le 1er."""
        if self._calib is not None:
            self._calib_end("Calibration annulée.", popup=False)
            return
        if self.ndev() < 2 or not self.is_running() or not all(self.live_mask()[d] for d in self.dev_list()):
            QtWidgets.QMessageBox.information(self, APP_NAME, "Calibration : lance d'abord le balayage avec tous les "
                                              "tinySA en ligne (et le même signal sur toutes les antennes).")
            return
        if self._zoom is not None:
            QtWidgets.QMessageBox.information(self, APP_NAME, "Coupe le zoom live avant de calibrer.")
            return
        bs = [b for b in self.scan_bands() if b["enabled"]]
        if not bs:
            return
        band = max(bs, key=lambda b: sum(1 for w in self.watch if b["start"] <= w["freq"] <= b["stop"]))
        with self.lock:
            self._calib = dict(band=dict(band), t0=time.time(), data={d: [] for d in self.dev_list()})
        self._bump()
        self.calib_btn.setText("⚖ Calibration en cours… (clic = annuler)")
        self.set_status(f"⚖ Calibration : les tinySA balayent tous « {band['name']} » ({CALIB_SWEEPS} fois chacun)…")

    def _calib_add(self, dev, f, l):
        cal = self._calib
        if cal is None:
            return
        cal["data"][dev].append((np.asarray(f), np.asarray(l)))
        if time.time() - cal["t0"] > CALIB_TIMEOUT:
            self._calib_end("⚠ Calibration abandonnée : trop long.")
            return
        if all(len(v) >= CALIB_SWEEPS for v in cal["data"].values()):
            ref = calib_maxhold(cal["data"][0], CALIB_SWEEPS)          # même nombre de balayages pour tous
            msgs, bad = [], []
            for d in sorted(cal["data"]):
                if d == 0:
                    continue
                oth = calib_maxhold(cal["data"][d], CALIB_SWEEPS)
                res = calib_offset(*ref, *oth) if (ref is not None and oth is not None) else None
                if res is None:
                    bad.append(self.dev_name(d))
                    continue
                delta, n, kind = res
                rep_ = calib_repeat(cal["data"][0], cal["data"][d], CALIB_SWEEPS)
                spread = f", répétabilité ±{rep_[1] / 2:.1f} dB" if rep_ is not None else ""
                new = max(-40.0, min(40.0, round(self.dev_offset(d) + delta, 1)))
                self.set_dev_offset(d, new)
                msgs.append(f"{self.dev_name(d)} {delta:+.1f} dB → offset {new:+.1f} dB (sur {n} points, base : {kind}"
                            f"{spread})")
            if not msgs:
                self._calib_end("⚠ Calibration impossible : pas assez de points communs.")
                return
            self._calib_end("⚖ Calibration faite : " + " · ".join(msgs)
                            + (f" · ⚠ pas assez de points communs : {', '.join(bad)}" if bad else "") + ".")

    def _calib_end(self, msg, popup=True):
        with self.lock:
            self._calib = None
        if msg.startswith("⚖"):     # audit 7.44 : offsets changés -> max hold / historique d'avant = autre échelle
            self.history.clear()
            self.reset_max()
        self._bump()
        self.calib_btn.setText("⚖ Calibrer les autres tinySA sur le 1er…")
        self.calib_msg = msg
        self.set_status(msg)
        if popup:                                  # la barre d'état est vite réécrite par le balayage
            QtWidgets.QMessageBox.information(self, APP_NAME, msg)

    # ------------------------------------------------- alertes téléphone / page web
    def export_bundle(self, path=None):
        """📦 7.63 : sauvegarde complète en un ZIP (pour l'archiver ou l'envoyer en cas de souci) : le show (fréquences,
        scènes, scans par lieu, historique…), la config SANS secrets, un diagnostic tout frais, et des 7 derniers jours :
        journaux, rapports, diagnostics, crash.log, garde.log. Pas les enregistrements de spectre (trop gros).
        -> chemin du ZIP ou None."""
        import zipfile
        now = datetime.now()
        if path is None:
            base = safe_filename(self.show_meta.get("name") or "TinySA", "TinySA")
            path, _ = QtWidgets.QFileDialog.getSaveFileName(
                self, TR("Sauvegarde complète (ZIP)"), str(Path.home() / f"{base}_sauvegarde_{now:%Y%m%d_%H%M}.zip"),
                "ZIP (*.zip)")
            if not path:
                return None
        try:
            diag = self.dump_diag("sauvegarde complète")
        except Exception:  # noqa: BLE001
            diag = None
        cand = []
        for folder, pat in ((self.log_dir, "journal_*.csv"), (self.log_dir / "rapports", "*.html"),
                            (self.log_dir / "diagnostic", "*.txt")):
            try:
                for p_ in Path(folder).glob(pat):
                    st = p_.stat()
                    cand.append((str(p_), st.st_size, st.st_mtime))
            except OSError:
                pass
        for p_ in (CRASH_PATH, GUARD_LOG):
            try:
                st = Path(p_).stat()
                cand.append((str(p_), st.st_size, now.timestamp()))   # toujours (petits, souvent utiles)
            except OSError:
                pass
        picked = bundle_pick(cand, now.timestamp())
        if diag is not None and str(diag) not in picked:
            picked.append(str(diag))
        cfg = self._collect_config(True)
        names = []
        try:
            with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
                doc = show_doc(dict(cfg, map=self.map_for_show(cfg.get("map"))), self.show_meta, self.ref_curves,
                               APP_VER)
                z.writestr("show" + SHOW_EXT, json.dumps(doc, ensure_ascii=False, indent=1))
                z.writestr("config_sans_secrets.json", json.dumps(config_public(cfg), ensure_ascii=False, indent=1,
                                                                  default=str))
                for p_ in picked:
                    pp = Path(p_)
                    sub = "journaux" if pp.name.startswith("journal_") else pp.parent.name if pp.parent.name in (
                        "rapports", "diagnostic") else "journaux_appli"
                    arc = f"{sub}/{pp.name}"
                    z.write(p_, arc)
                    names.append(arc)
                readme = [f"{APP_NAME} {APP_VER} — sauvegarde complète du {now:%d/%m/%Y %H:%M}",
                          f"Show : {self.show_meta.get('name') or '(sans nom)'} · {len(self.watch)} fréquence(s)",
                          f"Python {sys.version.split()[0]} · Qt {QtCore.qVersion()} · {sys.platform}", "",
                          "show.tsashow : à rouvrir avec 🎪 Shows › Ouvrir un show.",
                          "config_sans_secrets.json : réglages (jetons, PIN et mots de passe retirés).", "",
                          "Fichiers :"] + [f"  {n}" for n in names]
                z.writestr("LISEZMOI.txt", "\n".join(readme) + "\n")
        except Exception as e:  # noqa: BLE001
            QtWidgets.QMessageBox.warning(self, APP_NAME, TR("Sauvegarde impossible :\n{}").format(e))
            return None
        self.set_status(TR("📦 Sauvegarde complète : {} ({} fichier(s) en plus du show).").format(path, len(names)))
        return path

    def history_track(self, who=None):
        """🕘 Compare la liste à la dernière fois et note les changements (qui : « PC » par défaut)."""
        rows = watch_rows(self.watch)
        if self._hist_rows is None:
            self._hist_rows = rows
            return 0
        if rows == self._hist_rows:
            return 0
        ch = watch_diff(self._hist_rows, rows)
        self._hist_rows = rows
        now = time.time()
        for x in ch:
            self.mod_history.append(dict(x, t=now, who=who or "PC"))
        del self.mod_history[:-HIST_MAX]
        if self._hist_dlg is not None:
            try:
                if self._hist_dlg.isVisible():
                    self._hist_dlg.fill()
            except RuntimeError:
                self._hist_dlg = None
        return len(ch)

    def open_history(self):
        """🕘 7.63 : historique des modifications de la liste (qui, quand, quoi)."""
        self.history_track()
        if self._hist_dlg is not None:
            try:
                self._hist_dlg.fill()
                self._hist_dlg.show()
                self._hist_dlg.raise_()
                return self._hist_dlg
            except RuntimeError:
                pass
        self._hist_dlg = HistoryDialog(self)
        self._hist_dlg.show()
        return self._hist_dlg

    # ------------------------------------------------------- 🗺 7.64 : carte du site
    def _map_cfg_dump(self):
        d = dict(getattr(self, "map_cfg", None) or map_cfg_norm(None))
        d.pop("bg_data", None)                     # l'image n'est embarquée que dans les shows (map_for_show)
        d.pop("bg_name", None)
        bg = self._map_scene.bg_item if getattr(self, "_map_scene", None) is not None else None
        if bg is not None:                         # le plan a pu être déplacé à la souris
            d["bg_pos"] = [round(bg.pos().x(), 1), round(bg.pos().y(), 1)]
        return d

    def map_for_show(self, m):
        """Carte à écrire dans un show / un ZIP : avec l'image du plan EMBARQUÉE (le show reste complet sur un autre
        PC ; le plan n'a plus besoin d'être au même chemin)."""
        m = dict(m or {})
        p_ = m.get("bg") or ""
        try:
            if p_ and Path(p_).is_file():
                return map_bg_embed(m, Path(p_).read_bytes(), Path(p_).name)
        except OSError:
            pass
        return m

    def _map_bg_restore(self):
        """Show ouvert sur ce PC : son plan embarqué est recopié dans Documents/RF Technical Monitor/Plans (si le chemin
        d'origine n'existe pas ici) ; config.json ne garde que le chemin."""
        m = self.map_cfg
        got = map_bg_extract(m)
        m.pop("bg_data", None)
        name = m.pop("bg_name", None)
        if not got:
            return
        data, name = got
        try:
            if m.get("bg") and Path(m["bg"]).is_file() and Path(m["bg"]).read_bytes() == data:
                return
            import hashlib
            d_ = SHOW_DIR.parent / "Plans"
            d_.mkdir(parents=True, exist_ok=True)
            dst = d_ / f"{hashlib.sha1(data).hexdigest()[:10]}_{name}"
            if not dst.is_file():
                dst.write_bytes(data)
            m["bg"] = str(dst)
        except OSError:
            pass

    def map_scene(self):
        if self._map_scene is None:
            self._map_scene = MapScene(self)
            self._map_scene.sync()
        return self._map_scene

    def open_map(self):
        """🗺 Carte du site : scènes et tinySA à glisser, liens, plan facultatif, carte de chaleur."""
        if self._map is not None:
            try:
                self._map.show()
                self._map.raise_()
                self._map.activateWindow()
                return self._map
            except RuntimeError:
                self._map = None
        if not self.map_cfg["pos"]:            # 1re ouverture : tout est posé d'office, on déplace ensuite
            self.map_cfg["pos"].update(map_auto_place(self.map_scene().keys_all(), {}))
        self._map = MapWindow(self)
        self._map.show()
        return self._map

    def map_png(self, maxw=900):
        """Image de la carte (pour le téléphone et l'export) -> (octets PNG, rectangle de carte représenté)."""
        sc = self.map_scene()
        if sc.unplaced():                          # 7.65 (audit) : nouvelle scène / nouveau tinySA posé même si la
            sc.auto_place()                        # carte du PC est fermée (sinon absent de l'image du téléphone)
        else:
            sc.sync()
        sc.refresh()                               # états à jour (refresh ne tourne d'habitude que fenêtre ouverte)
        r = sc.itemsBoundingRect()
        if r.isEmpty():
            return b"", None
        r = r.adjusted(-40, -40, 40, 40)
        k = min(1.0, maxw / max(1.0, r.width()))
        img = QtGui.QImage(max(1, int(r.width() * k)), max(1, int(r.height() * k)), QtGui.QImage.Format.Format_RGB32)
        img.fill(QtGui.QColor(self.theme["ui_bg"]))
        p = QtGui.QPainter(img)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        sc.render(p, QtCore.QRectF(0, 0, img.width(), img.height()), r)
        p.end()
        ba = QtCore.QByteArray()
        buf = QtCore.QBuffer(ba)
        buf.open(QtCore.QIODevice.OpenModeFlag.WriteOnly)
        img.save(buf, "PNG")
        buf.close()
        return bytes(ba), r

    def _map_web_tick(self, now):
        """PNG de la carte pour le téléphone (vue 🔎 Chasse), refait toutes les 5 s si quelqu'un regarde."""
        if self.web is None or now - self._map_png_t < 5.0 or not self.map_cfg["pos"]:
            return
        if not self.web.watching(("chasse",)):
            return
        self._map_png_t = now
        try:
            self._map_png, self._map_rect = self.map_png(900)
        except Exception:  # noqa: BLE001 — une image ratée ne doit pas gêner la surveillance
            self._map_png = b""

    def map_mark_rel(self, x, y):
        """📍 « Je suis ici » touché sur l'image du téléphone (x, y entre 0 et 1) -> point de chaleur, ou None."""
        r = self._map_rect
        if r is None:
            return None
        pt = self.map_scene().mark(r.left() + x * r.width(), r.top() + y * r.height())
        if pt is not None and self._map is not None:
            try:
                self._map.fill_heat()
            except RuntimeError:
                pass
        self._map_png_t = 0.0
        return pt

    def map_marks_rel(self):
        """Points de la chasse en cours, en coordonnées de l'image du téléphone (0..1)."""
        r, h = self._map_rect, self._hunt
        if r is None or h is None:
            return []
        f = h.f_spin.value()
        out = []
        pts = heat_for(self.map_cfg["heat"], f, 0.05)[-200:]
        lo, hi = heat_scale([p["level"] for p in pts])
        st = heat_stops(self.map_cfg.get("heat_pal", HEAT_PAL_DEFAULT), self.theme["ui_accent"])
        for p in pts:
            out.append(dict(x=round((p["x"] - r.left()) / max(1.0, r.width()), 4),
                            y=round((p["y"] - r.top()) / max(1.0, r.height()), 4), level=p["level"],
                            c=heat_hex(p["level"], lo, hi, st)))
        return out

    def open_qr(self):
        """📱 7.63 : QR code de la page web pour les téléphones de l'équipe."""
        if self._qr is not None:
            try:
                self._qr.fill()
                self._qr.show()
                self._qr.raise_()
                return self._qr
            except RuntimeError:
                pass
        self._qr = QrDialog(self)
        self._qr.show()
        return self._qr

    def open_alerts(self):
        dlg = AlertsDialog(self)
        if dlg.exec():
            n, w = dlg.values()
            self.notify_cfg.update(n)
            pw_changed = w.get("password", "") != self.web_cfg.get("password", "")
            tech_changed = w.get("tech", "") != self.web_cfg.get("tech", "")
            self.web_cfg.update(w)
            if pw_changed and self.web is not None:
                self.web.revoke_all()              # nouveau mot de passe : tout le monde se reconnecte
            elif tech_changed and self.web is not None:
                self.web.revoke_tech()             # nouveau mot de passe Tech : plus personne n'a l'accès
            self.apply_web()

    def send_notify(self, title, body, prio, cfg=None):
        """Met une alerte dans la file d'envoi. -> message d'erreur de réglage, ou "" si c'est parti."""
        c = cfg or self.notify_cfg
        lang = c.get("lang", "app")                       # langue des alertes : celle de l'appli, ou imposée
        tr = TR if lang == "app" else (en_translator() if lang == "en" else (lambda x: x))
        title, body = tr(title), tr(body)
        if c["service"] == "telegram":
            if not c["tg_token"] or not c["tg_chat"]:
                return "Telegram : jeton du bot et chat id requis."
            req = telegram_request(c["tg_token"], c["tg_chat"], title, body)
        else:
            if not c["topic"]:
                return "ntfy : choisis un nom de canal."
            req = ntfy_request(c["server"], c["topic"], title, body, prio)
        if self.notifier is None:
            self.notifier = Notifier()
        self.notifier.post(req)
        return ""

    def _notify_new_alarms(self):
        for a in list(self.alarms.active.values()):
            if a["id"] in self._notified:
                continue
            self._notified.add(a["id"])
            if notify_wanted(a["prio"], self.notify_cfg["mode"]):
                title, body = notify_text(a, self.notify_cfg.get("site", ""))
                self.send_notify(title, body, a["prio"])

    def web_json(self):
        rows = []
        for w in self.watch:
            txt, tone, c_ = self.sig_view(w)
            rows.append(dict(w, conflict=(w["state"] == "occ" and self.is_keep_free(w["status"])), sig_txt=txt,
                             paused=self.w_paused(w),
                             tone=tone, color=c_ if tone != "none" else "", level_txt="" if w["level"] is None else self.lvl(w["level"], suffix=True)))
        cyc = f"{self.last_cycle:.1f} s" if self.is_running() else ""
        site = self.notify_cfg.get("site", "")
        st = web_state(rows, self.alarms.listing(), dict(
            title=f"RF Technical Monitor — {site}" if site else "RF Technical Monitor", time=datetime.now().strftime("%H:%M:%S"),
            running=self.is_running(), cycle=cyc, ack=len(self.web_cfg.get("pin", "").strip()) >= 4, ver=APP_VER,
            hunt=self.hunt_state(), terrain=self.terrain_state(), health=self.health(),
            thr=round(float(self.thr_spin.value()), 1),
            # 7.56 : le spectre de la page web prend les couleurs du thème de l'appli (gamme Analyseur comprise)
            plot=dict(bg=self.theme["plot_bg"], fg=self.theme["plot_fg"], curve=self.theme["curve"],
                      mh=self.theme["maxhold"], thr=self.theme["thr"], crt=self.theme.get("plot_style") == "crt")))
        out = {"fr": json.dumps(st, ensure_ascii=False).encode("utf-8")}
        tr = en_translator()                              # chaque personne choisit sa langue sur la page
        for r in st["rows"]:
            r.update(state_txt=tr(r["state_txt"]), status=tr(r["status"]), alarm=tr(r["alarm"]))
        for a in st["alarms"]:
            a.update(kind=tr(a["kind"]), info=tr(a["info"]), hint=tr(a.get("hint") or ""))
        if st.get("health"):
            d_ = st["health"].get("data")
            st["health"] = dict(st["health"], text=tr(st["health"]["text"]),
                                data=dict(d_, text=tr(d_["text"])) if d_ else None)
        if st.get("hunt"):
            st["hunt"] = dict(st["hunt"], devs=[tr(x) for x in st["hunt"]["devs"]], msg=tr(st["hunt"].get("msg") or ""))
        if st.get("terrain"):
            st["terrain"] = dict(st["terrain"], msg=tr(st["terrain"].get("msg") or ""),
                                 devs=[dict(d, label=tr(d["label"])) for d in st["terrain"]["devs"]])
        out["en"] = json.dumps(st, ensure_ascii=False).encode("utf-8")
        return out

    def web_spec_json(self):
        """Spectre allégé pour les vues Spectre / Waterfall de la page web (une entrée par bande récente)."""
        now = time.time()
        stale = max(15.0, 4 * self.last_cycle)
        names = {b["id"]: b["name"] for b in self.scan_bands()}
        segs, t = [], 0.0
        for k in sorted((k for k in self.latest if k != ZOOM_ID and now - self.latest_t.get(k, 0) <= stale),
                        key=lambda k: float(self.latest[k][0][0]) if len(self.latest[k][0]) else 0.0):
            f, l = self.latest[k]
            segs.append((names.get(k, f"{f[0]:.0f}–{f[-1]:.0f} MHz"), f, l, self.maxhold.get(k)))
            t = max(t, self.latest_t.get(k, 0.0))
        scenes = {}
        if self.web is not None and self.web.watching(("terrain",)):      # 🎒 max hold de chaque scène
            for sc, bands in self.site_mh.items():
                parts = sorted(bands.values(), key=lambda x: float(x[0][0]))
                scenes[sc] = dict(color=self.scene_color(sc),
                                  segs=[dict(f=b["f"], l=b["l"]) for b in web_spectrum([(sc, F, L, None) for F, L in parts],
                                                                                        n_max=600)])
        return json.dumps(dict(t=round(t, 3), bands=web_spectrum(segs), scenes=scenes), ensure_ascii=False).encode("utf-8")

    def apply_web(self):
        want = self.web_cfg["on"]
        if self.web is not None and (not want or self.web.port != self.web_cfg["port"]):
            self.web.stop()
            self.web = None
        if want and self.web is None:
            self._web_json = self.web_json()
            ws = WebServer(self.web_cfg["port"], lambda lang="fr": self._web_json.get(lang, self._web_json["fr"]),
                           get_pin=lambda: self.web_cfg.get("pin", ""), on_ack=self._web_acks.put,
                           on_hunt=self._web_hunts.put, on_terrain=self._web_terrain.put,
                           on_tech=self._web_tech.put, on_tech_req=self._web_techreq.put,
                           get_tech=lambda: self._tech_json, get_map=lambda: self._map_png,
                           get_spec=lambda: self._web_spec, get_cfg=lambda: self.web_cfg, get_page=web_page_bytes,
                           default_lang=self.lang, extra_get=self.web_extra()[0], extra_pin=self.web_extra()[1])
            ws.start()
            ws.ready.wait(3)
            if ws.error:
                self.set_status(f"⚠ Page web : {ws.error}")
                return
            self.web = ws
            self.set_status("🌐 Page web active : " + self.web_urls_text())

    def web_extra(self):
        """7.68 : routes web ajoutées par une autre version (V8) -> (extra_get, extra_pin) de WebServer. V7 : aucune."""
        return {}, {}

    def web_urls_text(self):
        if self.web is None:
            return "Page web désactivée."
        ips = local_ips() or ["<adresse de ce PC>"]
        return "Adresse à ouvrir sur le téléphone : " + "  ou  ".join(f"http://{ip}:{self.web.port}" for ip in ips)

    def dev_name(self, d):
        if d >= 2:
            x = self.devx[d - 2] if d - 2 < len(self.devx) else {}
            return (x.get("name") or "").strip() or f"tinySA {d + 1}"
        n = (self.dev_names[d] if d < len(self.dev_names) else "").strip()
        return n or f"tinySA {d + 1}"

    def seen_by(self, f):
        """« vu par <nom> » : le tinySA qui a mesuré la fréquence f (MHz) en dernier, si deux appareils ; sinon ""."""
        if self.ndev() < 2:
            return ""
        if self.diversity_on():                    # 🔀 : le tinySA qui a donné le meilleur niveau à cette fréquence
            for bid, (F, src, t) in self.div_src.items():
                if len(F) and F[0] - 0.05 <= f <= F[-1] + 0.05 and time.time() - t < 60:
                    return f"meilleur : {self.dev_name(int(src[int(np.argmin(np.abs(F - f)))]))}"
        best = None
        for bid, (F, _L) in self.latest.items():
            if len(F) and F[0] - 0.05 <= f <= F[-1] + 0.05 and bid in self.band_src:
                t = self.latest_t.get(bid, 0)
                if best is None or t > best[0]:
                    best = (t, self.band_src[bid])
        return f"vu par {self.dev_name(best[1])}" if best else ""

    def _dev_names_changed(self):
        self.dev_names = [self.dev1_name.text().strip() or "tinySA 1", self.dev2_name.text().strip() or "tinySA 2"]
        self.update_dev2_label()

    def open_relay(self):
        if getattr(self, "_relay_win", None) is None:
            self._relay_win = RelayWindow()
        self._relay_win.show()
        self._relay_win.raise_()

    def update_band_dev_col(self):
        """Colonne « tinySA » de la table des bandes : choix (Auto / 1 / 2) et appareil réellement utilisé."""
        if not hasattr(self, "band_table"):
            return
        asg = self.band_devices() if self.ndev() > 1 else {}
        self._updating = True
        for r, b in enumerate(self.bands):
            if r >= self.band_table.rowCount():
                break
            d = b.get("dev")
            if self.ndev() == 1:
                txt = "1" if d is None else f"{d + 1}"
            else:
                real = asg.get(b["id"])
                txt = "Auto" if d is None else f"{d + 1}"
                if real == -1:                        # tous la balayent (🔀 diversity, ou tinySA à des scènes)
                    txt = " + ".join(str(d + 1) for d in self.dev_list())
                elif real is not None and (d is None or real != d):
                    txt += f" → {real + 1}"
            self.band_table.setItem(r, 5, self._item(txt))
        self._updating = False

    def on_band_dbl(self, row, col):
        if col != 5 or row >= len(self.bands):
            return
        b = self.bands[row]
        cyc = [None] + self.dev_list()
        with self.lock:
            b["dev"] = cyc[(cyc.index(b.get("dev")) + 1) % len(cyc)] if b.get("dev") in cyc else None
        self._bands_changed()

    def cut_band(self):
        r = self.band_table.currentRow()
        if r < 0 or r >= len(self.bands):
            self.set_status("Sélectionne d'abord la bande à couper.")
            return
        b = self.bands[r]
        (a1, m1, st), (m2, z2, _st) = split_band(b["start"], b["stop"], b["step"])
        if m1 - a1 < 1.0:
            self.set_status("Bande trop étroite pour être coupée.")
            return
        with self.lock:
            self.bands.pop(r)
            for d in (self.latest, self.maxhold, self.partial_data):
                d.pop(b["id"], None)
            for k, (lo, hi) in enumerate(((a1, m1), (m2, z2))):
                self.bands.insert(r + k, dict(id=self._next_id, name=f"{b['name']} ({'bas' if k == 0 else 'haut'})",
                                              start=lo, stop=hi, step=st, enabled=b["enabled"], dev=None))
                self._next_id += 1
        self._fit_x = True
        self._bands_changed()
        self.set_status(f"« {b['name']} » coupée en deux : {a1:g}–{m1:g} et {m2:g}–{z2:g} MHz.")

    # --------------------------------------------------------------- bandes
    def _append_band(self, name, start, stop, step, enabled=True, dev=None):
        with self.lock:
            self.bands.append(dict(id=self._next_id, name=name, start=start, stop=stop,
                                   step=step, enabled=enabled, dev=dev))
            self._next_id += 1

    def _bands_changed(self):
        self._auto_steps()                         # ⚡ Auto : le pas suit la largeur totale des bandes
        self._bump()
        live = {b["id"] for b in self.scan_bands() if b["enabled"]} | {ZOOM_ID} | set(CALIB_IDS)
        for d in (self.latest, self.maxhold, self.partial_data, self.history):
            for k in [k for k in d if k not in live]:
                d.pop(k, None)
        self.rebuild_band_table()
        self.refresh_view_combo()
        self.update_estimate()
        if self._zoom is None and hasattr(self, "wf_hint"):
            self._wf_show(self._wf_bid() is not None)      # une seule bande balayée : waterfall d'office (7.57)

    def _band_restore(self, b, old):
        with self.lock:
            b.update(name=old[0], start=old[1], stop=old[2])
        self._bands_changed()
        self.set_status(f"Bande remise sur {old[1]:g}–{old[2]:g} MHz.")

    def show_band(self, bid):
        """Vue sur une bande (réactivée si elle n'était pas balayée)."""
        b = next((x for x in self.bands if x["id"] == bid), None)
        if b is None:
            return
        if not b["enabled"]:
            self.set_band_enabled(bid, True)
        self.refresh_view_combo()
        ix = self.view_combo.findData(bid)
        if ix >= 0:
            self.view_combo.setCurrentIndex(ix)

    def new_band_dialog(self):
        """＋ Nouvelle bande à balayer depuis « Vue » : un préréglage ou une plage à la main, puis on l'affiche."""
        d = NewBandDialog(self)
        if not d.exec():
            return None
        name, lo, hi, step = d.values()
        self.add_band(name, lo, hi, step)
        bid = self.bands[-1]["id"]
        self.show_band(bid)
        self.set_status(f"＋ Bande « {name} » ajoutée ({lo:g}–{hi:g} MHz) et affichée.")
        return bid

    def add_band(self, name, start, stop, step, enabled=True):
        self._append_band(name, start, stop, step, enabled)
        self._bands_changed()

    def on_preset(self, idx):
        if idx > 0:
            p = self.preset_combo.itemData(idx)
            self.add_band(p[0], p[1], p[2], p[3])
        self.preset_combo.setCurrentIndex(0)

    def del_band(self):
        r = self.band_table.currentRow()
        if r < 0 or r >= len(self.bands):
            return
        if len(self.bands) <= 1:
            self.set_status("Il faut garder au moins une bande.")
            return
        with self.lock:
            b = self.bands.pop(r)
        for d in (self.latest, self.maxhold, self.partial_data):
            d.pop(b["id"], None)
        self._bands_changed()
        self.undo_track()
        self.set_status(f"Bande « {b['name']} » supprimée · Ctrl+Z pour annuler.")

    def points_auto(self):
        """Points par cycle visés en ⚡ Auto, ou None si un nombre fixe est choisi."""
        return AUTO_BUDGET.get(self.points_combo.currentData())

    def _auto_steps(self):
        """⚡ Auto : un même pas pour toutes les bandes, d'après leur largeur totale (et la RBW si elle est imposée).
        -> pas en kHz (None si pas en Auto). Les données des bandes dont le pas change sont oubliées."""
        self._auto_changed = False
        budget = self.points_auto()
        if budget is None:
            return None
        act = [b for b in self.bands if b["enabled"]] or self.bands
        total = sum(max(0.0, b["stop"] - b["start"]) for b in act)
        step = auto_scan_step(total, self.rbw_combo.currentData(), budget)
        with self.lock:
            for b in self.bands:
                if abs(b["step"] - step) > 1e-9:
                    b["step"] = float(step)
                    self._auto_changed = True
                    for d in (self.latest, self.maxhold, self.partial_data):
                        d.pop(b["id"], None)
        if self._auto_changed:
            self._bump()
        return step

    def apply_points(self, _=None):
        if self.points_auto() is not None:
            step = self._auto_steps()
            self._sync_cfg()
            self.rebuild_band_table()
            self.update_estimate()
            tot = sum(self._npts(b) for b in self.bands if b["enabled"])
            self.set_status(f"⚡ Points Auto : pas de {step:g} kHz sur toutes les bandes ({tot} points par cycle).")
            return
        pts = int(self.points_combo.currentData() or 1000)
        with self.lock:
            for b in self.bands:
                b["step"] = round((b["stop"] - b["start"]) * 1000.0 / (pts - 1), 6)
        self._update_pts_btn()
        self.latest.clear()
        self.maxhold.clear()
        self.partial_data.clear()
        self.rebuild_band_table()
        self._sync_cfg()
        self.set_status(f"{pts} points par bande (pas recalculé pour chaque bande).")

    def rebuild_band_table(self):
        self._updating = True
        t = self.band_table
        t.setRowCount(len(self.bands))
        for r, b in enumerate(self.bands):
            it = QtWidgets.QTableWidgetItem(b["name"])
            it.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable |
                        Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEditable)
            it.setCheckState(Qt.CheckState.Checked if b["enabled"] else Qt.CheckState.Unchecked)
            t.setItem(r, 0, it)
            t.setItem(r, 1, self._item(f'{b["start"]:g}', True, True))
            t.setItem(r, 2, self._item(f'{b["stop"]:g}', True, True))
            t.setItem(r, 3, self._item(str(self._npts(b)), True, True))
            t.setItem(r, 4, self._item(f'{b["step"]:.4g}', True, True))
        self._updating = False
        self.update_band_dev_col()

    def on_band_edit(self, item):
        if self._updating or item.row() >= len(self.bands):
            return
        r, col, t = item.row(), item.column(), self.band_table
        name = t.item(r, 0).text()
        enabled = t.item(r, 0).checkState() == Qt.CheckState.Checked
        start, stop, step = (_num(t.item(r, c).text()) for c in (1, 2, 3 + 1))
        pts = _num(t.item(r, 3).text())
        if None in (start, stop, step, pts) or start < 0.1 or stop <= start or step <= 0 or pts < 2:
            QtCore.QTimer.singleShot(0, self.rebuild_band_table)
            return
        if col == 3:
            step = (stop - start) * 1000.0 / (int(pts) - 1)
        if col in (3, 4) and self.points_auto() is not None:
            self.points_combo.blockSignals(True)               # réglé à la main : plus d'Auto
            self.points_combo.setCurrentIndex(self.points_combo.findData(1000))
            self.points_combo.blockSignals(False)
            self._cfg["points_auto"] = False
            self.set_status("Points réglés à la main : ⚡ Auto désactivé.")
        b = self.bands[r]
        with self.lock:
            b.update(name=name, start=start, stop=stop, step=round(step, 6), enabled=enabled)
        if col != 0:
            for d in (self.latest, self.maxhold, self.partial_data):
                d.pop(b["id"], None)
        self._fit_x = True
        QtCore.QTimer.singleShot(0, self._bands_changed)

    def _build_pts_menu(self):
        m = self.pts_menu
        m.clear()
        cur = self.points_combo.currentData()
        grp = QtGui.QActionGroup(m)
        for i in range(self.points_combo.count()):
            k = self.points_combo.itemData(i)
            if i == len(AUTO_POINTS):
                m.addSeparator()
                hd = m.addAction("Nombre fixe par bande :")
                hd.setEnabled(False)
            a = m.addAction(self.points_combo.itemText(i) if k in AUTO_BUDGET else self.points_combo.itemText(i) + " pts")
            a.setCheckable(True)
            a.setChecked(k == cur)
            grp.addAction(a)
            a.triggered.connect(lambda *_, i=i: self.set_points_choice(i))

    def set_points_choice(self, i):
        self.points_combo.setCurrentIndex(i)
        self.apply_points()

    def _update_pts_btn(self):
        b = getattr(self, "pts_btn", None)
        if b is None:
            return
        if self.points_auto() is not None:
            st = next((x["step"] for x in self.bands if x["enabled"]), None)
            b.setText("⚡ Auto" + (f" · {st:g} kHz" if st else ""))
        else:
            b.setText(f"⚡ {self.points_combo.currentText()} pts")

    def _build_bands_menu(self):
        m = self.bands_menu
        m.clear()
        a = m.addAction("📶 Balayer toutes les bandes")
        a.triggered.connect(lambda *_: self.scan_all_bands())
        m.addSeparator()
        hd = m.addAction("Bandes balayées (cocher / décocher) :")
        hd.setEnabled(False)
        for b in self.bands:
            a = m.addAction(b["name"] + f"   {b['start']:g}–{b['stop']:g} MHz")
            a.setCheckable(True)
            a.setChecked(bool(b["enabled"]))
            a.toggled.connect(lambda *_, a=a, bid=b["id"]: self.set_band_enabled(bid, a.isChecked()))
        m.addSeparator()
        a = m.addAction("🎯 Ne balayer que la bande affichée dans « Vue »")
        a.setCheckable(True)
        a.setChecked(self.scan_follow)
        a.setToolTip("Choisis une bande dans « Vue » : seule celle-ci est balayée (beaucoup plus rapide).\n"
                     "« Toutes les bandes » dans « Vue » = toutes les bandes cochées.")
        a.toggled.connect(lambda *_, a=a: self.set_scan_follow(a.isChecked()))

    def set_band_enabled(self, bid, on):
        b = next((x for x in self.bands if x["id"] == bid), None)
        if b is None or bool(b["enabled"]) == bool(on):
            return
        if not on and sum(1 for x in self.bands if x["enabled"]) <= 1:
            self.set_status("Il faut garder au moins une bande à balayer.")
            return
        with self.lock:
            b["enabled"] = bool(on)
        self._bands_changed()
        n = sum(1 for x in self.bands if x["enabled"])
        self.set_status(f"{n} bande(s) balayée(s) sur {len(self.bands)}. Les fréquences des bandes non balayées "
                        f"ne sont plus surveillées.")

    def scan_all_bands(self):
        with self.lock:
            for b in self.bands:
                b["enabled"] = True
        self.scan_follow = False
        self._bands_changed()
        self.set_status("Toutes les bandes sont balayées.")

    def set_scan_follow(self, on):
        self.scan_follow = bool(on)
        self._bump()
        self.update_estimate()
        if on and self._follow_id() is None:
            self.set_status("Choisis maintenant une bande dans « Vue » : seule celle-ci sera balayée.")
        elif on:
            self.set_status("Seule la bande affichée est balayée. Les autres fréquences ne sont plus surveillées.")
        else:
            self.set_status("Toutes les bandes cochées sont de nouveau balayées.")

    def _follow_id(self):
        """Bande seule à balayer (mode « bande affichée »), sinon None."""
        if not self.scan_follow or self._zoom is not None:
            return None
        vid = getattr(self, "view_id", -1)
        return vid if any(b["id"] == vid and b["enabled"] for b in self.scan_bands()) else None

    def _scan_now(self, b):
        fid = self._follow_id()
        return bool(b["enabled"]) and (fid is None or b["id"] == fid)

    def refresh_view_combo(self):
        cur = self.view_combo.currentData()
        self.view_combo.blockSignals(True)
        self.view_combo.clear()
        self.view_combo.addItem("Toutes les bandes", -1)
        for b in self.scan_bands():
            self.view_combo.addItem(b["name"], b["id"])
        off = [b for b in self.bands if not b["enabled"]]
        if off:
            self.view_combo.insertSeparator(self.view_combo.count())
            for b in off:                            # bandes pas balayées : les choisir les réactive
                self.view_combo.addItem(f"○ {b['name']} (pas balayée)", f"on:{b['id']}")
        self.view_combo.insertSeparator(self.view_combo.count())
        self.view_combo.addItem("＋ Nouvelle bande à balayer…", "__add__")
        self.view_combo.addItem("Gérer les bandes…", "__manage__")
        idx = self.view_combo.findData(cur) if cur is not None else 0    # None = séparateur : « Vue » restait vide
        self.view_combo.setCurrentIndex(max(idx, 0))
        self._view_prev = self.view_combo.currentIndex()
        self.view_combo.blockSignals(False)
        self.on_view_changed()

    def on_view_changed(self, *_):
        v = self.view_combo.currentData()
        if isinstance(v, str):                       # entrées d'action de la liste « Vue »
            self.view_combo.blockSignals(True)
            self.view_combo.setCurrentIndex(max(0, getattr(self, "_view_prev", 0)))
            self.view_combo.blockSignals(False)
            if v == "__add__":
                self.new_band_dialog()
            elif v == "__manage__":
                self.open_settings("bands")
            elif v.startswith("on:"):
                self.show_band(int(v[3:]))
            return
        self._view_prev = self.view_combo.currentIndex()
        if self._zoom is not None:
            return
        self.view_id = -1 if v is None else v
        if self.scan_follow:
            self._bump()
            self.update_estimate()
        self._wf_show(self._wf_bid() is not None)
        self.wf_hist, self.wf_id = None, None
        self._fit_x = True
        self.update_plot()

    # ----------------------------------------------------------- zoom live
    def toggle_zoom(self, on):
        if on:
            if self._last_xy is None:
                QtWidgets.QMessageBox.information(
                    self, APP_NAME, "Lance d'abord un balayage (▶ Démarrer), zoome sur la zone qui "
                                    "t'intéresse, puis active le zoom live.")
                self.zoom_btn.setChecked(False)
                return
            vr = self.spec.getPlotItem().vb.viewRange()[0]
            self._set_zoom(vr[0], vr[1])
            self.view_id = ZOOM_ID
            self.view_combo.setEnabled(False)
            self._wf_show(True)
            self.zoom_timer.start()
            self.set_status("Zoom live : le tinySA scanne uniquement la zone visible. Zoome / déplace-toi, le "
                            "scan suit (les autres fréquences sont suspendues). " + self.zoom_info())
        else:
            if self._zoom is None:
                return
            self.zoom_timer.stop()
            with self.lock:
                self._zoom = None
            for d in (self.latest, self.maxhold, self.partial_data):
                d.pop(ZOOM_ID, None)
            self._bump()
            self.view_combo.setEnabled(True)
            self.on_view_changed()
            self.set_status("Zoom live désactivé.")

    def _band_extent(self):
        """Étendue des bandes balayées (min début, max fin) : le zoom live n'en sort pas."""
        bs = [b for b in self.scan_bands() if b["enabled"]] or self.bands
        if not bs:
            return 0.1, 6000.0
        return min(b["start"] for b in bs), max(b["stop"] for b in bs)

    def _set_zoom(self, a, b):
        self._zoom_view = (a, b)
        lo, hi = self._band_extent()
        a, b = max(0.1, lo, a), min(6000.0, hi, b)
        if b <= a:                                  # vue entièrement hors des bandes : on reste au bord
            a, b = (lo, min(hi, lo + 1.0)) if b <= lo else (max(lo, hi - 1.0), hi)
        if b - a < 0.05:
            mid = (a + b) / 2
            a, b = mid - 0.025, mid + 0.025
        with self.lock:
            self._zoom = (a, b)
        for d in (self.latest, self.maxhold, self.partial_data):
            d.pop(ZOOM_ID, None)
        self.wf_hist, self.wf_id = None, None
        self._bump()

    def zoom_follow(self):
        if self._zoom is None or self._zoom_view is None:
            return
        vr = self.spec.getPlotItem().vb.viewRange()[0]
        a, b = self._zoom_view
        tol = 0.02 * (b - a)
        if abs(vr[0] - a) > tol or abs(vr[1] - b) > tol:
            self._set_zoom(vr[0], vr[1])
            self.set_status(self.zoom_info())

    def zoom_info(self):
        """« 2.000 MHz · 201 points (pas 10.0 kHz) » : ce que scanne le zoom live."""
        z = self._zoom
        if not z:
            return ""
        c = self._cfg
        n = zoom_points(z[1] - z[0], c.get("zpts"), c["points"])
        step = (z[1] - z[0]) * 1000.0 / (n - 1)
        return f"Zoom : {z[1] - z[0]:.3f} MHz · {n} points (pas {step:.1f} kHz)"

    def zoom_on(self, row, half=1.0):
        if row >= len(self.watch):
            return
        if self._last_xy is None:
            self.set_status("Lance d'abord un balayage (▶ Démarrer) pour pouvoir zoomer.")
            return
        f = self.watch[row]["freq"]
        self.spec.getPlotItem().setXRange(f - half, f + half, padding=0)
        self._fit_x = False
        if not self.zoom_btn.isChecked():
            self.zoom_btn.setChecked(True)
        else:
            self._set_zoom(f - half, f + half)

    # ------------------------------------------------- couches : scènes › groupes
    def scene_by_name(self, name):
        return next((x for x in self.scenes if x["name"] == name), None)

    def duplicate_layer(self, key):
        """⧉ 7.63 : copie d'un groupe (dans la même scène) ou d'une scène avec tous ses groupes : couleur, priorité,
        appareils gardés ; AUCUNE fréquence copiée. -> nom de la copie."""
        import copy as _copy
        sc = self.scene_by_name(key[0])
        if sc is None:
            return None
        if key[1]:
            g = next((x for x in sc["groups"] if x["name"] == key[1]), None)
            if g is None:
                return None
            ng = _copy.deepcopy(g)
            ng["name"] = copy_name(g["name"], [x["name"] for x in sc["groups"]])
            sc["groups"].insert(sc["groups"].index(g) + 1, ng)
            new = ng["name"]
            what = f"{sc['name']} › {new}"
        else:
            ns = _copy.deepcopy(sc)
            ns["name"] = copy_name(sc["name"], [x["name"] for x in self.scenes])
            self.scenes.insert(self.scenes.index(sc) + 1, ns)
            new = what = ns["name"]
        self.rebuild_tree()
        self.undo_track()
        self.set_status(TR("⧉ Copie créée : « {} » (sans fréquences). Renomme-la par clic droit si besoin.").format(what))
        return new

    def ensure_group(self, scene, group=""):
        """Crée la scène (et le groupe) s'ils n'existent pas encore."""
        scene, group = (scene or "").strip(), (group or "").strip()
        if not scene:
            return
        sc = self.scene_by_name(scene)
        if sc is None:
            pal = theme_pal(self.theme)                  # 7.54.1 : couleurs qui suivent le thème
            sc = dict(name=scene, color=pal[len(self.scenes) % len(pal)], groups=[])
            self.scenes.append(sc)
        if group and not any(g["name"] == group for g in sc["groups"]):
            n = sum(len(x["groups"]) for x in self.scenes)
            pal = theme_pal(self.theme)
            sc["groups"].append(dict(name=group, color=pal[(n + 1) % len(pal)]))

    def group_color(self, scene, group):
        sc = self.scene_by_name(scene)
        if sc is None:
            return None
        for g in sc["groups"]:
            if g["name"] == group:
                return g["color"]
        return sc["color"]

    def in_scope(self, w):
        return scope_match(self.scope, w["scene"], w["group"])

    def scope_ws(self):
        return [w for w in self.watch if self.in_scope(w)]

    @staticmethod
    def layer_text(w):
        if w["scene"] and w["group"]:
            return f'{w["scene"]} › {w["group"]}'
        return w["scene"] or w["group"] or ""

    def scope_text(self):
        if not self.scope:
            return "Global"
        return " + ".join((f"{a} › {b}" if b else (a or "Sans scène")) for a, b in self.scope)

    def _scope_preset(self):
        """Scène / groupe proposés par défaut pour une nouvelle fréquence (la couche active, si c'est un groupe)."""
        if self.scope and len(self.scope) == 1 and self.scope[0][0]:
            return self.scope[0][0], (self.scope[0][1] or "")
        return "", ""

    def _tree_counts(self):
        cnt = {}
        for w in self.watch:
            keys = [(w["scene"], None)]
            if w["group"]:
                keys.append((w["scene"], w["group"]))
            for k in keys:
                c = cnt.setdefault(k, [0, 0, 0])
                c[0] += 1
                if w["state"] == "occ":
                    c[1] += 1
                    if self.is_keep_free(w["status"]):
                        c[2] += 1
                if w.get("absent"):
                    c[2] += 1
        return cnt

    @staticmethod
    def _tree_label(name, c):
        txt = f"{name}   ·  {c[0]} fréq."
        if c[2]:
            txt += f"  ·  ⚠ {c[2]} alarme(s)"
        elif c[1]:
            txt += f"  ·  {c[1]} occupée(s)"
        return txt

    def rebuild_tree(self):
        tree = self.layer_tree
        cnt = self._tree_counts()
        self._tree_lock = True
        tree.clear()
        self._tree_items, self._tree_sig = {}, {}

        def mk(parent, scene, group, name, color):
            it = QtWidgets.QTreeWidgetItem()
            it.setText(0, self._tree_label(name, cnt.get((scene, group), [0, 0, 0])))
            it.setIcon(0, color_icon(color))
            it.setData(0, Qt.ItemDataRole.UserRole, key_enc(scene, group))
            if parent is None:
                tree.addTopLevelItem(it)
            else:
                parent.addChild(it)
            self._tree_items[(scene, group)] = (it, name)
            return it

        for sc in self.scenes:
            top = mk(None, sc["name"], None, sc["name"] + self.dev_tag(sc["name"]), sc["color"])
            for g in sc["groups"]:
                mk(top, sc["name"], g["name"], g["name"] + self.prio_mark(g)
                   + (f"  · {' + '.join(rx_short(k) for k in self.group_rxs(g))}" if self.group_rxs(g) else ""),
                   g["color"])
        if self.scenes and any(w["scene"] == "" for w in self.watch):
            mk(None, "", None, "Sans scène", self.theme["st_none"])
        tree.expandAll()
        cur = list(self.scope or [])
        valid = [k for k in cur if k in self._tree_items]
        for k in valid:
            self._tree_items[k][0].setSelected(True)
        self._tree_lock = False
        if cur != valid:
            self.set_scope(valid or None)
        else:
            self.update_scope_ui()
        self._layer_compact()

    def list_tips(self):
        QtWidgets.QMessageBox.information(self, TR("Astuces de la liste"), getattr(self, "_list_tips", ""))

    def _layer_compact(self):
        """8.1 (DA épurée) : sans scène, le cadre « Classer par scène › groupe » se réduit à sa rangée de boutons
        (pas d'arbre vide, pas de ligne « Couche active » qui répète le compteur de la liste)."""
        has = bool(self.scenes)
        for w_ in (self.layer_tree, self.focus_chk, self.layer_lbl):
            w_.setVisible(has)
        try:
            sp = self.freq_split
            row = self.layer_box.sizeHint().height() if not has else 230
            tot = sum(sp.sizes()) or 830
            sp.setSizes([min(row, tot // 2), max(200, tot - min(row, tot // 2))])
        except Exception:  # noqa: BLE001
            pass

    def update_tree_counts(self):
        cnt = self._tree_counts()
        th = self.theme
        for k, (it, name) in self._tree_items.items():
            c = cnt.get(k, [0, 0, 0])
            txt = self._tree_label(name, c)
            col = th["st_occ"] if c[2] else (th["st_weak"] if c[1] else th["ui_text"])
            if self._tree_sig.get(k) != (txt, col):
                self._tree_sig[k] = (txt, col)
                it.setText(0, txt)
                it.setForeground(0, QtGui.QBrush(QtGui.QColor(col)))

    def update_scope_ui(self):
        n = len(self.scope_ws())
        if self.scope:
            self.layer_lbl.setText(f"Couche active : {self.scope_text()} — {n} fréquence(s)")
        else:
            self.layer_lbl.setText(f"Couche active : Global — {len(self.watch)} fréquence(s)")
        self.focus_chk.setEnabled(bool(self.scope))
        col = self.theme["ui_accent"]
        self.global_btn.setStyleSheet(
            "QPushButton{background:%s;color:%s;font-weight:600;border-color:%s;}" % (col, contrast_text(col), col)
            if not self.scope else "")
        self.update_title()

    def _site_feed(self, bid, f, l):
        """📍 Balayage d'un tinySA posé à un lieu : rangé dans le direct et le max hold de ce lieu. Avec deux tinySA à
        deux lieux, la vue Global prend le plus fort des deux (le pire cas) -> (F, L) à garder en global."""
        mine = self.dev_scenes.get(self.band_src.get(bid, 0), [])
        if not mine:
            return f, l
        now = time.time()
        for site in mine:                          # un tinySA peut couvrir plusieurs scènes : chacune reçoit le balayage
            self.site_live.setdefault(site, {})[bid] = (f, l, now)
            if site not in self.site_mh:
                self._site_mh_t0[site] = now
            mh = self.site_mh.setdefault(site, {})
            old = mh.get(bid)
            mh[bid] = (f, np.maximum(old[1], l) if old is not None and old[1].shape == l.shape else l.copy())
            if site not in self._site_base:
                self._site_base[site] = next((d for d in self.site_scans if d["name"] == site), None)
        if self.multi_site_on():
            stale = max(15.0, 4 * self.last_cycle)
            for s_, bands in self.site_live.items():
                x = bands.get(bid)
                if s_ not in mine and x is not None and now - x[2] <= stale and x[1].shape == l.shape:
                    l = np.maximum(l, x[1])
        return f, l

    def _div_feed(self, bid, f, l):
        """🔀 Garde le dernier balayage de chaque tinySA pour cette bande -> meilleur des deux, point par point."""
        now = time.time()
        buf = self.div_buf.setdefault(bid, {})
        buf[self.band_src.get(bid, 0)] = (f, l, now)
        r = diversity_merge(buf, now, max(10.0, 2.5 * self.last_cycle))
        if r is None:
            return f, l
        F, L, src = r
        self.div_src[bid] = (F, src, now)
        return F, L

    def site_fresh(self, site):
        """Direct d'un lieu (bandes récentes) -> (F, L) trié, ou (None, None)."""
        now, stale = time.time(), max(15.0, 4 * self.last_cycle)
        segs = [(f, l) for f, l, t in self.site_live.get(site, {}).values() if now - t <= stale]
        if not segs:
            return None, None
        F, L = np.concatenate([x[0] for x in segs]), np.concatenate([x[1] for x in segs])
        o = np.argsort(F)
        return F[o], L[o]

    def forget_site(self, site):
        """Oublie le max hold EN MÉMOIRE d'une scène (sinon _sites_tick recrée son scan gardé 30 s plus tard)."""
        self.site_mh.pop(site, None)
        self._site_mh_t0.pop(site, None)
        self._site_base.pop(site, None)

    def _sites_tick(self, now):
        """Toutes les 30 s : le max hold de chaque lieu est gardé tout seul (fusionné au scan déjà gardé)."""
        if now < self._sites_next or not self.site_mh:
            return
        self._sites_next = now + 30.0
        for site in [s_ for s_ in self.site_mh if self.scene_by_name(s_) is None]:
            self.forget_site(site)               # scène supprimée (ou nouveau show) : son scan ne revient pas
        for site, bands in self.site_mh.items():
            segs = sorted(bands.values(), key=lambda x: float(x[0][0]))
            F, L = np.concatenate([x[0] for x in segs]), np.concatenate([x[1] for x in segs])
            base = self._site_base.get(site)
            rbw, est = self.scan_rbw(F)
            if base is not None:
                F, L = merge_scans([(base["f"], base["l"]), (F, L)])
                rbw = rbw_merge(base.get("rbw"), rbw) if "rbw" in base else rbw
            if F is None:
                continue
            self.site_scans = site_replace(self.site_scans, site_scan_doc(site, F, L, now, rbw=rbw, rbw_est=est))
        self.update_site_curve()

    def view_sites(self):
        """Lieux à montrer sur le spectre : la (les) scène(s) choisie(s) dans « Mes fréquences » qui sont des lieux
        (un tinySA y est, ou un scan y est gardé). None = vue normale (Global, ou scène qui n'est pas un lieu)."""
        if not self.scope or not getattr(self, "sites_btn", None) or not self.sites_btn.isChecked():
            return None
        if not any(self.dev_scenes.values()):     # aucun tinySA rattaché à une scène : le direct reste celui de
            return None                            # tous (sinon une scène avec un scan gardé n'avait plus de direct)
        known = set(self.site_live) | {d["name"] for d in self.site_scans} | {x for v in self.dev_scenes.values() for x in v}
        sel = sorted({k[0] for k in self.scope if k and k[0] in known})
        return sel or None

    def set_dev_site(self, dev, site):
        """« Le tinySA n° dev est à : site » ("" = aucun lieu) : une seule scène."""
        self.set_dev_scenes(dev, [site] if (site or "").strip() else [])

    def toggle_dev_scene(self, dev, scene, on):
        cur = list(self.dev_scenes.get(int(dev), []))
        if on and scene not in cur:
            cur.append(scene)
        elif not on and scene in cur:
            cur.remove(scene)
        self.set_dev_scenes(dev, cur)

    def set_dev_scenes(self, dev, scenes):
        """📡 Les scènes que surveille le tinySA n° dev (une ou plusieurs ; vide = aucune) : appliqué tout de suite."""
        dev = int(dev)
        scenes = list(dict.fromkeys(x.strip() for x in scenes if (x or "").strip()))
        if scenes:
            self.dev_scenes[dev] = scenes
        else:
            self.dev_scenes.pop(dev, None)
        if self.dev_ids.get(dev):                  # tinySA numéroté : ses scènes le suivront s'il change de port
            self.devid_scenes[self.dev_ids[dev]] = scenes
        self._bump()
        self.rebuild_tree()
        self.update_site_curve()
        self.update_plot()
        who = f"{dev_ord(dev)} tinySA ({self.dev_name(dev)})"
        self.set_status(f"📡 {who} : " + (", ".join(scenes) if scenes else "aucune scène")
                        + (" · scènes différentes : chaque tinySA balaye toutes les bandes chez lui"
                           if self.multi_site_on() else ""))

    def dev_tag(self, scene):
        """« 📡 Plateau » : quel(s) tinySA surveille(nt) cette scène (dans l'arbre, dès qu'un rattachement existe : il
        change ce que montre le spectre, il ne doit pas être caché)."""
        if not any(self.dev_scenes.values()):
            return ""
        who = [self.dev_name(d) for d in sorted(self.dev_scenes) if scene in self.dev_scenes[d]]
        return f"   📡 {' + '.join(who)}" if who else ""

    def on_devid(self, dev, n):
        """🔢 Numéro gravé dans le tinySA lu à la connexion : s'il a déjà été rattaché à des scènes sous ce numéro,
        elles le suivent (ex. les deux tinySA ont été branchés à l'envers)."""
        self.dev_ids[dev] = int(n)
        if not n:
            return
        want = self.devid_scenes.get(int(n))
        if want is not None and want != self.dev_scenes.get(dev, []):
            self.dev_scenes[dev] = list(want)
            if not want:
                self.dev_scenes.pop(dev, None)
            self._bump()
            self.rebuild_tree()
            self.set_status(f"🔁 tinySA n° {n} reconnu en {dev_ord(dev)} : ses scènes le suivent "
                            f"({', '.join(want) or 'aucune'}).")
        elif want is None and self.dev_scenes.get(dev):
            self.devid_scenes[int(n)] = list(self.dev_scenes[dev])
        if self._devdlg is not None:
            self._devdlg.refresh()

    def identify_device(self, dev):
        """👋 Fait clignoter l'écran du tinySA n° dev (pour savoir lequel est lequel)."""
        ws = [w for i, w in enumerate(self.workers) if getattr(w, "slot", i) == dev and w.isRunning()]
        if not ws:
            self.set_status("👋 Lance d'abord ▶ Démarrer : il faut être connecté au tinySA pour le faire clignoter.")
            return False
        ws[0].cmdq.put(("identify",))
        self.set_status(f"👋 Regarde les tinySA : celui dont l'écran clignote en orange est le "
                        f"{dev_ord(dev)} ({self.dev_name(dev)}).")
        return True

    def number_device(self, dev, n):
        """🔢 Grave un numéro dans le tinySA (gardé même débranché, même sur un autre PC)."""
        ws = [w for i, w in enumerate(self.workers) if getattr(w, "slot", i) == dev and w.isRunning()]
        if not ws:
            self.set_status("🔢 Lance d'abord ▶ Démarrer : il faut être connecté au tinySA pour le numéroter.")
            return False
        ws[0].cmdq.put(("setid", int(n)))
        if self.dev_scenes.get(dev):
            self.devid_scenes[int(n)] = list(self.dev_scenes[dev])
        self.set_status(f"🔢 Numéro {n} gravé dans le {dev_ord(dev)} tinySA.")
        return True

    def open_devices(self):
        if self._devdlg is not None:
            self._devdlg.raise_()
            return
        self._devdlg = DevicesDialog(self)
        self._devdlg.show()

    def _build_sites_menu(self):
        m = self.sites_menu
        m.clear()
        m.addAction("📡 Mes tinySA et leurs scènes…").triggered.connect(lambda *_: self.open_devices())
        names = list(dict.fromkeys([x["name"] for x in self.scenes] + [d["name"] for d in self.site_scans]
                                   + [x for v in self.dev_scenes.values() for x in v]))
        for d_ in self.dev_list():
            sm = m.addMenu(f"📡 {dev_ord(d_)} tinySA ({self.dev_name(d_)}) surveille…")
            for n_ in names:
                a = sm.addAction(n_)
                a.setCheckable(True)
                a.setChecked(n_ in self.dev_scenes.get(d_, []))
                a.triggered.connect(lambda *_, d_=d_, n_=n_, a=a: self.toggle_dev_scene(d_, n_, a.isChecked()))
        m.addSeparator()
        a = m.addAction("👁 Afficher les lieux sur le spectre")
        a.setCheckable(True)
        a.setChecked(self.sites_btn.isChecked())
        a.triggered.connect(lambda *_, a=a: self.sites_btn.setChecked(a.isChecked()))
        m.addAction("📍 Scans par lieu (fusion, export)…").triggered.connect(lambda *_: self.open_sites())

    def update_site_curve(self):
        """📍 Scan gardé du lieu choisi (scène sélectionnée dans « Mes fréquences »), ou fusion de tous en Global."""
        if not hasattr(self, "sitecurve"):
            return
        self.update_site_bar()
        docs = sites_for_scope(self.site_scans, self.scope) if self.sites_btn.isChecked() else []
        if not docs:
            self.sitecurve.setData([], [])
            self.site_lbl.setVisible(False)
            return
        F, L = merge_scans([(d["f"], d["l"]) for d in docs]) if len(docs) > 1 else (np.asarray(docs[0]["f"]),
                                                                                    np.asarray(docs[0]["l"]))
        if F is None:
            return
        F, L = gap_nan(F, L)
        scs = {site_doc_scene(d) for d in docs}
        if self.scope and len(scs) == 1 and len(docs) > 1:      # une scène, plusieurs scans gardés : leur fusion
            sc = next(iter(scs))
            col = self.scene_color(sc)
            txt = (f"📍 {sc} : en direct · pointillés = fusion de {len(docs)} scans gardés"
                   if self.site_fresh(sc)[0] is not None or not any(self.dev_scenes.values())
                   else f"📍 {sc} : fusion de {len(docs)} scans gardés")
        elif len(docs) == 1:
            col = self.scene_color(docs[0]["name"]) if self.scene_by_name(docs[0]["name"]) else "#e5e7eb"
            when = datetime.fromtimestamp(docs[0]["t"]).strftime("%d/%m %H:%M") if docs[0]["t"] else ""
            if self.scope and self.site_fresh(docs[0]["name"])[0] is not None:
                txt = f"📍 {docs[0]['name']} : en direct (pointillés = max gardé)"
            elif self.scope and not any(self.dev_scenes.values()):
                txt = f"📍 {docs[0]['name']} : scan gardé en pointillés" + (f" ({when})" if when else "")
            elif self.scope:
                txt = f"📍 {docs[0]['name']} : pas de tinySA ici en ce moment · dernier spectre gardé" + (
                    f" ({when})" if when else "")
            else:
                txt = f"📍 Scan gardé : {docs[0]['name']}" + (f" ({when})" if when else "")
        else:
            col = "#e5e7eb"
            txt = f"📍 Tous les lieux : fusion de {len(docs)} scans"
        self.sitecurve.setPen(pg.mkPen(col, width=1.2, style=Qt.PenStyle.DashLine))
        self.sitecurve.setData(F, L)
        self.site_lbl.setText(txt, color=col)
        self.site_lbl.setVisible(True)
        self._place_site_lbl()

    def update_site_bar(self):
        """Bandeau au-dessus du spectre quand la scène regardée n'a AUCUN tinySA rattaché (son direct est donc vide) :
        qui surveille quoi, et en un clic « ce tinySA est ici » ou « tout le site » (retour de Clément 7.26.1 : « j'avais
        mal assigné le tiny, il faut que ce soit intuitif »)."""
        bar = getattr(self, "site_bar", None)
        if bar is None:
            return
        sites = self.view_sites()
        watched = {x for v in self.dev_scenes.values() for x in v}
        lost = [x for x in (sites or []) if x not in watched]
        n_ = self.site_bar_btns.count()
        for _ in range(n_ if isinstance(n_, int) else 0):      # (faux Qt des tests : count() n'est pas un entier)
            it = self.site_bar_btns.takeAt(0)
            if it is not None and it.widget() is not None:
                it.widget().deleteLater()
        if not sites or len(lost) < len(sites):
            bar.setVisible(False)
            return
        sc = lost[0]
        where = " · ".join(f"{dev_ord(d)} tinySA ({self.dev_name(d)}) : {', '.join(self.dev_scenes[d])}"
                           for d in sorted(self.dev_scenes) if self.dev_scenes[d])
        self.site_bar_lbl.setText(f"📡 Aucun tinySA ne surveille « {sc} » : pas de direct ici. Actuellement : {where}.")
        for d in self.dev_list():
            b = QtWidgets.QPushButton(f"📡 Le {dev_ord(d)} tinySA ({self.dev_name(d)}) est ici")
            b.setToolTip(f"Ce tinySA surveille désormais « {sc} » (à la place de ses scènes actuelles).")
            b.clicked.connect(lambda *_, d=d, sc=sc: self.set_dev_scenes(d, [sc]))
            self.site_bar_btns.addWidget(b)
        g_ = QtWidgets.QPushButton("🌐 Tout le site")
        g_.setToolTip("Revenir à la vue globale : le direct de tous les tinySA.")
        g_.clicked.connect(lambda *_: self.go_global())
        self.site_bar_btns.addWidget(g_)
        o_ = QtWidgets.QPushButton("⚙")
        o_.setToolTip("Mes tinySA et leurs scènes : qui surveille quoi.")
        o_.clicked.connect(lambda *_: self.open_devices())
        self.site_bar_btns.addWidget(o_)
        bar.setVisible(True)

    def _place_site_lbl(self):
        if getattr(self, "site_lbl", None) is not None and self.site_lbl.isVisible():
            (x0, x1), (y0, y1) = self.spec.getPlotItem().vb.viewRange()
            self.site_lbl.setPos(x0 + (x1 - x0) * 0.01, y1 - (y1 - y0) * 0.24)   # sous les noms des fréquences

    def scene_color(self, name):
        sc = self.scene_by_name(name)
        return sc["color"] if sc else "#e5e7eb"

    def set_scope(self, scope):
        self.scope = [tuple(k) for k in scope] if scope else None
        self.update_site_curve()
        for w in self.watch:
            w["t_acc"] = None
            w["sig"] = None
        self._refresh_focus()
        self.update_scope_ui()
        self.update_watch_table(force=True)
        self._update_markers()
        if self.wall is not None and self.wall.isVisible():
            self.wall.relayout()

    def on_tree_sel(self):
        if self._tree_lock:
            return
        keys = []
        for it in self.layer_tree.selectedItems():
            k = key_dec(it.data(0, Qt.ItemDataRole.UserRole))
            if k is not None:
                keys.append(k)
        self.set_scope(keys or None)

    def go_global(self):
        self._tree_lock = True
        self.layer_tree.clearSelection()
        self._tree_lock = False
        self.set_scope(None)

    def _layers_changed(self):
        for w in self.watch:
            w["sig"] = None
        self.rebuild_tree()
        self._refresh_focus()
        self.update_watch_table(force=True)
        self._update_markers()
        if self.wall is not None and self.wall.isVisible():
            self.wall.relayout()

    def _sel_layer_key(self):
        its = self.layer_tree.selectedItems()
        return key_dec(its[0].data(0, Qt.ItemDataRole.UserRole)) if its else None

    def add_scene(self):
        txt, ok = self.ask_name("scene", "Nouvelle scène", "Nom de la scène (ex. Main Stage) :")
        name = txt.strip()
        if ok and name:
            self.ensure_group(name)
            self._layers_changed()
            return name
        return None

    def _pick_scene(self):
        k = self._sel_layer_key()
        if k is not None and k[0] and self.scene_by_name(k[0]) is not None:
            return k[0]
        if len(self.scenes) == 1:
            return self.scenes[0]["name"]
        if self.scenes:
            name, ok = QtWidgets.QInputDialog.getItem(self, "Scène", "Dans quelle scène ?",
                                                      [x["name"] for x in self.scenes], 0, False)
            return name if ok else None
        return None

    def add_group(self, scene=None):
        """Crée un groupe (et la scène si besoin) ; renvoie (scène, groupe) ou None."""
        scene = scene or self._pick_scene()
        if not scene:
            txt, ok = self.ask_name("scene", "Nouvelle scène", "Il n'y a pas encore de scène. Nom de la scène :")
            if not (ok and txt.strip()):
                return None
            scene = txt.strip()
        txt, ok = self.ask_name("group", "Nouveau groupe", f"Nom du groupe / de l'artiste dans « {scene} » :")
        name = txt.strip()
        if ok and name:
            self.ensure_group(scene, name)
            self._layers_changed()
            return scene, name
        return None

    def assign_rows(self, rows, scene, group=""):
        if group and not scene:
            scene = DEFAULT_SCENE
        self.ensure_group(scene, group)
        for r in rows:
            if r < len(self.watch):
                self.watch[r]["scene"], self.watch[r]["group"] = scene, group
        self._layers_changed()

    def assign_menu(self, parent):
        m = QtWidgets.QMenu(parent)
        for sc in self.scenes:
            sm = m.addMenu(color_icon(sc["color"]), sc["name"])
            a = sm.addAction(f"{sc['name']} (toute la scène)")
            a.setData(key_enc(sc["name"]))
            sm.addSeparator()
            for g in sc["groups"]:
                a = sm.addAction(color_icon(g["color"]), g["name"])
                a.setData(key_enc(sc["name"], g["name"]))
            sm.addSeparator()
            a = sm.addAction("＋ Nouveau groupe…")
            a.setData("N" + SEP + sc["name"])
        if self.scenes:
            m.addSeparator()
        a = m.addAction("＋ Nouvelle scène + groupe…")
        a.setData("NS" + SEP)
        a = m.addAction("— Aucune scène")
        a.setData("X" + SEP)
        return m

    def _assign_action(self, rows, d):
        """Traite l'action d'un menu « affecter » ; False si ce n'en est pas une."""
        if not (isinstance(d, str) and SEP in d):
            return False
        p = d.split(SEP)
        if p[0] == "X":
            self.assign_rows(rows, "", "")
        elif p[0] == "S" and len(p) == 2:
            self.assign_rows(rows, p[1], "")
        elif p[0] == "G" and len(p) == 3:
            self.assign_rows(rows, p[1], p[2])
        elif p[0] == "N" and len(p) == 2:
            r = self.add_group(p[1])
            if r:
                self.assign_rows(rows, r[0], r[1])
        elif p[0] == "NS":
            txt, ok = self.ask_name("scene", "Nouvelle scène", "Nom de la scène :")
            if ok and txt.strip():
                r = self.add_group(txt.strip())
                if r:
                    self.assign_rows(rows, r[0], r[1])
        return True

    def layer_popup(self, rows):
        m = self.assign_menu(self)
        act = m.exec(QtGui.QCursor.pos())
        if act is not None:
            self._assign_action(rows, act.data())

    def rename_layer(self, key):
        scene, group = key
        old = group if group else scene
        txt, ok = self.ask_name("scene" if group is None else "group", "Renommer", "Nouveau nom :", old)
        new = txt.strip()
        sc = self.scene_by_name(scene)
        if not ok or not new or new == old or sc is None:
            return
        if group is None:
            if self.scene_by_name(new) is not None:
                QtWidgets.QMessageBox.information(self, APP_NAME, "Une scène porte déjà ce nom.")
                return
            sc["name"] = new
            for w in self.watch:
                if w["scene"] == scene:
                    w["scene"] = new
            if self.scope:
                self.scope = [(new if k[0] == scene else k[0], k[1]) for k in self.scope]
        else:
            if any(g["name"] == new for g in sc["groups"]):
                QtWidgets.QMessageBox.information(self, APP_NAME, "Un groupe porte déjà ce nom dans cette scène.")
                return
            for g in sc["groups"]:
                if g["name"] == group:
                    g["name"] = new
            for w in self.watch:
                if w["scene"] == scene and w["group"] == group:
                    w["group"] = new
            if self.scope:
                self.scope = [(k[0], new if (k[0] == scene and k[1] == group) else k[1]) for k in self.scope]
        self._layers_changed()

    def delete_layer(self, key):
        scene, group = key
        sc = self.scene_by_name(scene)
        if sc is None:
            return
        if group is None:
            n = sum(1 for w in self.watch if w["scene"] == scene)
            msg = (f"Supprimer la scène « {scene} » et ses {len(sc['groups'])} groupe(s) ?\n"
                   f"Les {n} fréquence(s) restent dans ta liste, sans scène.")
        else:
            n = sum(1 for w in self.watch if w["scene"] == scene and w["group"] == group)
            msg = (f"Supprimer le groupe « {group} » ?\n"
                   f"Les {n} fréquence(s) restent dans la scène « {scene} », sans groupe.")
        if QtWidgets.QMessageBox.question(self, APP_NAME, msg) != QtWidgets.QMessageBox.StandardButton.Yes:
            return
        if group is None:
            self.scenes.remove(sc)
            for w in self.watch:
                if w["scene"] == scene:
                    w["scene"], w["group"] = "", ""
        else:
            sc["groups"] = [g for g in sc["groups"] if g["name"] != group]
            for w in self.watch:
                if w["scene"] == scene and w["group"] == group:
                    w["group"] = ""
        self._layers_changed()

    def pick_layer_color(self, key):
        scene, group = key
        sc = self.scene_by_name(scene)
        if sc is None:
            return
        tgt = sc if group is None else next((g for g in sc["groups"] if g["name"] == group), None)
        if tgt is None:
            return
        c = QtWidgets.QColorDialog.getColor(QtGui.QColor(tgt["color"]), self, "Couleur")
        if c.isValid():
            tgt["color"] = c.name()
            self._layers_changed()

    def layer_action(self, what):
        k = self._sel_layer_key()
        if k is None or self.scene_by_name(k[0]) is None:
            self.set_status("Sélectionne d'abord une scène ou un groupe dans l'arbre.")
            return
        if what == "rename":
            self.rename_layer(k)
        elif what == "delete":
            self.delete_layer(k)

    def layer_menu(self, pos):
        it = self.layer_tree.itemAt(pos)
        key = key_dec(it.data(0, Qt.ItemDataRole.UserRole)) if it is not None else None
        real = key is not None and self.scene_by_name(key[0]) is not None
        m = QtWidgets.QMenu(self)
        a_scene = m.addAction("＋ Nouvelle scène…")
        a_group = m.addAction("＋ Nouveau groupe…")
        a_imp = a_asg = a_ren = a_col = a_del = a_mu_on = a_mu_off = None
        rows = self._sel_rows()
        if real:
            m.addSeparator()
            a_imp = m.addAction("📥 Importer un CSV dans " + ("ce groupe…" if key[1] else "cette scène…"))
            if rows:
                a_asg = m.addAction(f"Affecter les {len(rows)} fréquence(s) sélectionnée(s) ici")
            m.addSeparator()
            lws = self.layer_ws(key)
            if lws:
                if not all(w.get("muted") for w in lws):
                    a_mu_on = m.addAction("💤 Tout éteindre (je sais) : pas d'alarme ABSENT")
                if any(w.get("muted") for w in lws):
                    a_mu_off = m.addAction("🔔 Tout rallumer")
            a_dup = m.addAction("⧉ Dupliquer ce groupe (sans les fréquences)" if key[1]
                                else "⧉ Dupliquer cette scène et ses groupes (sans les fréquences)")
            a_ren = m.addAction("Renommer…")
            a_col = m.addAction("Couleur…")
            sub = QtWidgets.QMenu("🔔 Priorité des alarmes" + (" (ce groupe)" if key[1] else " (tous ses groupes)"), m)
            a_prio = {sub.addAction(f"{lab}{'  ✔' if cur else ''}"): p
                      for p, lab, cur in ((2, "❗ Critique : son répété jusqu'à acquittement", self._cur_prio(key) == 2),
                                          (1, "Normale : bip à l'apparition", self._cur_prio(key) == 1),
                                          (0, "🔕 Info : pas de son", self._cur_prio(key) == 0))}
            m.addMenu(sub)
            rxm = m.addMenu("📻 Appareils de ce groupe (coordination)" if key[1] else "📻 Appareils de ses groupes (coordination)")
            rxm.setToolTipsVisible(True)
            cur_rx = self._cur_rxs(key)
            a_ = rxm.addAction("Aucun (réglages par défaut)")
            a_.setCheckable(True)
            a_.setChecked(not cur_rx)
            a_.triggered.connect(lambda *_, key_=key: self.set_group_rx(key_, ""))
            rxm.addSeparator()
            for k_, n_ in [(k, n) for k, n, _d, _w in rx_all()]:   # plusieurs possibles : coord entre appareils
                a_ = rxm.addAction(n_)
                a_.setCheckable(True)
                a_.setChecked(k_ in cur_rx)
                a_.triggered.connect(lambda *_, k_=k_, key_=key, a_=a_: self.toggle_group_rx(key_, k_, a_.isChecked()))
            if self.expert:                         # 7.61 : un modèle précis, avec sa bande (mode expert seulement)
                rxm.addSeparator()
                a_ = rxm.addAction("📚 Depuis la bibliothèque (avec sa bande)…")
                a_.setToolTip("Choisis le modèle exact (ex. SLX-D G58) : il est ajouté à ce groupe avec sa bande ;\n"
                              "Vérifier le plan, Coordonner et la fréquence de secours restent dans cette bande.")
                a_.triggered.connect(lambda *_, key_=key: self.pick_library_rx(key_))
            if self.expert and not key[1]:          # 📡 quel(s) tinySA surveille(nt) cette scène
                dm = m.addMenu("📡 Surveillée par")
                for d_ in self.dev_list():
                    a_ = dm.addAction(f"{dev_ord(d_)} tinySA ({self.dev_name(d_)})")
                    a_.setCheckable(True)
                    a_.setChecked(key[0] in self.dev_scenes.get(d_, []))
                    a_.triggered.connect(lambda *_, d_=d_, a_=a_, n_=key[0]: self.toggle_dev_scene(d_, n_, a_.isChecked()))
                dm.addSeparator()
                dm.addAction("📡 Mes tinySA et leurs scènes…").triggered.connect(lambda *_: self.open_devices())
            a_del = m.addAction("Supprimer")
        act = m.exec(self.layer_tree.viewport().mapToGlobal(pos))
        if act is None:
            return
        if act is a_scene:
            self.add_scene()
        elif act is a_group:
            if real:
                self.add_group(key[0])
            else:
                self.add_group()
        elif act is a_imp:
            self.import_into(key)
        elif act is a_asg:
            self.assign_rows(rows, key[0], key[1] or "")
        elif act is not None and act in (a_mu_on, a_mu_off):
            self.set_muted(self.layer_ws(key), act is a_mu_on)
        elif act is a_dup:
            self.duplicate_layer(key)
        elif act is a_ren:
            self.rename_layer(key)
        elif act is a_col:
            self.pick_layer_color(key)
        elif act is a_del:
            self.delete_layer(key)
        elif real and act in a_prio:
            self.set_prio(key, a_prio[act])

    def _cur_prio(self, key):
        """Priorité d'un groupe (ou de la scène si tous ses groupes sont identiques, sinon -1)."""
        sc = self.scene_by_name(key[0])
        if sc is None:
            return -1
        ps = {int(g.get("prio", 1)) for g in sc["groups"] if not key[1] or g["name"] == key[1]}
        return ps.pop() if len(ps) == 1 else -1

    def import_into(self, key):
        paths, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, "Importer des fréquences", "", "CSV / texte (*.csv *.txt *.tsv);;Tous les fichiers (*)")
        for p in paths:
            self.open_import(decode_text(Path(p).read_bytes()), os.path.basename(p),
                             preset=(key[0], key[1] or ""))

    # ------------------------------------------------------ scan ciblé (focus)
    def scan_bands(self):
        """Bandes réellement balayées : zones ciblées autour de la couche active, sinon tes bandes."""
        return self._focus_bands if self._focus_bands else self.bands

    def _on_focus_toggled(self, on):
        self._refresh_focus()
        if on and self.scope:
            self.set_status("🎯 Scan ciblé : seules les zones autour des fréquences de la couche active sont "
                            "balayées. Repasse en Global pour tout revoir.")
        elif on:
            self.set_status("Le scan ciblé s'active dès qu'une scène ou un groupe est sélectionné.")

    def _refresh_focus(self):
        new = []
        if self.scope and self.focus_chk.isChecked():
            fr = [x for w in self.watch if self.in_scope(w) for x in block_points(w["freq"], w.get("bw"))]
            for i, (a, b, n) in enumerate(focus_plan(fr, self._cfg["points"])):
                new.append(dict(id=-100 - i, name=f"{a:.2f}–{b:.2f} MHz", start=a, stop=b,
                                step=round((b - a) * 1000.0 / (n - 1), 6), enabled=True))
        sig = [(b["start"], b["stop"], b["step"]) for b in new]
        if sig != self._focus_sig:
            with self.lock:
                self._focus_bands, self._focus_sig = new, sig
            self._bump()
            ids = {b["id"] for b in self.scan_bands()}
            for d in (self.latest, self.latest_t, self.maxhold, self.partial_data, self.history, self.unk_now):
                for k in [k for k in d if k != ZOOM_ID and k not in ids]:
                    d.pop(k, None)
            self._fit_x = True
            self.refresh_view_combo()
        self.update_estimate()

    # ------------------------------------------------- fréquences surveillées
    def _append_watch(self, name, freq, status="", thr=None, scene="", group="", bw=0.0):
        scene, group = (scene or "").strip(), (group or "").strip()
        if group and not scene:
            scene = DEFAULT_SCENE
        self.ensure_group(scene, group)
        band, cat = spectrum_info(freq, self.plan, self.tv)
        st_ = self.state_by_name(self.state_cur) if getattr(self, "state_cur", "") else None
        if st_ is not None and int(round(freq * 1000)) not in st_["keys"]:     # 📸 nouvelle = active dans l'état
            st_["keys"] = sorted(st_["keys"] + [int(round(freq * 1000))])
        self.watch.append(dict(name=name, freq=freq, status=status, level=None, max=None,
                               state=None, peak=None, since=0.0, sig=None, thr=thr,
                               occw=OccWindow(self.occ_combo.currentData() or 60), t_acc=None,
                               band=band, cat=cat, scene=scene, group=group, free_since=None, absent=False,
                               bw=float(bw or 0.0)))     # bw > 0 : bloc large (Spectera / WMAS), en MHz

    def sort_watch(self):
        self.watch.sort(key=lambda w: w["freq"])

    def is_keep_free(self, name):
        return bool(name) and any(s["name"] == name and s.get("free") for s in self.statuses)

    def _strong_changed(self):
        self.strong_line.setValue(self.strong_spin.value())
        self.strong_line.setVisible(self.strong_chk.isChecked())
        if not self.strong_chk.isChecked():
            now = time.time()
            for k in [k for k in self.alarms.active if k[0] == "FORT"]:
                self.alarms.clear(k, now)
            self._strong_src = {}

    def check_strong(self, bid, f, l):
        """Alarme ⚠ TROP FORT : un signal au-dessus du seuil « trop fort » dans la bande qui vient d'être balayée.
        Une alarme par MHz ; elle se termine quand ce MHz repasse 3 dB sous le seuil."""
        src = self._strong_src
        if bid in CALIB_IDS or not self.strong_chk.isChecked() or l is None or not len(l):
            return
        thr, now = self.strong_spin.value(), time.time()
        peaks = strong_peaks(f, l, thr)
        keep = {("FORT", int(round(pf))) for pf, _ in peaks}
        # fin d'alarme : seulement pour les MHz couverts par CE balayage (hystérésis 3 dB)
        for key in [k for k, b in src.items() if b == bid and k not in keep]:
            mhz = key[1]
            seg = l[(f >= mhz - 0.5) & (f <= mhz + 0.5)]
            if not len(seg) or seg.max() < thr - 3.0:
                self.alarms.clear(key, now)
                src.pop(key, None)
        new = None
        for pf, pl in peaks:
            key = ("FORT", int(round(pf)))
            src[key] = bid
            w = min(self.watch, key=lambda w_: abs(w_["freq"] - pf), default=None)
            near = w is not None and abs(w["freq"] - pf) <= max(0.3, (w.get("bw") or 0) / 2)
            name = f"{w['name']} (trop près ?)" if near else f"Signal {pf:.3f} MHz"
            seen = self.seen_by(pf)
            if self.alarms.raise_(key, "TROP FORT", name, pf, 2, now, pl, self.layer_text(w) if near else "",
                                  ("risque de décrochage" + (f" · {seen}" if seen else ""))):
                new = (name, pf, pl)
                self.log_event(dict(name=name, freq=pf, scene="", group="", note=f"> {thr:.0f} dBm"), pl, "TROP FORT")
        if new is not None:
            self._alarm_sound(2)
            self.set_status(f"⚠ TROP FORT : {new[0]} à {new[2]:.0f} dBm ({new[1]:.3f} MHz) — risque de saturation / "
                            f"décrochage des récepteurs.")
            self.refresh_alarms()

    def set_unit(self, unit):
        """Unité d'affichage des niveaux (dBm, dBµV, %). Les valeurs internes, fichiers et shows restent en dBm."""
        unit = unit if unit in UNIT_SUFFIX else "dbm"
        self.unit = LevelSpin.unit = LevelAxis.unit = unit
        if self.unit_combo.currentData() != unit:
            self.unit_combo.blockSignals(True)
            self.unit_combo.setCurrentIndex(max(0, self.unit_combo.findData(unit)))
            self.unit_combo.blockSignals(False)
        for sp_ in (self.thr_spin, self.weak_spin, self.strong_spin):
            sp_.setSingleStep(1.0)
            sp_.refresh()
        u = UNIT_SUFFIX[unit]
        ax = self.spec.getPlotItem().getAxis("left")
        self.spec.getPlotItem().setLabel("left", f"Niveau ({u})")
        ax.picture = None
        ax.update()
        for c, base_ in ((C_LVL, "Niveau"), (C_MAX, "Max"), (C_THR, "Seuil")):
            it = self.watch_table.horizontalHeaderItem(c)
            if it is not None:
                it.setText(base_ if unit == "dbm" else f"{base_} ({u})")
        for w in self.watch:
            w["sig"] = None
        self.update_watch_table(force=True)
        self.refresh_alarms()
        if self.wall is not None and self.wall.isVisible():
            self.wall.rebuild()

    def lvl(self, dbm, suffix=False):
        return fmt_level(dbm, self.unit, 1, suffix)

    def wall_is_fullscreen(self):
        return getattr(self, "_wall_full", None) is not None

    def wall_fullscreen(self, on, screen=None):
        """Plein écran du mur : il quitte son panneau pour une vraie fenêtre, et y revient en sortant."""
        if on and not self.wall_is_fullscreen():
            if screen is None:
                screen = self.wall.screen()                 # l'écran où est le mur (2ᵉ écran s'il y est)
            win_ = WallFullWindow(self)
            hold = QtWidgets.QLabel("🧱 Mur en plein écran — Échap ou F11 pour le ramener ici.")
            hold.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.dock_wall.setWidget(hold)
            win_.layout().addWidget(self.wall)
            self.wall.show()                # le panneau le cache en le lâchant : sinon plein écran tout noir (7.6.0)
            self._wall_full = win_
            if screen is not None:
                win_.setScreen(screen)
                win_.move(screen.geometry().topLeft())
            win_.showFullScreen()
            win_.activateWindow()
            QtCore.QTimer.singleShot(150, self.wall.rebuild)
            self.wall.full_btn.setText("⛶ Quitter (Échap)")
        elif not on and self.wall_is_fullscreen():
            win_, self._wall_full = self._wall_full, None
            self.dock_wall.setWidget(self.wall)
            self.wall.show()
            win_.hide()
            win_.deleteLater()
            self.wall.full_btn.setText("⛶ Plein écran")
            self.dock_wall.show()
            self.dock_wall.raise_()
        self.wall.relayout()

    def wall_detach(self, on):
        """Mur dans sa propre fenêtre (taille libre à la souris) ou en onglet à côté du spectre."""
        d = self.dock_wall
        if self.wall_is_fullscreen():
            self.wall_fullscreen(False)
        d.show()
        if on and not d.isFloating():
            d.setFloating(True)
            if d.width() > 900 or d.height() > 650 or d.width() < 250:     # 1re fois : une taille de vignette
                d.resize(560, 380)
                g = self.frameGeometry()
                d.move(g.right() - 600, g.top() + 80)
        elif not on and d.isFloating():
            d.setFloating(False)
        d.raise_()
        d.activateWindow()
        self._wall_float_txt()

    def _wall_float_txt(self, *_):
        if self.wall is not None:
            self.wall.float_btn.setText("📌 Raccrocher" if self.dock_wall.isFloating() else "🗗 Détacher")

    def in_alarm(self, w):
        return bool(w.get("absent")) or (w.get("state") == "occ" and self.is_keep_free(w["status"]))

    def set_wall_rows(self, rows, show):
        for r in rows:
            if 0 <= r < len(self.watch):
                if show:
                    self.watch[r].pop("hide_wall", None)
                else:
                    self.watch[r]["hide_wall"] = True
        if self.wall is not None and self.wall.isVisible():
            self.wall.relayout()
            self.wall.refresh()

    def pick_wall(self):
        if not self.watch:
            self.set_status("La liste de fréquences est vide.")
            return
        dlg = WallPickDialog(self)
        if dlg.exec():
            shown = dlg.shown()
            self.set_wall_rows([i for i, on in shown.items() if on], True)
            self.set_wall_rows([i for i, on in shown.items() if not on], False)

    def edit_labels(self):
        dlg = LabelsDialog(self, self.sig_labels, self.sig_colors,
                           lambda k: self.tone_color(SIGNAL_TONES.get(k, "none")))
        if dlg.exec():
            self.sig_labels = dlg.values()
            self.sig_colors = dlg.colors()
            for w in self.watch:
                w["sig"] = None
            self.update_watch_table(force=True)
            self._update_markers()
            if self.wall is not None and self.wall.isVisible():
                self.wall.rebuild()

    def w_paused(self, w):
        """🎬 Groupe pas sur scène en ce moment (planning), 📸 fréquence hors de l'état actif, ou 💤 éteinte exprès :
        pas d'alarme ABSENT."""
        if w.get("off") or w.get("muted"):
            return True
        act, planned = self._plan_state
        return planning_paused(w.get("scene", ""), w.get("group", ""), act, planned)

    def sig_view(self, w):
        """(texte, ton, couleur) du signal de w selon son statut (voir signal_view)."""
        if w.get("off"):
            return "💤 en pause (état)", "none", self.theme["st_none"]
        if w.get("muted") and w["state"] in (None, "free"):
            return "💤 éteint (je sais)", "none", self.theme["st_none"]
        if w["state"] in (None, "free") and self.is_keep_on(w["status"]) and self.w_paused(w):
            return "💤 pas sur scène", "none", self.theme["st_none"]
        key, tone = signal_key(w["state"], self.is_keep_free(w["status"]), self.is_keep_on(w["status"]),
                               bool(w.get("absent")), bool(w.get("im")))
        txt, _t = signal_view(w["state"], self.is_keep_free(w["status"]), self.is_keep_on(w["status"]),
                              bool(w.get("absent")), bool(w.get("im")), self.sig_labels)
        return txt, tone, self.sig_colors.get(key) or self.tone_color(tone)

    def tone_color(self, tone):
        th = self.theme
        return {"ok": th["st_free"], "free": th.get("st_libre", LIBRE_COLOR), "bad": th["st_occ"],
                "warn": th["st_weak"]}.get(tone, th["st_none"])

    def state_color(self, st):
        return {"free": self.theme["st_free"], "weak": self.theme["st_weak"],
                "occ": self.theme["st_occ"]}.get(st, self.theme["st_none"])

    def status_color(self, name):
        for s in self.statuses:
            if s["name"] == name:
                return s["color"]
        return self.theme["st_none"]

    def rebuild_watch_table(self):
        self._updating = True
        t = self.watch_table
        t.setRowCount(len(self.watch))
        for r, w in enumerate(self.watch):
            w["sig"] = None
            w["band"], w["cat"] = spectrum_info(w["freq"], self.plan, self.tv)
            t.setItem(r, C_NAME, self._item(w["name"], True))
            t.setItem(r, C_FREQ, self._item(f'{w["freq"]:.3f}', True, True))
            for c in (C_LVL, C_MAX):
                t.setItem(r, c, self._item("—", False, True))
            t.setItem(r, C_THR, self._item("—", True, True))
            t.setItem(r, C_SIG, self._item("—"))
            t.setItem(r, C_STAT, self._item("—"))
            t.setItem(r, C_OCC, self._item("—", False, True))
            t.setItem(r, C_LAYER, self._item("—"))
            t.setItem(r, C_BAND, self._item("—"))
            t.setItem(r, C_MARG, self._item("—", False, True))
        self._updating = False
        self.rebuild_tree()
        self._refresh_focus()
        self.update_watch_table(force=True)

    def update_watch_table(self, force=False):
        t, th = self.watch_table, self.theme
        base = th["ui_base"]
        self._updating = True
        n = dict(occ=0, weak=0, free=0)
        n_conf = n_ws = n_abs = 0
        overlaps = block_overlaps([(w["name"], w["freq"], w.get("bw") or 0.0) for w in self.watch])
        for r, w in enumerate(self.watch):
            if r >= t.rowCount():
                break
            st = w["state"]
            conf = st == "occ" and self.is_keep_free(w["status"])
            absn = bool(w.get("absent"))
            if self.in_scope(w):
                n_ws += 1
                if st in n:
                    n[st] += 1
                n_conf += conf
                n_abs += absn
            lv, mx = self.lvl(w["level"]), self.lvl(w["max"])
            stat = w["status"] or "—"
            thr_txt = self.lvl(w["thr"])
            if w["thr"] is None and w.get("athr") is not None:
                thr_txt = "auto " + self.lvl(w["athr"])
            pct = w["occw"].pct()
            occ_txt = "—" if pct is None else f"{pct:.0f} %"
            band = w["band"] or "—"
            if w.get("bw"):
                band = f"▬ bloc {w['bw']:g} MHz · {band}"
            if r in overlaps:
                band = f"⚠ dans le bloc « {overlaps[r]} » · {band}"
            layer = self.layer_text(w)
            gc = self.group_color(w["scene"], w["group"]) if layer else None
            keep_free = self.is_keep_free(w["status"])
            m_txt, m_tone, m_tip = snr_view(w.get("margin") if w.get("level") is not None else None, keep_free)
            # 7.54.1 (Clément : « je vois plus le éteint ») : 💤 dans la case Statut et ligne grisée, même si le micro
            # émet encore (la case Signal, elle, montre ce qui est mesuré)
            if w.get("muted"):
                stat = "💤 éteint · " + stat if w["status"] else "💤 éteint"
            elif w.get("off"):
                stat = "💤 hors état · " + stat if w["status"] else "💤 hors état"
            sig = (lv, mx, st, conf, stat, w["name"], round(w["freq"], 3), thr_txt, occ_txt, band, layer, gc, absn,
                   m_txt)
            if not force and w["sig"] == sig:
                continue
            w["sig"] = sig
            sig_txt, tone, tone_col = self.sig_view(w)
            # 7.54 (look « pro ») : la ligne n'est que légèrement teintée, la couleur forte reste sur la case Signal
            row_bg = {"bad": blend(th["st_occ"], base, 0.20), "warn": blend(th["st_weak"], base, 0.10)}.get(tone, base)
            row_fg = th["ui_text"]
            dim = bool(w.get("muted") or w.get("off"))
            if dim:
                row_fg = blend(th["ui_text"], base, 0.55)
            cells = ((C_NAME, w["name"]), (C_FREQ, f'{w["freq"]:.3f}'), (C_LVL, lv), (C_MAX, mx),
                     (C_THR, thr_txt), (C_SIG, sig_txt), (C_STAT, stat), (C_OCC, occ_txt),
                     (C_LAYER, layer or "—"), (C_BAND, band), (C_MARG, m_txt))
            for c, txt in cells:
                it = t.item(r, c)
                if it is None:
                    continue
                if it.text() != txt:
                    it.setText(txt)
                bg, fg = row_bg, row_fg
                if c == C_SIG and tone != "none":
                    bg = blend(tone_col, base, 1.0 if tone == "bad" else 0.85)
                    fg = contrast_text(bg)
                elif c == C_STAT and w["status"]:
                    bg = blend(self.status_color(w["status"]), row_bg, 0.32 * (0.5 if dim else 1.0))
                    fg = row_fg
                elif c == C_LAYER and gc:
                    bg = blend(gc, row_bg, 0.30)
                    fg = th["ui_text"]
                elif c == C_MARG:
                    fl_ = w.get("floor")
                    it.setToolTip(m_tip + (f"\nBruit de fond utilisé : {self.lvl(fl_, True)} (± 2 MHz autour)"
                                           if fl_ is not None and w.get("level") is not None else ""))
                    if m_tone in ("warn", "bad") and not (keep_free and m_tone == "ok"):
                        bg = blend(th["st_weak"] if m_tone == "warn" else th["st_occ"], row_bg, 0.35)
                        fg = th["ui_text"]
                elif c == C_BAND and w["cat"]:
                    bg = blend(th.get("bp_" + w["cat"], th["st_none"]), row_bg, 0.25)
                    fg = th["ui_text"]
                    tip = describe_freq(w["freq"], self.plan, self.tv)
                    if it.toolTip() != tip:
                        it.setToolTip(tip)
                it.setBackground(QtGui.QColor(bg))
                it.setForeground(QtGui.QColor(fg))
        self._updating = False
        total = f"{n_ws} fréquences" + (f" (sur {len(self.watch)})" if self.scope else "")
        txt = (f'{total} · {n["occ"]} occupée(s) · '
               f'{n["weak"]} faible(s) · {n["free"]} libre(s)')
        if n_conf:
            txt += f" · {CONFLICT_TEXT} ×{n_conf}"
        if n_abs:
            txt += f" · {ABSENT_TEXT} ×{n_abs}"
        self.count_lbl.setText(txt)
        self.apply_filter()
        self.update_tree_counts()
        if self.wall is not None and self.wall.isVisible():
            self.wall.refresh()

    def apply_filter(self, *_):
        t = self.watch_table
        txt = self.filter_edit.text().strip().lower().replace(",", ".")
        occ = self.occ_only_chk.isChecked()
        for r, w in enumerate(self.watch):
            if r >= t.rowCount():
                break
            hide = (not self.in_scope(w)) or (occ and w["state"] != "occ") or bool(
                txt and not (txt in w["name"].lower() or txt in f'{w["freq"]:.3f}'
                             or txt in (w["status"] or "").lower() or txt in (w["band"] or "").lower()
                             or txt in self.layer_text(w).lower()))
            if t.isRowHidden(r) != hide:
                t.setRowHidden(r, hide)

    def on_watch_edit(self, item):
        if self._updating or item.row() >= len(self.watch):
            return
        w = self.watch[item.row()]
        if item.column() == C_NAME:
            w["name"] = item.text()
            w["sig"] = None
            self._update_markers()
        elif item.column() == C_FREQ:
            v = parse_freq_cell(item.text())
            if v is None:
                QtCore.QTimer.singleShot(0, self.rebuild_watch_table)
                return
            self.set_watch_freq(w, v)
        elif item.column() == C_THR:
            txt = item.text().strip().lower()
            if txt in ("", "—", "-", "global"):
                w["thr"] = None
            else:
                v = _num(txt)
                if v is not None and -140.0 <= v <= 20.0:
                    w["thr"] = v
            w["sig"] = None
            QtCore.QTimer.singleShot(0, lambda: self.update_watch_table(force=True))

    def on_watch_dbl(self, row, col):
        if col == C_STAT:
            self.status_popup([row])
        elif col == C_LAYER:
            self.layer_popup([row])
        elif col in (C_LVL, C_MAX, C_SIG):
            self.zoom_on(row)

    def _sel_rows(self):
        return sorted({i.row() for i in self.watch_table.selectedIndexes() if i.row() < len(self.watch)})

    def _status_menu(self, parent):
        m = QtWidgets.QMenu(parent)
        a0 = m.addAction("— aucun statut\tCtrl+0")
        a0.setData("")
        for i, s in enumerate(self.statuses):
            a = m.addAction(color_icon(s["color"]), s["name"] + (f"\tCtrl+{i + 1}" if i < 9 else ""))
            a.setData(s["name"])
        return m

    def quick_status(self, which):
        """Raccourci clavier : statut n° which (0 = le 1er), None = aucun, "on" = le 1er « doit émettre »."""
        rows = self._sel_rows()
        if not rows:
            self.set_status("Sélectionne d'abord des fréquences dans la liste (clic, Maj+clic, Ctrl+A…).")
            return
        if which == "on":
            st = next((x for x in self.statuses if x.get("on")), None)
        elif which is None:
            st = dict(name="")
        else:
            st = self.statuses[which] if which < len(self.statuses) else None
        if st is None:
            self.set_status("Aucun statut à ce numéro (☰ Plus › Statuts… pour les voir / les ranger).")
            return
        self.set_status_rows(rows, st["name"])
        self.set_status(f"{len(rows)} fréquence(s) → « {st['name'] or 'aucun statut'} ».")

    def status_popup(self, rows):
        m = self._status_menu(self)
        act = m.exec(QtGui.QCursor.pos())
        if act is not None and act.data() is not None:
            self.set_status_rows(rows, act.data())

    def set_status_rows(self, rows, name):
        for r in rows:
            if r < len(self.watch):
                self.watch[r]["status"] = name
        self.update_watch_table(force=True)
        self._update_markers()

    def watch_menu(self, pos):
        rows = self._sel_rows()
        if not rows:
            r = self.watch_table.rowAt(pos.y())
            rows = [r] if 0 <= r < len(self.watch) else []
        if not rows:
            return
        m = QtWidgets.QMenu(self)
        sub = self._status_menu(m)
        sub.setTitle(f"Statut ({len(rows)} sélectionnée(s))" if len(rows) > 1 else "Statut")
        m.addMenu(sub)
        lay_sub = self.assign_menu(m)
        lay_sub.setTitle("Scène › Groupe")
        m.addMenu(lay_sub)
        a_rep = m.addAction("🆘 Remplacer ce micro (3 propositions)…")
        a_zoom = m.addAction("🔍 Zoom live sur cette fréquence")
        a_lis = m.addAction("🎧 Écouter avec le SDR…")
        a_rt = m.addAction("⏱ Temps réel autour de cette fréquence…")
        if getattr(self, "sdr_engs", None):
            self._sdr_follow_menu(m, [self.watch[r] for r in rows])     # 8.0.2 : suivre avec le SDR
        a_ren = m.addAction("Renommer…")
        a_qn = m.addAction("✏ Nommer la sélection (HF 1, HF 2…)…")
        a_fd = m.addAction("⇣ Numéroter vers le bas depuis la 1ʳᵉ ligne")
        a_thr = m.addAction("Seuil propre à la fréquence…")
        a_thr0 = m.addAction("Revenir au seuil global")
        a_occ0 = m.addAction("Remettre l'occupation à zéro")
        a_blk = m.addAction("📶 Bloc large (Spectera / WMAS)…")
        wall_hid = all(self.watch[r].get("hide_wall") for r in rows)
        a_wall = m.addAction("🧱 Afficher sur le mur" if wall_hid else "🧱 Masquer sur le mur")
        hid = all(self.watch[r].get("hide_mk") for r in rows)
        a_mk = m.addAction("📍 Réafficher le repère sur le spectre" if hid else "📍 Masquer le repère sur le spectre")
        a_ev = m.addAction("📍 Niveau de cette fréquence dans chaque lieu…") if self.site_scans else None
        muted = all(self.watch[r].get("muted") for r in rows)
        m.addSeparator()
        a_mute = m.addAction("🔔 Rallumer (surveiller à nouveau)  Ctrl+Espace" if muted
                             else "💤 Éteint (je sais) : pas d'alarme ABSENT  Ctrl+Espace")
        m.addSeparator()
        a_del = m.addAction("Supprimer")
        act = m.exec(self.watch_table.viewport().mapToGlobal(pos))
        if act is None:
            return
        if act is a_mute:
            self.set_muted([self.watch[r] for r in rows], not muted)
        elif act is a_rep:
            self.open_replace(self.watch[rows[0]])
        elif act is a_zoom:
            self.zoom_on(rows[0])
        elif act is a_lis:
            self.open_listen(rows)
        elif act is a_rt:
            self.open_realtime(self.watch[rows[0]]["freq"])
        elif act is a_thr:
            w0 = self.watch[rows[0]]
            cur = w0["thr"] if w0["thr"] is not None else self.thr_spin.value()
            u = self.unit
            lo_, hi_ = (0.0, 100.0) if u == "pct" else (to_unit(-140.0, u), to_unit(20.0, u))
            v, ok = QtWidgets.QInputDialog.getDouble(
                self, "Seuil propre", f"Seuil « occupé » ({UNIT_SUFFIX[u]}) pour {len(rows)} fréquence(s) :",
                round(to_unit(cur, u), 1), lo_, hi_, 1)
            v = from_unit(v, u)
            if ok:
                for r in rows:
                    self.watch[r]["thr"] = v
                self.update_watch_table(force=True)
        elif act is a_thr0:
            for r in rows:
                self.watch[r]["thr"] = None
            self.update_watch_table(force=True)
        elif act is a_occ0:
            for r in rows:
                self.watch[r]["occw"].clear()
            self.update_watch_table(force=True)
        elif act is a_qn:
            self.quick_name_dialog(rows)
        elif act is a_fd:
            self.fill_down_names(rows)
        elif act is a_ren:
            w = self.watch[rows[0]]
            txt, ok = self.ask_name("name", "Renommer", f"Nom de {w['freq']:.3f} MHz :", w["name"])
            if ok and txt.strip():
                w["name"] = txt.strip()
                self.update_watch_table(force=True)
                self._update_markers()
        elif act is a_del:
            self.del_watch()
        elif act is a_mk:
            self.hide_marker_rows(rows, not hid)
        elif a_ev is not None and act is a_ev:
            w0 = self.watch[rows[0]]
            self.open_sites(freq=(w0["freq"], float(w0.get("bw") or 0.0)))
        elif act is a_blk:
            self.set_block_rows(rows)
        elif act is a_wall:
            self.set_wall_rows(rows, wall_hid)
        elif self._assign_action(rows, act.data()):
            pass
        elif act.data() is not None:
            self.set_status_rows(rows, act.data())

    def set_muted(self, ws, on, quiet=False):
        """💤 Éteint (je sais) : le micro est éteint exprès, pas d'alarme ABSENT, jusqu'à ce qu'on le rallume.
        La fréquence reste dans le plan (elle se rallumera) et un signal sur une « doit rester libre » sonne toujours."""
        now = time.time()
        n = 0
        for w in ws:
            if bool(w.get("muted")) == bool(on):
                continue
            n += 1
            if on:
                w["muted"] = True
                w["free_since"] = None
                if w.get("absent"):
                    w["absent"] = False
                self.alarms.clear(("ABSENT", int(round(w["freq"] * 1000))), now)
            else:
                w.pop("muted", None)
                w["free_since"] = None
            self.log_event(w, w.get("level") if w.get("level") is not None else 0.0,
                           "ÉTEINT (je sais)" if on else "RALLUMÉ")
        if n:
            w0 = ws[0]
            self.update_watch_table(force=True)
            self._update_markers()
            self.refresh_alarms()
            if self.wall is not None and self.wall.isVisible():
                self.wall.rebuild()
            if not quiet:
                one = w0["name"] or f"{w0['freq']:.3f} MHz"
                self.set_status((f"💤 {one} éteint (je sais) : pas d'alarme ABSENT." if on else f"🔔 {one} rallumé.")
                                if n == 1 else (f"💤 {n} fréquence(s) éteintes (je sais)." if on
                                                else f"🔔 {n} fréquence(s) rallumées."))
        return n

    def toggle_muted_sel(self):
        rows = self._sel_rows()
        ws = [self.watch[r] for r in rows if 0 <= r < len(self.watch)]
        if ws:
            self.set_muted(ws, not all(w.get("muted") for w in ws))

    def layer_ws(self, key):
        """Fréquences d'une scène (key = (scène, "")) ou d'un groupe (key = (scène, groupe))."""
        return [w for w in self.watch if w["scene"] == key[0] and (not key[1] or w["group"] == key[1])]

    BLOCK_WIDTHS = (("Fréquence simple (pas de bloc)", 0.0), ("Bloc 6 MHz", 6.0), ("Bloc 8 MHz", 8.0),
                    ("Autre largeur…", None))

    def set_block_rows(self, rows):
        """Fréquence simple ↔ bloc large (Spectera / WMAS) pour les lignes choisies."""
        rows = [r for r in rows if 0 <= r < len(self.watch)]
        if not rows:
            return
        labels = [t for t, _ in self.BLOCK_WIDTHS]
        cur = self.watch[rows[0]].get("bw") or 0.0
        idx = next((i for i, (_t, v) in enumerate(self.BLOCK_WIDTHS) if v == cur), len(labels) - 1)
        txt, ok = QtWidgets.QInputDialog.getItem(
            self, "Bloc large", "Spectera / WMAS : un porteur large (canal TV) au lieu d'une fréquence.\n"
                                "« Doit émettre » : niveau médian du bloc · « Doit rester libre » : pic dans le bloc.\n\n"
                                "Largeur :", labels, idx, False)
        if not ok:
            return
        bw = dict(self.BLOCK_WIDTHS)[txt]
        if bw is None:
            bw, ok = QtWidgets.QInputDialog.getDouble(self, "Bloc large", "Largeur du bloc (MHz) :",
                                                      max(cur, 1.0), 0.2, 40.0, 1)
            if not ok:
                return
        for r in rows:
            self.watch[r]["bw"] = float(bw)
            self.watch[r]["sig"] = None
        self._refresh_focus()
        self.update_watch_levels()
        self.update_watch_table(force=True)
        self._update_markers()

    def add_block_dialog(self):
        """Ajoute un bloc Spectera / WMAS : canal TV du pays, ou fréquence centrale + largeur."""
        ch = block_choices(self.tv)
        other = "Autre : fréquence centrale et largeur…"
        txt, ok = QtWidgets.QInputDialog.getItem(self, "Bloc Spectera / WMAS", "Canal (selon le pays choisi) :",
                                                 [c[0] for c in ch] + [other], 0, False)
        if not ok:
            return
        if txt == other:
            f, ok = QtWidgets.QInputDialog.getDouble(self, "Bloc Spectera / WMAS", "Fréquence centrale (MHz) :",
                                                     610.0, 0.1, 6000.0, 3)
            if not ok:
                return
            bw, ok = QtWidgets.QInputDialog.getDouble(self, "Bloc Spectera / WMAS", "Largeur (MHz) :",
                                                      8.0 if self.country not in ("US", "CA") else 6.0, 0.2, 40.0, 1)
            if not ok:
                return
            name = f"Spectera {f:.1f}"
        else:
            _lab, f, bw = next(c for c in ch if c[0] == txt)
            name = "Spectera " + txt.split(" — ")[0].replace("CH ", "ch ")
        sc, gr = self._scope_preset()
        on = next((x["name"] for x in self.statuses if x.get("on")), "")
        self._append_watch(name, f, status=on, scene=sc, group=gr, bw=bw)
        self.sort_watch()
        self.rebuild_watch_table()
        self._refresh_focus()
        self._update_markers()
        self.set_status(f"Bloc « {name} » ajouté : {f - bw / 2:g}–{f + bw / 2:g} MHz (statut « {on or 'aucun'} »).")

    def add_watch_dialog(self, text=""):
        """⌨ 7.62 : « Ajouter » ouvre la saisie express (une ou plusieurs fréquences, nommées ou non)."""
        if self._quickadd is not None and self._quickadd.isVisible():
            if text:
                self._quickadd.edit.setPlainText(text)
            self._quickadd.raise_()
            self._quickadd.activateWindow()
            return self._quickadd
        self._quickadd = QuickAddDialog(self, text, self._scope_preset())
        self._quickadd.show()
        return self._quickadd

    def in_scanned_band(self, f):
        """La fréquence est-elle dans une bande cochée (balayée) ?"""
        return any(b.get("enabled", True) and b["start"] - 1e-6 <= f <= b["stop"] + 1e-6 for b in self.bands)

    def del_watch(self):
        rows = self._sel_rows()
        for r in reversed(rows):
            self.watch.pop(r)
        self.rebuild_watch_table()
        self._update_markers()
        if rows:
            self.undo_track()
            self.set_status(f"{len(rows)} fréquence(s) supprimée(s) · Ctrl+Z pour annuler.")

    # ------------------------------------------------------- ↶ annuler / ↷ rétablir (7.32, demande de Clément)
    UNDO_KEYS = ("watch", "scenes", "bands", "statuses")

    def _undo_state(self):
        """Ce qu'on peut annuler : liste, scènes / groupes, bandes, statuts (en JSON) + scans par lieu."""
        c = self._collect_config(True)
        txt = json.dumps({k: c.get(k) for k in self.UNDO_KEYS}, ensure_ascii=False, sort_keys=True, default=str)
        sites = list(self.site_scans)
        sig = txt + "|" + json.dumps([(d["name"], d.get("scene", "")) for d in sites], ensure_ascii=False)
        return (txt, sites), sig

    def undo_track(self):
        """Appelé chaque seconde (et après une suppression) : met de côté l'état d'avant s'il a changé."""
        if getattr(self, "_undo_busy", False):
            return
        try:
            st, sig = self._undo_state()
        except Exception:  # noqa: BLE001 — jamais bloquant
            return
        self.undo_stack.track(st, sig)

    def _undo_restore(self, st, what):
        txt, sites = st
        self._undo_busy = True
        self.history_track()
        pre = self._hist_rows
        try:
            data = self._collect_config(True)
            data.update(json.loads(txt))
            data["site_scans"] = list(sites)
            self._apply_config(data)
            self._hist_rows = pre                  # 🕘 l'annulation est notée (« ↶ Annulé »)
            self.history_track(TR(what.split(" ·")[0]))
            self.site_scans = list(sites)
            self.update_site_curve()
            self.undo_stack.resync(self._undo_state()[1])
        finally:
            self._undo_busy = False
        self._bump()
        n_u, n_r = len(self.undo_stack.undo), len(self.undo_stack.redo)
        self.set_status(f"{what} · encore {n_u} retour(s) possible(s), {n_r} à rétablir (Ctrl+Y).")

    def undo(self):
        self.undo_track()                          # le dernier changement, même de moins d'une seconde
        st = self.undo_stack.back()
        if st is None:
            self.set_status("Rien à annuler.")
            return False
        self._undo_restore(st, "↶ Annulé")
        return True

    def redo(self):
        st = self.undo_stack.fwd()
        if st is None:
            self.set_status("Rien à rétablir.")
            return False
        self._undo_restore(st, "↷ Rétabli")
        return True

    def delete_selected_layer(self):
        k = self._sel_layer_key()
        if k is not None and self.scene_by_name(k[0]) is not None:
            self.delete_layer(k)

    def edit_statuses(self):
        dlg = StatusDialog(self, self.statuses)
        if not dlg.exec():
            return
        rows = dlg.result_rows()
        for w in self.watch:
            new = ""
            for s in rows:
                if s["orig"] is not None and s["orig"] == w["status"]:
                    new = s["name"]
                    break
            w["status"] = new
        self.statuses = [dict(name=s["name"], color=s["color"], free=bool(s.get("free")), on=bool(s.get("on")))
                         for s in rows]
        self.update_watch_table(force=True)
        self._update_markers()

    def edit_colors(self):
        dlg = ColorsDialog(self, self.theme, self.preview_theme)
        if dlg.exec():
            self.theme = dict(dlg.theme)
            if dlg.recolor_chk.isChecked():
                self.recolor_layers()
        self.apply_theme()

    def recolor_layers(self):
        """Scènes, groupes et statuts aux couleurs de la palette du thème (7.54.1)."""
        self.scenes, self.statuses = layers_recolor(self.scenes, self.statuses, self.theme)
        self.rebuild_tree()
        for w in self.watch:
            w["sig"] = None
        self.update_watch_table(force=True)
        self._update_markers()
        if self.wall is not None and self.wall.isVisible():
            self.wall.rebuild()
        self.set_status("🎨 Scènes, groupes et statuts aux couleurs du thème (Ctrl+Z pour annuler).")

    def preview_theme(self, t):
        self.theme = dict(t)
        self.apply_theme()

    # ---------------------------------------------------- import / export
    def _resolve_status(self, st):
        if not st:
            return ""
        for s in self.statuses:
            if s["name"].lower() == st.lower():
                return s["name"]
        pal = theme_pal(self.theme)
        self.statuses.append(dict(name=st, color=pal[(len(self.statuses) + 3) % len(pal)],
                                  free=False, on=False))
        return st

    def import_watch(self):
        paths, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, "Importer des fréquences", "", "Listes et plans (*.csv *.txt *.tsv *.ezrf3 *.shw *.cug *.wsm *.wshow "
            "*.acp);;Plan EazyRF (*.ezrf3);;Show Shure WWB (*.shw);;Groupe Shure (*.cug);;Projet Sennheiser WSM (*.wsm);;"
            "Show Wisycom Manager (*.wshow);;Projet DPA (*.acp);;Tous les fichiers (*)")
        for p in paths:
            if Path(p).suffix.lower() in PLAN_EXTS:
                self.import_ezrf_file(p)
                continue
            self.open_import(decode_text(Path(p).read_bytes()), os.path.basename(p), preset=self._scope_preset())

    def paste_watch(self):
        txt, ok = QtWidgets.QInputDialog.getMultiLineText(
            self, "Coller une liste", "Colle un tableau (Excel, WWB, WSM, Wisycom…) ou une fréquence par ligne :")
        if ok and txt.strip():
            self.open_import(txt, "Texte collé", preset=self._scope_preset())

    def import_ezrf_file(self, path, opts=None):
        """Plan d'un logiciel de coordination (.ezrf3, Shure WWB .shw / .cug, Sennheiser WSM .wsm) -> aperçu
        puis import ; le fichier peut ensuite être suivi (🔗)."""
        try:
            doc, kind = parse_plan_file(Path(path).read_bytes(), os.path.basename(path))
        except (OSError, ValueError) as e:
            QtWidgets.QMessageBox.warning(self, APP_NAME, f"Impossible de lire « {os.path.basename(path)} » : {e}")
            return None
        return self.open_ezrf(doc, os.path.basename(path), opts=opts, path=path, kind=kind)

    def open_ezrf(self, doc, source, opts=None, path=None, kind="EazyRF"):
        """Plan -> fenêtre d'aperçu puis import (opts donné = sans fenêtre, pour les tests)."""
        if opts is None:
            dlg = EzrfImportDialog(self, doc, source, path, kind)
            if not dlg.exec():
                return None
            opts = dlg.options()
        opts = dict(opts, kind=opts.get("kind") or kind)
        if opts.get("manual"):                       # récepteurs Wisycom complétés dans « À compléter »
            doc = plan_fill_pending(doc, opts["manual"])
        return self.apply_ezrf(doc, opts, source, path)

    def _ezrf_profiles(self, doc):
        """Appareils du plan -> {clé appareil: clé de profil}. Réglages connus (.ezrf3) : profil perso créé ou
        réutilisé (même nom ET mêmes réglages) ; copier-coller : profil perso ou bibliothèque du même nom."""
        names = ezrf_profile_names(doc["devices"])

        def same(d, p):
            return (abs(d["sep"] - p["sep"]) < 1e-6 and abs(d["filt"] - p["filt"]) < 1e-6
                    and abs(d["step"] - p["step"]) < 1e-6
                    and all(abs(d["tol"].get(k, 0) - p["tol"].get(k, 0)) < 1e-6 for k in ("2tx3", "3tx3", "5"))
                    and abs(float(d.get("img") or 0) - float(p.get("img") or 0)) < 1e-6)
        new, want = [], {}
        have = {n: (k, d) for k, n, d, _w in RX_CUSTOM}
        low = lambda x: str(x).strip().lower()
        for dk, p in doc["devices"].items():
            name = names[dk]
            if "sep" in p:
                k = 2
                while name in have and not same(have[name][1], p):
                    name, k = f"{names[dk][:55]} ({k})", k + 1
                if name not in have and name not in [x["name"] for x in new]:
                    d = rx_from_library(dict(p, type=""))
                    d["name"] = name
                    d["note"] = (f"Plan EazyRF « {doc['title'] or 'sans titre'} » · {p['lo']:g}–{p['hi']:g} MHz"
                                 + (f" · FI {p['img']:g} MHz (fréquence image vérifiée)" if p.get("img") else ""))
                    new.append(d)
                want[dk] = name
            else:
                hit = next((n for n in have if low(n) == low(name)), None)
                if hit is None:
                    lib = next((d for d in RX_LIBRARY if low(d["name"]) == low(name)), None)
                    if lib is not None and lib["name"] not in [x["name"] for x in new]:
                        new.append(rx_from_library(lib))
                    hit = lib["name"] if lib is not None else None
                if hit:
                    want[dk] = hit
        if new:
            rx_set_custom(rx_custom_dump() + new)
            self.rx_profiles_changed()
        by_name = {n: k for k, n, _d, _w in RX_CUSTOM}
        return {dk: by_name[n] for dk, n in want.items() if n in by_name}

    def apply_ezrf(self, doc, opts, source="EazyRF", path=None):
        """Importe le plan : fréquences (scène = groupe du document, groupe = section), appareils posés sur les groupes,
        interférences en émetteurs extérieurs, scan de fond dans Scans par lieu. -> nombre de fréquences ajoutées."""
        entries = ezrf_remap(ezrf_entries(doc, opts.get("skip_off", True), opts.get("naming", "dev")), opts.get("map"))   # 🗂 7.66 : rangement
        keymap = self._ezrf_profiles(doc) if opts.get("profiles", True) else {}
        if opts.get("replace"):
            self.watch.clear()
        by_key = {int(round(w["freq"] * 1000)): w for w in self.watch}
        st = self._resolve_status(opts["status"]) if opts.get("status") else ""
        added, groups = 0, {}
        for name, f, sc, gr, dk, _note in entries:
            rx = keymap.get(dk, "")
            if rx and gr:
                lst = groups.setdefault((sc or DEFAULT_SCENE, gr), [])
                if rx not in lst:
                    lst.append(rx)
            k = int(round(f * 1000))
            src = os.path.basename(str(path)) if path else ""
            if k in by_key:
                if not by_key[k].get("ez"):           # 🔗 déjà là : reliée au plan quand même (pas volée à un autre plan)
                    by_key[k]["ez"] = ezrf_id(sc, gr, name)
                    if src:
                        by_key[k]["ezsrc"] = src
                continue
            self._append_watch(name, f, st, None, sc, gr)
            self.watch[-1]["ez"] = ezrf_id(sc, gr, name)
            if src:
                self.watch[-1]["ezsrc"] = src
            if rx:
                self.watch[-1]["rx"] = rx
            by_key[k] = self.watch[-1]
            added += 1
        for (sc, gr), rxs in groups.items():
            g = self.group_row(sc, gr)
            if g is not None:
                old = self.group_rxs(g)
                g["rx"] = old + [r for r in rxs if r not in old]
        for w in self.watch:                     # appareil = celui du groupe par défaut : inutile de le répéter
            if w.get("rx") and w["rx"] == self.rx_of(dict(w, rx="")):
                w.pop("rx", None)
        n_ext = 0
        if opts.get("interf"):
            for f in doc["interf"]:
                k = int(round(f * 1000))
                if k not in by_key:
                    self._append_watch(f"Ext. {f:.3f}", f, "", None, "", "")
                    by_key[k] = self.watch[-1]
                    n_ext += 1
        if doc.get("tv") or opts.get("replace"):   # 7.58.2 : canaux TV du plan -> 📺 grisés ; liste remplacée (tournée,
            self.tnt_set_plan(doc.get("tv") or [], os.path.basename(str(path)) if path else source)  # nouveau lieu) :
            # ceux de l'ancien plan repartent, même si le nouveau n'en a pas
        scan_name = ""
        if opts.get("scan") and doc["scan"] is not None:
            names = {d["name"] for d in self.site_scans}
            scan_name = snapshot_name("EazyRF", doc["scan_title"] or doc["title"], names, time.strftime("%H:%M"))
            self.site_scans.append(site_scan_doc(scan_name, doc["scan"][0], doc["scan"][1], time.time()))
        self.sort_watch()
        self.rebuild_tree()
        self.rebuild_watch_table()
        self._update_markers()
        if scan_name:
            self.update_site_curve()
        self.undo_track()
        if opts.get("follow") and path:            # 🔗 suivre le fichier
            try:
                self.ezrf_link = dict(path=str(path), mtime=os.path.getmtime(path), name=os.path.basename(str(path)),
                                      status=opts.get("status", ""), skip_off=bool(opts.get("skip_off", True)),
                                      kind=opts.get("kind") or "EazyRF", manual=dict(opts.get("manual") or {}),
                                      map=ezrf_map_norm(opts.get("map")), naming=opts.get("naming", "dev"))
            except OSError:
                self.ezrf_link = None
        msg = f"📥 Plan {opts.get('kind') or 'EazyRF'} : {added} fréquence(s) importée(s)"
        if len(entries) > added:
            msg += f" ({len(entries) - added} déjà présente(s))"
        if keymap:
            msg += f", {len(set(keymap.values()))} appareil(s) posé(s) sur leurs groupes"
        if n_ext:
            msg += f", {n_ext} émetteur(s) extérieur(s)"
        if scan_name:
            msg += f", scan « {scan_name} » gardé dans Scans par lieu"
        if opts.get("planning"):                   # 🎬 7.66 : créneaux lus dans les noms des passages
            slots = ezrf_planning(entries)
            have = {(x["scene"], x["group"], x["day"], x["start"], x["end"]) for x in self.planning["slots"]}
            new = [x for x in slots if (x["scene"], x["group"], x["day"], x["start"], x["end"]) not in have]
            if new:
                self.planning = planning_norm(dict(self.planning, slots=self.planning["slots"] + new))
                msg += TR(", {} créneau(x) ajouté(s) au planning").format(len(new))
        self.set_status(msg + ".")
        if added:
            self.offer_missing_bands()
        return added

    def open_import(self, text, source, preset=("", "")):
        if is_ezrf_paste(text):
            try:
                return self.open_ezrf(parse_ezrf_paste(text), source)
            except ValueError:
                pass
        dlg = ImportDialog(self, text, source, self.scenes, preset)
        if not dlg.an["data"]:
            QtWidgets.QMessageBox.information(self, APP_NAME, f"Aucune fréquence reconnue dans « {source} ».")
            return
        if not dlg.exec():
            return
        entries = dlg.entries()
        if dlg.replace():
            self.watch.clear()
        by_key = {int(round(w["freq"] * 1000)): w for w in self.watch}
        added = moved = 0
        for name, f, st, sc, gr in entries:
            k = int(round(f * 1000))
            if k in by_key:
                w = by_key[k]
                if (sc or gr) and not w["scene"] and not w["group"]:
                    if gr and not sc:
                        sc = DEFAULT_SCENE
                    self.ensure_group(sc, gr)
                    w["scene"], w["group"] = sc, gr
                    moved += 1
                continue
            self._append_watch(name, f, self._resolve_status(st), None, sc, gr)
            by_key[k] = self.watch[-1]
            added += 1
        self.sort_watch()
        self.rebuild_watch_table()
        self._update_markers()
        extra = f", {moved} rangée(s) dans leur groupe" if moved else ""
        self.set_status(f"{added} fréquence(s) importée(s) depuis {source} "
                        f"({len(entries) - added} déjà présente(s){extra}).")
        if added:
            self.offer_missing_bands()

    def dragEnterEvent(self, e):
        if e.mimeData().hasUrls():
            e.acceptProposedAction()

    def dropEvent(self, e):
        for u in e.mimeData().urls():
            p = u.toLocalFile()
            if p and Path(p).suffix.lower() in PLAN_EXTS:
                self.import_ezrf_file(p)
            elif p and Path(p).suffix.lower() in (".csv", ".txt", ".tsv"):
                self.open_import(decode_text(Path(p).read_bytes()), os.path.basename(p),
                                 preset=self._scope_preset())

    def export_watch(self):
        path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Exporter", "frequences.csv", "CSV (*.csv)")
        if path:
            with open(path, "w", newline="", encoding="utf-8-sig") as f:
                wr = csv.writer(f, delimiter=";")
                wr.writerow(["Nom", "MHz", "Statut", "Scène", "Groupe", "Niveau dBm", "Max dBm", "Signal",
                             "Seuil dBm", "Occupation %", "Spectre"])
                for w in self.watch:
                    pct = w["occw"].pct()
                    wr.writerow([w["name"], fmt_comma(w["freq"]), w["status"], w["scene"], w["group"],
                                 "" if w["level"] is None else fmt_comma(w["level"], 1),
                                 "" if w["max"] is None else fmt_comma(w["max"], 1), SIG_TEXT[w["state"]],
                                 "" if w["thr"] is None else fmt_comma(w["thr"], 1),
                                 "" if pct is None else fmt_comma(pct, 0), w["band"]])

    def bands_from_list(self):
        ws = self.scope_ws()
        if not ws:
            QtWidgets.QMessageBox.information(self, APP_NAME, "La liste de fréquences (ou la couche active) est vide.")
            return
        fs = sorted(x for w in ws for x in block_points(w["freq"], w.get("bw")))
        groups, cur = [], [fs[0]]
        for f in fs[1:]:
            if f - cur[-1] <= 20.0:
                cur.append(f)
            else:
                groups.append(cur)
                cur = [f]
        groups.append(cur)
        new = [(f"{g[0]:.0f}–{g[-1]:.0f} MHz", max(0.1, g[0] - 0.5), g[-1] + 0.5, 200.0) for g in groups]
        tot = sum(int((b[2] - b[1]) * 1000 / b[3]) + 1 for b in new)
        r = QtWidgets.QMessageBox.question(
            self, APP_NAME, f"Remplacer les bandes actuelles par {len(new)} bande(s) "
                            f"couvrant {'la couche active' if self.scope else 'ta liste'} "
                            f"({tot} points au total, pas de 200 kHz) ?")
        if r == QtWidgets.QMessageBox.StandardButton.Yes:
            with self.lock:
                self.bands.clear()
            for d in (self.latest, self.maxhold, self.partial_data):
                d.clear()
            for b in new:
                self._append_band(*b)
            self._bands_changed()

    # -------------------------------------------------------------- journal
    def log_event(self, w, level, event):
        if not self.log_kinds.get(log_kind(event), True):
            return                                # type d'événement décoché dans « 📝 Quoi noter »
        self._log_n += 1
        t = self.log_table
        t.insertRow(0)
        vals = [datetime.now().strftime("%H:%M:%S"), w["name"], f'{w["freq"]:.3f}' if w["freq"] else "—",
                f"{level:.1f}" if w["freq"] else "—", event,
                self.layer_text(w) if "scene" in w else "", w.get("note", "")]
        col = (self.theme["st_occ"] if event in ("OCCUPÉ", "CONFLIT", "INTERMOD", "ABSENT", "APPAREIL PERDU", "TROP FORT",
                                                 "APPEL INCOMPLET")
               else self.theme["st_unk"]
               if event == "INCONNU" else self.theme["st_free"])
        self._auto_log(vals, w)                      # fichier : toujours en dBm
        if self._session is not None:
            self._session_log(vals, w)
        if w["freq"]:
            vals = list(vals)
            vals[3] = self.lvl(level)
        for c, v in enumerate(vals):
            it = self._item(v, False, c in (2, 3))
            if c == 4:
                it.setForeground(QtGui.QColor(col))
            t.setItem(0, c, it)
        while t.rowCount() > 2000:
            t.removeRow(t.rowCount() - 1)

    def _sync_log_menu(self):
        for k, a_ in getattr(self, "_logwhat_acts", {}).items():
            a_.blockSignals(True)
            a_.setChecked(self.log_kinds.get(k, True))
            a_.blockSignals(False)

    def on_log_dbl(self, row, col):
        it = self.log_table.item(row, 4)
        if it is None or it.text() != TR("INCONNU"):
            return
        f = _num(self.log_table.item(row, 2).text())
        if f is None:
            return
        sc, gr = self._scope_preset()
        self._append_watch(f"Nouveau {f:.3f}", f, scene=sc, group=gr)
        self.sort_watch()
        self.rebuild_watch_table()
        self._update_markers()
        self.set_status(f"{f:.3f} MHz ajoutée à la liste (renomme-la : clic droit › Renommer).")

    def export_log(self):
        path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Exporter le journal", "journal.csv", "CSV (*.csv)")
        if not path:
            return
        t = self.log_table
        with open(path, "w", newline="", encoding="utf-8-sig") as f:
            wr = csv.writer(f, delimiter=";")
            wr.writerow([TR(x) for x in ("Heure", "Nom", "MHz", "dBm", "Événement", "Scène › Groupe", "Note")])
            for r in range(t.rowCount() - 1, -1, -1):
                wr.writerow([t.item(r, c).text() for c in range(7)])

    # --------------------------------------------------------- données live
    def _sweep_time(self, bid):
        """Heure de la mesure donnée par le worker (audit 7.44 : interface chargée = balayages datés en retard) ;
        heure actuelle si l'appareil ne la donne pas (ou si elle est incohérente)."""
        now = time.time()
        try:
            t = (getattr(self.sender(), "sweep_t", None) or {}).get(bid)
        except Exception:  # noqa: BLE001
            t = None
        if isinstance(t, (float, int)) and not isinstance(t, bool):
            return min(float(t), now)            # audit 7.53 : une mesure ANCIENNE garde son âge (avant : remise à
        return now                               # « maintenant » au-delà de 2 min = fraîcheur artificielle)

    def on_sweep(self, bid, f, l):
        if bid in CALIB_IDS:
            self._calib_add(CALIB_IDS.index(bid), f, l)
            return
        self.partial_data.pop(bid, None)
        if bid != ZOOM_ID:
            f, l = self._site_feed(bid, f, l)
            if self.diversity_on():
                f, l = self._div_feed(bid, f, l)
        old = self.latest.get(bid)
        if (old is not None and old[0].shape == f.shape and abs(old[0][0] - f[0]) < 1e-6
                and abs(old[0][-1] - f[-1]) < 1e-6):
            self.history.setdefault(bid, deque(maxlen=20)).append(old)
        else:
            self.history.pop(bid, None)
        self.latest[bid] = (f, l)
        self.latest_t[bid] = self._sweep_time(bid)
        if bid != ZOOM_ID and len(l):
            self.__dict__.setdefault("_sat_max", {})[bid] = (self.latest_t[bid], float(np.nanmax(l)))
        if bid != ZOOM_ID:
            if self._t_start is None:
                self._t_start = self.latest_t[bid]
            self.store.add(bid, self.latest_t[bid], f, l)
            if self.recorder is not None:
                self.recorder.add(bid, self.latest_t[bid], f, l)
        mh = self.maxhold.get(bid)
        if not self.maxhold:
            self._mh_t0 = time.time()            # le max hold repart : la durée d'un scan gardé se compte d'ici
        self.maxhold[bid] = np.maximum(mh, l) if (mh is not None and mh.shape == l.shape) else l.copy()
        self.update_watch_levels()
        self.check_strong(bid, f, l)
        self.update_watch_table()
        if self.unk_chk.isChecked() or self._linecheck is not None:     # l'appel repère les packs mal réglés
            self.detect_unknown(bid, f, l)
        if self._linecheck is not None and bid != ZOOM_ID:
            self._linecheck.feed()
        if self._hunt is not None and bid == ZOOM_ID:
            self._hunt.feed(f, l)
        if self.view_id in (-1, bid):
            self.update_plot()
        if self._wf_bid() == bid:
            self.update_waterfall(bid, f, l)

    def offer_missing_bands(self):
        """7.57 : après un import, des fréquences hors des bandes balayées -> on propose d'ajouter les bandes qui
        manquent (fenêtre non bloquante)."""
        miss = missing_bands([w["freq"] for w in self.watch], self.bands)
        if not miss:
            return []
        txt = "\n".join(f"• {a:g}–{z:g} MHz ({n} fréquence(s))" for a, z, n in miss)
        box = QtWidgets.QMessageBox(QtWidgets.QMessageBox.Icon.Question, APP_NAME,
                                    "Des fréquences de ta liste sont en dehors des bandes balayées : elles ne seraient "
                                    "pas surveillées.\nAjouter ces bandes ?\n\n" + txt, parent=self)
        yes = box.addButton("Ajouter les bandes", QtWidgets.QMessageBox.ButtonRole.AcceptRole)
        box.addButton("Plus tard", QtWidgets.QMessageBox.ButtonRole.RejectRole)

        def done(btn, miss=miss):
            if btn is yes:
                for a, z, _n in miss:
                    self._append_band(f"{a:g}–{z:g} MHz", a, z, 100.0, True)
                self._bands_changed()
                self.set_status(f"📶 {len(miss)} bande(s) ajoutée(s) : toute ta liste est maintenant surveillée.")
        box.buttonClicked.connect(done)
        box.setModal(False)
        self._band_offer = box
        box.show()
        return miss

    def _wf_bid(self):
        """Bande du waterfall (7.57) : la bande de la Vue, ou la seule bande balayée en « Toutes les bandes »."""
        return single_band_view(self.view_id, self.bands, ZOOM_ID)

    def auto_view(self):
        """7.57 : Vue « Toutes les bandes » -> directement sur la bande UHF du pays (ou la seule bande balayée)."""
        if self._zoom is not None or self.view_id != -1:
            return
        bid = default_view_band(self.bands, getattr(self, "country", "FR"))
        i_ = self.view_combo.findData(bid) if bid is not None else -1
        if i_ >= 0:
            self.view_combo.setCurrentIndex(i_)

    def on_partial(self, bid, f, l, i, n):
        if bid in CALIB_IDS:
            return
        self.partial_data[bid] = (f, l)
        name = next((b["name"] for b in self.scan_bands() if b["id"] == bid), "Zoom")
        self.set_status(f"Balayage « {name} » : segment {i}/{n}")
        if self.view_id in (-1, bid):
            now = time.monotonic()                 # fluidité (7.31.1) : 5 images / s au plus pendant un balayage
            if now - getattr(self, "_partial_t", 0.0) >= 0.2:
                self._partial_t = now
                self.update_plot(hist=False)

    def on_cycle(self, dt, nb, dev=0):
        self.dev_cycle[dev] = dt
        live = [v for k, v in self.dev_cycle.items() if k >= len(self.dev_live) or self.dev_live[k]]
        dt = max(live) if live else dt          # le plus lent des tinySA fixe le rythme de rafraîchissement
        nb = len([b for b in self.scan_bands() if self._scan_now(b)]) if self.ndev() > 1 and self._zoom is None else nb
        self.last_cycle = dt
        ids = {b["id"] for b in self.scan_bands() if b["enabled"]}
        if self._zoom is not None:
            ids.add(ZOOM_ID)
        for k in list(self.latest):
            if k not in ids:
                for d in (self.latest, self.maxhold, self.unk_now, self.history):
                    d.pop(k, None)
        ws = self.scope_ws()
        occ = sum(1 for w in ws if w["state"] == "occ")
        conf = sum(1 for w in ws if w["state"] == "occ" and self.is_keep_free(w["status"]))
        absn = sum(1 for w in ws if w.get("absent"))
        mode = "ZOOM · " if self._zoom is not None else ("🎯 " if self._focus_bands else "")
        self.cycle_lbl.setText(f"{mode}Cycle {dt:.2f} s · {nb} bande(s) · {len(ws)} fréq. · "
                               f"{occ} occupée(s)" + (f" · {CONFLICT_TEXT} ×{conf}" if conf else "")
                               + (f" · {ABSENT_TEXT} ×{absn}" if absn else "") + "   ")

    def update_watch_levels(self):
        try:
            self._auto_curve_update()
        except Exception:
            pass
        if not self.watch:
            return
        now = time.time()
        stale = max(15.0, 4 * self.last_cycle)
        fresh = [k for k in self.latest if now - self.latest_t.get(k, 0) <= stale]
        if not fresh:
            for w in self.watch:
                w["level"], w["state"], w["t_acc"] = None, None, None
                self._alarm_reset(w, now)
            return
        F = np.concatenate([self.latest[k][0] for k in fresh])
        L = np.concatenate([self.latest[k][1] for k in fresh])
        o = np.argsort(F)
        F0, L0 = F[o], L[o]
        # 📍 deux tinySA à deux lieux : une fréquence de la scène X est jugée par le tinySA posé à X
        per_site = {}
        if self.multi_site_on():
            for site in {x for v in self.dev_scenes.values() for x in v}:
                Fs, Ls = self.site_fresh(site)
                if Fs is not None:
                    per_site[site] = (Fs, Ls)
        win = self.win_spin.value() / 1000.0
        gthr, gweak, weak_on = self.thr_spin.value(), self.weak_spin.value(), self.weak_chk.isChecked()
        rel = self.ref_chk.isChecked() and self._ref_F is not None
        margin = self.ref_margin.value()
        cap = max(5.0, 2.0 * self.last_cycle)
        delay = max(float(self.absent_spin.value()), 2.0 * self.last_cycle)
        alert = conflict = absent = None
        new_prio = -1
        for w in self.watch:
            if not self.in_scope(w):
                w["t_acc"] = None
                self._alarm_reset(w, now)
                continue
            f = w["freq"]
            bw = w.get("bw") or 0.0
            F, L = per_site.get(w.get("scene"), (F0, L0))
            how = "max" if self.is_keep_free(w["status"]) else "median"
            lvl = level_block(F, L, f, bw, how) if bw else level_at(F, L, f, win)
            w["level"] = lvl
            fl_ = noise_floor(F, L, f, win=2.0 + bw / 2.0, exclude=max(0.15, win, bw / 2.0)) if lvl is not None else None
            w["margin"] = (lvl - fl_) if fl_ is not None else None
            w["floor"] = fl_
            if self.thr_auto and fl_ is not None:      # seuils auto : bruit appris, qui ne monte pas si c'est occupé
                w["afl"] = floor_track(w.get("afl"), fl_, now - (w.get("afl_t") or now), busy=w.get("state") == "occ")
                w["afl_t"] = now
            if lvl is None:
                w["state"], w["t_acc"] = None, None
                self._alarm_reset(w, now)
                continue
            w["max"] = lvl if w["max"] is None else max(w["max"], lvl)
            ref_l = ((level_block(self._ref_F, self._ref_L, f, bw, how) if bw else
                      level_at(self._ref_F, self._ref_L, f, win)) if rel else None)
            thr, weak = eff_thresholds(w["thr"], ref_l, rel, margin, gthr, gweak,
                                       w.get("afl") if self.thr_auto else None, self.auto_margins())
            w["athr"] = thr if self.thr_auto and w["thr"] is None else None
            w["ethr"] = thr                         # seuil réellement appliqué (explication des alarmes, 7.56)
            prev = w["state"]
            new = next_state(prev, lvl, thr, weak, weak_on)
            t0 = w["t_acc"]
            w["t_acc"] = now
            if t0 is not None:
                w["occw"].add(now, min(now - t0, cap), new == "occ")
            keep_free = self.is_keep_free(w["status"])
            if new == "occ" and prev != "occ":
                w["peak"], w["since"] = lvl, now
                seen = self.seen_by(f)
                if keep_free:
                    f_at = f
                    if bw:                              # bloc : l'intrus est au pic mesuré dans le bloc
                        lo_ = int(np.searchsorted(F, f - bw / 2.0))
                        hi_ = int(np.searchsorted(F, f + bw / 2.0, side="right"))
                        if hi_ > lo_:
                            f_at = float(F[lo_ + int(np.argmax(L[lo_:hi_]))])
                    w["im"] = self.im_cause(w, f_at)
                    note = " · ".join(x for x in (w["im"], seen) if x)
                    self.log_event(dict(w, note=note) if note else w, lvl, "INTERMOD" if w["im"] else "CONFLIT")
                    conflict = w
                else:
                    w["occ_log"] = False                # noté seulement s'il dure (OCC_LOG_S), voir plus bas
                    if OCC_LOG_S <= 0 and not self.w_paused(w):
                        w["occ_log"] = True
                        self.log_event(dict(w, note=seen) if seen else w, lvl, "OCCUPÉ")
                    alert = w
            elif new == "occ":
                w["peak"] = max(w["peak"] or lvl, lvl)
                if (not keep_free and w.get("occ_log") is False and now - (w.get("since") or now) >= OCC_LOG_S
                        and not self.w_paused(w)):
                    w["occ_log"] = True
                    nb, seen = w.pop("blips", 0), self.seen_by(f)
                    note = " · ".join(x for x in (seen, f"+ {nb} passage(s) de moins de {OCC_LOG_S:.0f} s avant"
                                                  if nb else "") if x)
                    self.log_event(dict(w, note=note) if note else w, w["peak"], "OCCUPÉ")
            elif prev == "occ" and not keep_free and w.get("occ_log") is False:
                w["occ_log"] = None                     # occupation trop courte (ou micro en pause) : pas de ligne
                w["blips"] = w.get("blips", 0) + (0 if self.w_paused(w) else 1)
                w["im"] = ""
            elif prev == "occ":
                w["occ_log"] = None
                w["im"] = ""
                # bilan de Clément (7.53) : « Libre » affichait le PIC de l'occupation (−69,7) et paraissait plus fort que
                # le « OCCUPÉ » (−91,7) : on note le niveau ACTUEL, le pic va dans la note
                pk = w.get("peak")
                self.log_event(dict(w, note=f"max pendant l'occupation : {self.lvl(pk)}") if pk is not None else w,
                               lvl, f"Libre ({now - w['since']:.0f} s)")
            if prev is not None and (prev == "occ") != (new == "occ"):     # 🩺 7.68 : « pile au seuil »
                fl_q = w.get("_flips")
                if fl_q is None:
                    fl_q = w["_flips"] = deque(maxlen=200)
                fl_q.append(now)
            lh = w.get("_lvh")
            if lh is None:
                lh = w["_lvh"] = deque(maxlen=400)
            if not lh or now - lh[-1][0] >= 2.0:
                lh.append((now, lvl))
            w["state"] = new
            # ---- alarmes : CONFLIT (signal sur une fréquence « doit rester libre ») et ABSENT (« doit émettre » muette)
            fk = int(round(f * 1000))
            confirm = float(self.sound.cfg.get("confirm", 0))
            if new == "occ" and keep_free and now - (w.get("since") or now) < confirm:
                pass                                # signal trop court pour l'instant : on attend la confirmation
            elif new == "occ" and keep_free and not w.get("off"):      # 📸 en pause : pas d'alarme
                prio = self.freq_prio(w)
                kind = "INTERMOD" if w.get("im") else "CONFLIT"
                if self.alarms.raise_(("CONFLIT", fk), kind, w["name"], f, prio, now, lvl, self.layer_text(w),
                                      " · ".join(x for x in (w.get("im", ""), self.seen_by(f)) if x)):
                    new_prio = max(new_prio, prio)
            else:
                self.alarms.clear(("CONFLIT", fk), now)
            if self.is_keep_on(w["status"]) and not self.w_paused(w):
                if new == "free":
                    fs = w.get("free_since")
                    if fs is None:
                        fs = w["free_since"] = now
                    if now - fs >= delay:
                        prio = self.freq_prio(w)
                        if self.alarms.raise_(("ABSENT", fk), "ABSENT", w["name"], f, prio, now, lvl,
                                              self.layer_text(w), f"silence depuis {now - fs:.0f} s"):
                            w["absent"] = True
                            self.log_event(dict(w, note=f"aucun signal depuis {now - fs:.0f} s"), lvl, "ABSENT")
                            absent = w
                            new_prio = max(new_prio, prio)
                else:
                    w["free_since"] = None
                    a_ = self.alarms.clear(("ABSENT", fk), now)
                    if w.get("absent") or a_ is not None:
                        w["absent"] = False
                        self.log_event(w, lvl, f"Retour ({now - a_['t0']:.0f} s)" if a_ else "Retour")
            else:
                w["free_since"] = None
                if w.get("absent"):
                    w["absent"] = False
                    self.alarms.clear(("ABSENT", fk), now)
        if conflict is not None:
            self.set_status(f"⚠ CONFLIT : {conflict['name']} ({conflict['freq']:.3f} MHz) est occupée "
                            f"alors qu'elle doit rester libre.")
        if absent is not None:
            self.set_status(f"⚠ ABSENT : {absent['name']} ({absent['freq']:.3f} MHz) n'émet plus alors qu'elle "
                            f"doit émettre.")
        if alert is not None and conflict is None and self.alert_chk.isChecked() and self.sound.cfg.get("occ_beep") \
                and not snooze_left(self.snooze_until, now):
            self.sound.alarm(0)
        if new_prio >= 0:
            self._alarm_sound(new_prio)
            self.refresh_alarms()

    def detect_unknown(self, bid, f, l):
        """Pics au-dessus du seuil qui ne correspondent à aucune fréquence de la liste."""
        self.unk_now[bid] = []
        if len(l) < 3:
            return
        thr = self.thr_spin.value()
        if self.thr_auto and self._acurve is not None:   # seuils auto : la courbe du bruit + la marge, point par point
            Fc, Lc, _ = self._acurve
            ok = np.isfinite(Lc)
            if ok.any():
                thr = (np.interp(f, Fc[ok], Lc[ok]) + self.auto_margins()[0])[1:-1]
        mid = l[1:-1]
        idx = np.where((mid >= thr) & (mid >= l[:-2]) & (mid > l[2:]))[0] + 1
        if not len(idx):
            return
        wf = np.array([w["freq"] for w in self.watch]) if self.watch else np.array([])
        step = float(np.median(np.diff(f))) if len(f) > 1 else 0.2
        guard = self.win_spin.value() / 1000.0 + step / 2 + 0.05
        now, logged = time.time(), 0
        for i in idx[:200]:
            fr = float(f[i])
            if len(wf) and float(np.min(np.abs(wf - fr))) <= guard:
                continue
            self.unk_now[bid].append(fr)
            key = round(fr / 0.1)
            last = self.unk_seen.get(key, 0.0)
            self.unk_seen[key] = now
            if now - last > 30 and logged < 10:
                note = self.im_note(fr, step)
                self.log_event({"name": "Signal inconnu", "freq": fr, "note": note}, float(l[i]), "INCONNU")
                logged += 1

    # ------------------------------------------------------------- graphes
    def _series(self, k):
        """Courbe à afficher : le balayage en cours posé sur l'ancien (comme un vrai analyseur)."""
        part, old = self.partial_data.get(k), self.latest.get(k)
        if part is None:
            return old
        if old is None or len(part[0]) == 0:
            return part
        keep = old[0] > part[0][-1]
        return np.concatenate([part[0], old[0][keep]]), np.concatenate([part[1], old[1][keep]])

    def _fit_range(self):
        if self.view_id == -1:
            bs = [b for b in self.scan_bands() if b["enabled"]]
        else:
            bs = [b for b in self.scan_bands() if b["id"] == self.view_id]
        if not bs:
            return None
        return min(b["start"] for b in bs), max(b["stop"] for b in bs)

    coord_on = False

    def set_coord(self, on):
        """Montre / cache les outils de coordination (parcours ③ ④, ☰ Plus, tutos, clic droit du journal)."""
        self.coord_on = bool(on)
        for k in COORD_STEPS:
            a_ = self.__dict__.get("_step_acts", {}).get(k)
            if a_ is not None:
                a_.setVisible(self.coord_on)
            a_ = self.__dict__.get("_step_arrows", {}).get(k)
            if a_ is not None:
                a_.setVisible(self.coord_on)
        for a_ in self.__dict__.get("_coord_acts", []):
            a_.setVisible(self.coord_on)
        h_ = self.__dict__.get("_coord_hint")
        if h_ is not None:                          # caché : une entrée dit où les réactiver (Clément : « où est la coord ? »)
            h_.setVisible(not self.coord_on)

    def set_smooth(self, on):
        """Courbes lissées (antialiasing) du spectre, de la rémanence et des scans gardés : plus joli, plus lourd."""
        self.smooth = bool(on)
        pg.setConfigOptions(antialias=self.smooth)
        items = [getattr(self, n_, None) for n_ in ("curve", "maxcurve", "refcurve")] + list(getattr(self, "_hist_items", []))
        try:                                       # (objets factices dans les tests : rien à faire)
            for it in items:
                if it is None:
                    continue
                it.opts["antialias"] = self.smooth
                it.curve.opts["antialias"] = self.smooth
                it.curve.update()
            sc = getattr(self, "sitecurve", None)
            if sc is not None:
                sc.opts["antialias"] = self.smooth
                sc.update()
        except (TypeError, AttributeError, KeyError):
            pass

    def update_plot(self, hist=True):
        try:
            self._update_plot(hist)
        finally:
            self.marker_refresh()

    def _update_plot(self, hist=True):
        nan = np.array([np.nan])
        sites = self.view_sites()
        if sites is not None and self._zoom is None:
            # 📍 scène choisie = un lieu : son direct à lui (tinySA posé là), sinon rien en direct (son spectre
            # gardé reste en pointillés, voir update_site_curve)
            xs, ys, mxs, mys = [], [], [], []
            now, stale = time.time(), max(15.0, 4 * self.last_cycle)
            for site in sites:
                for bid, (f, l, t) in sorted(self.site_live.get(site, {}).items(), key=lambda kv: float(kv[1][0][0])):
                    if now - t > stale or (self.view_id != -1 and bid != self.view_id):
                        continue
                    xs += [f, nan]
                    ys += [l, nan]
                    mh = self.site_mh.get(site, {}).get(bid)
                    mxs += [mh[0] if mh is not None else f, nan]
                    mys += [mh[1] if mh is not None and mh[1].shape == l.shape else l, nan]
            if xs:
                x, y = np.concatenate(xs), np.concatenate(ys)
                self._last_xy = (x, y)
                self.curve.setData(x, y)
                self.maxcurve.setData(np.concatenate(mxs), np.concatenate(mys)) if self.hold_chk.isChecked() \
                    else self.maxcurve.setData([], [])
            else:
                self.curve.setData([], [])
                self.maxcurve.setData([], [])
            self._update_history([])
            if self._fit_x:
                rng = self._fit_range()
                if rng:
                    span = rng[1] - rng[0]
                    self.spec.getPlotItem().setXRange(rng[0] - 0.01 * span, rng[1] + 0.01 * span, padding=0)
                self._fit_x = False
            self._update_markers()
            return
        if self.view_id == -1:
            live = {b["id"] for b in self.scan_bands() if b["enabled"]}
            keys = [k for k in set(self.latest) | set(self.partial_data) if k != ZOOM_ID and k in live]
            keys = [k for k in keys if self._series(k) is not None and len(self._series(k)[0])]
            keys.sort(key=lambda k: self._series(k)[0][0])
        else:
            keys = [self.view_id] if self._series(self.view_id) is not None else []
        if not keys:
            self._clear_plot()
            if self._fit_x and self._zoom is None:       # pas encore de mesure : l'axe montre déjà les bandes
                rng = self._fit_range()                    # (1er lancement : 470–694 MHz, pas 0–1 MHz — Clément)
                if rng:
                    span = rng[1] - rng[0]
                    self.spec.getPlotItem().setXRange(rng[0] - 0.01 * span, rng[1] + 0.01 * span, padding=0)
            return
        xs, ys, mxs, mys = [], [], [], []
        for k in keys:
            f, l = self._series(k)
            xs += [f, nan]
            ys += [l, nan]
            old, mh = self.latest.get(k), self.maxhold.get(k)
            if old is not None and mh is not None and mh.shape == old[1].shape:
                mxs += [old[0], nan]
                mys += [mh, nan]
            else:
                mxs += [f, nan]
                mys += [l, nan]
        x, y = np.concatenate(xs), np.concatenate(ys)
        mx, my = np.concatenate(mxs), np.concatenate(mys)
        self._last_xy = (x, y)
        self.curve.setData(x, y)
        if self.hold_chk.isChecked():
            self.maxcurve.setData(mx, my)
        else:
            self.maxcurve.setData([], [])
        if hist:
            self._update_history(keys)
        if self._fit_x and self._zoom is None:
            rng = self._fit_range()
            if rng:
                span = rng[1] - rng[0]
                self.spec.getPlotItem().setXRange(rng[0] - 0.01 * span, rng[1] + 0.01 * span, padding=0)
            self._fit_x = False
        elif self._zoom is not None:
            self._fit_x = False
        self._update_markers()

    def _clear_plot(self):
        self.curve.setData([], [])
        self.maxcurve.setData([], [])
        self._update_history([])
        self._update_markers()

    def _update_history(self, keys):
        """Rémanence (7.55, façon analyseur numérique) : les anciens balayages ne sont plus N courbes empilées mais UNE
        image de densité (density_raster) : ce qui revient souvent brille, un passage rare reste en trace fantôme.
        Une seule image à dessiner (au lieu de N chemins) : ≈ −10 % de processeur mesuré en démo."""
        n = self.persist_combo.currentData() or 0
        traces = []
        for i in range(n):
            xs, ys = [], []
            for k in keys:
                h = self.history.get(k)
                if k in self.latest and h and len(h) > i:
                    f, l = h[-1 - i]
                    xs += [np.asarray(f, dtype=float), np.array([np.nan])]
                    ys += [np.asarray(l, dtype=float), np.array([np.nan])]
            if xs:
                traces.append((np.concatenate(xs), np.concatenate(ys)))
        self._dens_traces = traces
        self._dens_n = n
        self._density_draw()

    def _density_item(self):
        img = getattr(self, "_dens_img", None)
        if img is None:
            img = pg.ImageItem()
            img.setZValue(-1)
            img.setLookupTable(density_lut(self.theme["curve"]))
            img.setLevels((0.0, 1.0))
            self.spec.getPlotItem().addItem(img, ignoreBounds=True)
            self._dens_img = img
            # vue déplacée / zoomée / fenêtre redimensionnée : image refaite (calcul ≈ 20 ms, regroupé)
            self._dens_timer = QtCore.QTimer(self)
            self._dens_timer.setSingleShot(True)
            self._dens_timer.setInterval(60)
            self._dens_timer.timeout.connect(self._density_draw)
            vb = self.spec.getPlotItem().vb
            vb.sigXRangeChanged.connect(lambda *a: self._dens_timer.start())
            vb.sigYRangeChanged.connect(lambda *a: self._dens_timer.start())
            vb.sigResized.connect(lambda *a: self._dens_timer.start())
        return img

    def _density_draw(self):
        traces = getattr(self, "_dens_traces", None)
        img = getattr(self, "_dens_img", None)
        if not traces:
            if img is not None:
                img.setVisible(False)
            return
        img = self._density_item()
        vb = self.spec.getPlotItem().vb
        (x0, x1), (y0, y1) = vb.viewRange()
        W = int(min(1800, max(64, vb.width())))
        H = int(min(700, max(48, vb.height())))
        n = max(1, getattr(self, "_dens_n", len(traces)))
        w = [1.0 - i / (n + 1.0) for i in range(len(traces))]
        try:
            arr = density_glow(density_raster(traces, x0, x1, y0, y1, W, H, w))
        except Exception:
            img.setVisible(False)
            return
        img.setImage(arr, autoLevels=False, levels=(0.0, 1.0))
        img.setRect(QtCore.QRectF(x0, y0, x1 - x0, y1 - y0))
        img.setVisible(True)

    def _clear_hist_pool(self):
        """Changement de thème : la rémanence prend la couleur de la nouvelle trace."""
        pi = self.spec.getPlotItem()
        for it in self._hist_items:
            pi.removeItem(it)
        self._hist_items = []
        img = getattr(self, "_dens_img", None)
        if img is not None:
            img.setLookupTable(density_lut(self.theme["curve"]))

    MK_STYLE = (("full", "Trait sur toute la hauteur"), ("top", "Petit repère discret en haut"))

    def _build_mk_menu(self):
        """Menu 📍 Repères, reconstruit à chaque ouverture (couches et statuts peuvent avoir changé)."""
        m = self.mk_menu
        m.clear()
        mk = self.mk

        def check(menu, txt, on, setter):
            a = menu.addAction(txt)
            a.setCheckable(True)
            a.setChecked(bool(on))
            # on lit l'état de la case : avec un paramètre optionnel, PySide6 appelle la fonction SANS l'argument
            # « checked » (il valait toujours False : impossible de recocher à la souris)
            a.triggered.connect(lambda *_, a=a: setter(a.isChecked()))
            return a

        def toggle_in(key, value):
            def f(on):
                lst = [x for x in mk[key] if x != value]
                if not on:
                    lst.append(value)
                self.set_markers(**{key: lst})
            return f

        def toggle_state(value):
            def f(on):
                lst = [x for x in mk["states"] if x != value] + ([value] if on else [])
                self.set_markers(states=lst)
            return f

        m.addAction("✔ Tout afficher (enlève les filtres)").triggered.connect(lambda *_: self.reset_markers())
        check(m, "Masquer tous les repères  (Ctrl+M)", not mk["on"], lambda on: self.set_markers(on=not on))
        m.addSection("Afficher selon l'état mesuré")
        for key, txt in MK_STATES:
            check(m, txt, key in mk["states"], toggle_state(key))
        check(m, "Toujours montrer les fréquences en alarme", mk["alarms"], lambda on: self.set_markers(alarms=on))
        sub_l = m.addMenu("Par scène › groupe")
        for sc in self.scenes:
            groups = [g["name"] for g in sc["groups"]] or [""]
            for g in groups:
                k = mk_layer_key(sc["name"], g)
                check(sub_l, f"{sc['name']} › {g}" if g else sc["name"], k not in mk["hide_layers"],
                      toggle_in("hide_layers", k))
        check(sub_l, "Sans scène", "" not in mk["hide_layers"], toggle_in("hide_layers", ""))
        sub_s = m.addMenu("Par statut")
        for st in [x["name"] for x in self.statuses] + [""]:
            check(sub_s, st or "(sans statut)", st not in mk["hide_status"], toggle_in("hide_status", st))
        n_hid = sum(1 for w in self.watch if w.get("hide_mk"))
        if n_hid:
            m.addAction(f"Réafficher les {n_hid} repère(s) masqué(s) à la main").triggered.connect(
                lambda *_: self.hide_marker_rows([i for i, w in enumerate(self.watch) if w.get("hide_mk")], False))
        m.addSection("Affichage")
        check(m, "Noms des fréquences", self.names_chk.isChecked(), self.names_chk.setChecked)
        check(m, "Signaux inconnus (pointillés)", mk["unk"] and self.unk_chk.isChecked(), self.set_unk_markers)
        m.addSection("Style")
        grp = QtGui.QActionGroup(m)
        for key, txt in self.MK_STYLE:
            grp.addAction(check(m, txt, mk["style"] == key, lambda on, k=key: on and self.set_markers(style=k)))
        m.addSection("Couleur")
        grp2 = QtGui.QActionGroup(m)
        for i in range(self.mark_combo.count()):
            key, txt = self.mark_combo.itemData(i), self.mark_combo.itemText(i).replace(TR("Repères : "), "")
            grp2.addAction(check(m, txt, self.mark_combo.currentData() == key,
                                 lambda on, k=key: on and self.mark_combo.setCurrentIndex(self.mark_combo.findData(k))))

    def _sync_mk_menu(self):
        if hasattr(self, "mk_btn"):
            self.mk_btn.setText("📍 Repères" + (" (masqués)" if not self.mk["on"] else
                                                 " (filtrés)" if mk_filtered(self.mk) else ""))

    def set_markers(self, **kw):
        for k, v in kw.items():
            if k in self.mk:
                self.mk[k] = v
        self._sync_mk_menu()
        self._update_markers()

    def set_unk_markers(self, on):
        """Repères des signaux inconnus ; les afficher demande aussi la détection (Réglages › Détection)."""
        if on and not self.unk_chk.isChecked():
            self.unk_chk.setChecked(True)
            self.set_status("Détection des signaux inconnus activée (Réglages › Détection) : leurs repères "
                            "apparaissent au prochain balayage.")
        self.set_markers(unk=on)

    def reset_markers(self):
        style, unk = self.mk["style"], self.mk["unk"]
        self.mk = dict(mk_default(), style=style, unk=unk)
        for w in self.watch:
            w.pop("hide_mk", None)
        self.set_markers()

    def toggle_markers(self):
        """Ctrl+M : tout masquer / réafficher (les filtres choisis sont gardés)."""
        self.set_markers(on=not self.mk["on"])
        self.set_status("Repères masqués (Ctrl+M pour les réafficher)." if not self.mk["on"] else "Repères affichés.")

    def hide_marker_rows(self, rows, hide=True):
        for r in rows:
            if 0 <= r < len(self.watch):
                if hide:
                    self.watch[r]["hide_mk"] = True
                else:
                    self.watch[r].pop("hide_mk", None)
        self.set_markers()

    def _marker_item(self, key):
        it = self._mk_items.get(key)
        if it is None:
            c_ = QtGui.QColor(key[0])
            c_.setAlphaF(0.72)                   # 7.54 : repères plus fins et un peu transparents (moins de « barreaux »)
            pen = pg.mkPen(c_, width=1.5, style=Qt.PenStyle.DotLine if key[1] else Qt.PenStyle.SolidLine)
            it = pg.PlotCurveItem(pen=pen, connect="pairs")
            self.spec.getPlotItem().addItem(it)
            self._mk_items[key] = it
        return it

    def _clear_marker_pool(self):
        pi = self.spec.getPlotItem()
        for it in self._mk_items.values():
            pi.removeItem(it)
        self._mk_items = {}

    def _update_markers(self):
        vb = self.spec.getPlotItem().vb
        (x0, x1), (y0, y1) = vb.viewRange()
        vis = [w for w in self.watch if x0 <= w["freq"] + (w.get("bw") or 0) / 2 and
               w["freq"] - (w.get("bw") or 0) / 2 <= x1 and self.in_scope(w)]
        unk = [f for lst in self.unk_now.values() for f in lst if x0 <= f <= x1]
        mk = self.mk
        vis = [w for w in vis if marker_visible(
            w, mk, alarm=bool(w.get("absent")) or (w["state"] == "occ" and self.is_keep_free(w["status"])))]
        if not mk["on"] or not mk["unk"]:
            unk = []
        ys = [-130.0, 0.0] if self.mk["style"] == "full" else [y1 - (y1 - y0) * 0.07, y1]
        mode = self.mark_combo.currentData()
        groups, colors = {}, []
        for w in vis:
            col = None
            if mode == "status" and w["status"]:
                col = self.status_color(w["status"])
            elif mode == "group":
                col = self.group_color(w["scene"], w["group"])
            if col is None:
                col = self.sig_view(w)[2] if w["state"] is not None else self.theme["st_none"]
            seg = groups.setdefault((col, False), ([], []))
            bw = w.get("bw") or 0.0
            if bw:                         # bloc : bord gauche, bord droit, barre en haut
                a, b = w["freq"] - bw / 2, w["freq"] + bw / 2
                ybar = min(ys[1], y1 - (y1 - y0) * 0.015)
                seg[0].extend([a, a, b, b, a, b])
                seg[1].extend([ys[0], ys[1], ys[0], ys[1], ybar, ybar])
            else:
                seg[0].extend([w["freq"], w["freq"]])
                seg[1].extend(ys)
            colors.append(col)
        for f in unk:
            seg = groups.setdefault((self.theme["st_unk"], True), ([], []))
            seg[0].extend([f, f])
            seg[1].extend(ys)
        for key, (xs_, ys_) in groups.items():
            self._marker_item(key).setData(np.array(xs_), np.array(ys_))
        for key, it in self._mk_items.items():
            if key not in groups:
                it.setData(np.array([]), np.array([]))

        show = self.names_chk.isChecked() and 0 < len(vis) <= MAX_LABELS
        pi = self.spec.getPlotItem()
        while len(self.labels) < MAX_LABELS:
            lab = pg.TextItem("", anchor=(0.5, 0))
            pi.addItem(lab, ignoreBounds=True)
            lab.setVisible(False)
            self.labels.append(lab)
        for i, lab in enumerate(self.labels):
            if show and i < len(vis):
                lab.setText(vis[i]["name"], color=colors[i])
                dy = (y1 - y0) * (0.08 if self.mk["style"] == "top" else 0.0)
                lab.setPos(vis[i]["freq"], y1 - 2.0 - dy - (i % 3) * 5.5)
                lab.setVisible(True)
            else:
                lab.setVisible(False)
        self._update_selection()
        self._place_site_lbl()

    def _on_watch_sel(self):
        self._update_selection()
        rows = self._sel_rows()
        if len(rows) == 1 and self._last_xy is not None:
            w = self.watch[rows[0]]
            (x0, x1), _ = self.spec.getPlotItem().vb.viewRange()
            if not x0 <= w["freq"] <= x1:
                self.set_status(f"« {w['name']} » ({w['freq']:.3f} MHz) est hors de la vue du spectre : "
                                f"double-clic sur son niveau pour zoomer dessus.")

    def _update_selection(self):
        """Fréquence(s) choisie(s) dans la liste : ressortent sur le spectre (bande ambrée, trait épais, nom)."""
        pi = self.spec.getPlotItem()
        if self._sel_items is None:
            c = QtGui.QColor(SEL_COLOR)
            c.setAlpha(80)
            regs = []
            for _i in range(SEL_MAX):
                r = pg.LinearRegionItem(values=(0, 0), movable=False, brush=pg.mkBrush(c),
                                        pen=pg.mkPen(SEL_COLOR, width=1))
                r.setZValue(-5)
                r.setVisible(False)
                pi.addItem(r, ignoreBounds=True)
                regs.append(r)
            line = pg.PlotCurveItem(pen=pg.mkPen(SEL_COLOR, width=3.5), connect="pairs")
            line.setZValue(40)
            pi.addItem(line, ignoreBounds=True)
            lab = pg.TextItem("", color=SEL_COLOR, anchor=(0.5, 1), fill=pg.mkBrush(0, 0, 0, 170),
                              border=pg.mkPen(SEL_COLOR))
            lab.setZValue(50)
            lab.setVisible(False)
            pi.addItem(lab, ignoreBounds=True)
            self._sel_items = (regs, line, lab)
        regs, line, lab = self._sel_items
        rows = self._sel_rows()[:SEL_MAX]
        (x0, x1), (y0, y1) = pi.vb.viewRange()
        xs, ys = [], []
        for i, r in enumerate(regs):
            if i < len(rows):
                w = self.watch[rows[i]]
                half = max((w.get("bw") or 0.0) / 2, (x1 - x0) * 0.006)
                r.setRegion((w["freq"] - half, w["freq"] + half))
                r.setVisible(True)
                if not w.get("bw"):
                    xs += [w["freq"], w["freq"]]
                    ys += [y0, y1]
            else:
                r.setVisible(False)
        line.setData(np.array(xs, dtype=float), np.array(ys, dtype=float))
        if len(rows) == 1:
            w = self.watch[rows[0]]
            lvl = "" if w.get("level") is None else "  " + self.lvl(w["level"], suffix=True)
            lab.setText(f"{w['name']}  {w['freq']:.3f}" + lvl)
            rel = (w["freq"] - x0) / max(1e-9, x1 - x0)          # près d'un bord : texte du côté intérieur
            lab.setAnchor((0.0, 1) if rel < 0.2 else (1.0, 1) if rel > 0.8 else (0.5, 1))
            lab.setPos(w["freq"], y0 + (y1 - y0) * 0.16)
            lab.setVisible(True)
        else:
            lab.setVisible(False)

    def update_waterfall(self, bid, f, l):
        lr = decimate_max(l, WF_MAX_COLS)
        if self.wf_hist is None or self.wf_id != bid or self.wf_hist.shape[0] != len(lr):
            self.wf_hist = np.full((len(lr), WF_ROWS), np.nan, dtype=np.float32)   # 8.1 : vide = transparent
            self.wf_id = bid
        self.wf_hist = np.roll(self.wf_hist, 1, axis=1)
        self.wf_hist[:, 0] = lr
        self.wf_img.setImage(self.wf_hist, autoLevels=False, levels=(-115, -40))
        self.wf_img.setRect(QtCore.QRectF(float(f[0]), 0.0, float(f[-1] - f[0]), float(WF_ROWS)))
        self.wf.getPlotItem().setYRange(0, WF_ROWS, padding=0)

    def on_mouse(self, evt):
        pos = evt[0]
        if not self.spec.sceneBoundingRect().contains(pos):
            return
        xm = self.spec.getPlotItem().vb.mapSceneToView(pos).x()
        self._show_band_info(float(xm))
        if self._last_xy is None:
            return
        x, y = self._last_xy
        try:
            k = int(np.nanargmin(np.abs(x - xm)))
        except ValueError:
            return
        self.readout.setText(f"{x[k]:.3f} MHz   {self.lvl(float(y[k]), suffix=True)}")
        self.readout.setToolTip(TR("Sur 50 Ω : {}").format(rf_linear_text(float(y[k]))))   # 8.1 : µV, pW…

    def capture(self):
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, "Capture du spectre", f"spectre_{datetime.now():%Y%m%d_%H%M%S}.png", "PNG (*.png)")
        if path:
            ex = pg.exporters.ImageExporter(self.spec.getPlotItem())
            ex.parameters()["width"] = 1800
            ex.export(path)
            self.set_status(f"Capture enregistrée : {path}")

    # ----------------------------------------------------------- seuils
    def _thr_from_spin(self, v):
        if abs(self.thr_line.value() - v) > 1e-6:
            self.thr_line.setValue(v)

    def _thr_from_line(self):
        v = round(self.thr_line.value(), 1)
        if abs(self.thr_spin.value() - v) > 1e-6:
            self.thr_spin.setValue(max(-130, min(0, v)))

    def _weak_from_spin(self, v):
        if abs(self.weak_line.value() - v) > 1e-6:
            self.weak_line.setValue(v)

    def _weak_from_line(self):
        v = round(self.weak_line.value(), 1)
        if abs(self.weak_spin.value() - v) > 1e-6:
            self.weak_spin.setValue(max(-130, min(0, v)))

    def _weak_toggled(self, on):
        self.weak_spin.setEnabled(on)
        self.auto_weak_spin.setEnabled(on)
        self.weak_line.setVisible(on and not self.thr_auto)

    def auto_threshold(self):
        """Ancien bouton « Auto » (une seule fois) : allume maintenant les seuils automatiques."""
        self.thr_auto_btn.setChecked(True)

    def auto_margins(self):
        return float(self.auto_occ_spin.value()), float(self.auto_weak_spin.value())

    def set_thr_auto(self, on):
        """Seuils automatiques : bruit de fond appris + marges, fréquence par fréquence."""
        on = bool(on)
        self.thr_auto = on
        if self.thr_auto_btn.isChecked() != on:
            self.thr_auto_btn.setChecked(on)
        for w_ in (self.thr_spin, self.weak_spin):
            w_.setVisible(not on)
        for w_ in (self.auto_occ_spin, self.auto_weak_spin):
            w_.setVisible(on)
        self.thr_line.setVisible(not on)
        self.weak_line.setVisible(not on and self.weak_chk.isChecked())
        if not on:
            self.auto_curve.setVisible(False)
        self._auto_curve_draw()
        self.reeval()

    def _auto_margins_changed(self):
        self._auto_curve_draw()
        self.reeval()

    def show_auto_thr_help(self):
        """❓ Fiche « Comment marche le seuil auto ? » (non bloquante)."""
        d = getattr(self, "_auto_help", None)
        if d is None:
            d = QtWidgets.QDialog(self)
            d.setWindowTitle("Comment marche le seuil auto ?")
            lay = QtWidgets.QVBoxLayout(d)
            lb = QtWidgets.QLabel(auto_thr_help_html(TR))
            lb.setWordWrap(True)
            lb.setTextFormat(Qt.TextFormat.RichText)
            sc = QtWidgets.QScrollArea()
            sc.setWidgetResizable(True)
            sc.setWidget(lb)
            lay.addWidget(sc, 1)
            row = QtWidgets.QHBoxLayout()
            man = QtWidgets.QPushButton("❓ Manuel")
            man.setToolTip("Le chapitre du manuel sur les seuils.")
            man.clicked.connect(lambda *_: self.open_manual("seuils"))
            tnt = QtWidgets.QPushButton("📺 Canaux TNT…")
            tnt.setToolTip("Les canaux pris par la TNT, comparés au vrai bruit du lieu.")
            tnt.clicked.connect(lambda *_: self.open_tnt())
            ok_ = QtWidgets.QPushButton("Fermer")
            ok_.setToolTip("Ferme la fiche.")
            ok_.clicked.connect(lambda *_: d.close())
            row.addWidget(man)
            row.addWidget(tnt)
            row.addStretch(1)
            row.addWidget(ok_)
            lay.addLayout(row)
            fit_dialog(d, 620, 560)
            self._auto_help = d
        d.show()
        d.raise_()
        return d

    def _auto_curve_update(self, now=None):
        """Bruit de fond le long du spectre (courbe en tirets) + valeurs « typiques » des seuils globaux (utilisées par
        les outils : coordination, scans…)."""
        if not self.thr_auto or not self.latest:
            return
        now = time.time() if now is None else now
        F = np.concatenate([v[0] for v in self.latest.values()])
        L = np.concatenate([v[1] for v in self.latest.values()])
        Fc, Lc = floor_curve(F, L)
        if Fc is None:
            return
        prev = self._acurve
        if prev is not None and len(prev[0]) == len(Fc) and np.allclose(prev[0], Fc):
            Lc = floor_track(prev[1], Lc, now - prev[2])
        self._acurve = (Fc, Lc, now)
        fin = Lc[np.isfinite(Lc)]
        if len(fin):
            m_occ, m_weak = self.auto_margins()
            med = float(np.median(fin))
            self.thr_spin.setValue(max(-130, min(0, round(med + m_occ))))
            self.weak_spin.setValue(max(-130, min(0, round(med + m_weak))))
        self._auto_curve_draw()

    def _auto_curve_draw(self):
        on = self.thr_auto and self._acurve is not None
        self.auto_curve.setVisible(bool(on))
        if on:
            Fc, Lc, _ = self._acurve
            self.auto_curve.setData(Fc, Lc + self.auto_margins()[0])     # en dBm : l'axe gauche convertit

    def auto_thr_at(self, f):
        """Seuil « occupé » automatique à f (MHz) d'après la courbe de bruit, ou None."""
        if not self.thr_auto or self._acurve is None:
            return None
        Fc, Lc, _ = self._acurve
        if f < Fc[0] - 1.0 or f > Fc[-1] + 1.0:
            return None
        ok = np.isfinite(Lc)
        if not ok.any():
            return None
        return float(np.interp(f, Fc[ok], Lc[ok])) + self.auto_margins()[0]

    # ------------------------------------------------------- marqueurs M1 / M2
    def _build_markers_bar(self):
        bar = QtWidgets.QWidget()
        self.mkr_bar = bar
        self.mkr_spins, self.mkr_lines = [], []
        cols = ("#ffd166", "#06d6a0")
        pi = self.spec.getPlotItem()
        for i, col in enumerate(cols):
            sp_ = QtWidgets.QDoubleSpinBox()
            sp_.setDecimals(3)
            sp_.setRange(0.0, 6000.0)
            sp_.setSuffix(" MHz")
            sp_.setKeyboardTracking(False)
            sp_.setToolTip(f"Fréquence du marqueur M{i + 1} : tape-la, ou molette / flèches (pas choisi à droite).")
            ln = pg.InfiniteLine(pos=0.0, angle=90, movable=True, pen=pg.mkPen(col, width=1.4, style=Qt.PenStyle.DashLine),
                                 label=f"M{i + 1}", labelOpts=dict(position=0.96, color=col, fill=(0, 0, 0, 160)))
            ln.setVisible(False)
            pi.addItem(ln, ignoreBounds=True)
            ln.sigPositionChanged.connect(lambda *_, i=i: self._mkr_from_line(i))
            sp_.valueChanged.connect(lambda v, i=i: self._mkr_from_spin(i, v))
            self.mkr_spins.append(sp_)
            self.mkr_lines.append(ln)
        self.mkr_step = self._combo([("pas 1 kHz", 0.001), ("pas 5 kHz", 0.005), ("pas 25 kHz", 0.025),
                                     ("pas 100 kHz", 0.1), ("pas 1 MHz", 1.0)], 0.025)
        self.mkr_step.setToolTip("De combien bougent les marqueurs à chaque cran de molette / flèche.")
        self.mkr_step.currentIndexChanged.connect(lambda *_: [s_.setSingleStep(self.mkr_step.currentData())
                                                              for s_ in self.mkr_spins])
        for s_ in self.mkr_spins:
            s_.setSingleStep(0.025)
        pk = QtWidgets.QPushButton("⤒ Pic")
        pk.setToolTip("Place M1 sur le plus haut signal à ±0,5 MHz.")
        pk.clicked.connect(lambda *_: self.marker_to_peak(0))
        self.mkr2_chk = QtWidgets.QCheckBox("M2")
        self.mkr2_chk.setToolTip("Deuxième marqueur : écart en fréquence et en niveau entre M1 et M2.")
        self.mkr2_chk.toggled.connect(lambda *_: self._mkr_visible())
        self.mkr_drop = QtWidgets.QSpinBox()
        self.mkr_drop.setRange(3, 60)
        self.mkr_drop.setValue(20)
        self.mkr_drop.setPrefix("largeur à −")
        self.mkr_drop.setSuffix(" dB")
        self.mkr_drop.setToolTip("Bande occupée autour du pic près de M1 : là où le niveau reste au-dessus du pic moins "
                                 "cette valeur.")
        self.mkr_drop.valueChanged.connect(lambda *_: self.marker_refresh())
        self.mkr_lbl = QtWidgets.QLabel("")
        self._elastic(self.mkr_lbl)
        self.mkr_lbl.setStyleSheet("font-family:Consolas,monospace;")
        self.mkr_lbl.setMinimumWidth(260)
        self.mkr_lbl.setToolTip("M1 : fréquence et niveau · Δ : écart M1 → M2 · largeur occupée autour du pic.")
        lay = self._flow(("M1 :", self.mkr_spins[0], pk), (self.mkr2_chk, self.mkr_spins[1]), self.mkr_step,
                         self.mkr_drop, self.mkr_lbl)
        lay.setContentsMargins(0, 0, 0, 0)
        bar.setLayout(lay)
        bar.setVisible(False)
        return bar

    def show_markers_bar(self, on):
        self.mkr_bar.setVisible(bool(on))
        if on and not any(s_.value() for s_ in self.mkr_spins):
            x0, x1 = self.spec.getPlotItem().vb.viewRange()[0]
            self.mkr_spins[0].setValue((x0 + x1) / 2.0)
            self.mkr_spins[1].setValue(x0 + (x1 - x0) * 0.6)
        self._mkr_visible()
        self.marker_refresh()

    def _mkr_visible(self):
        on = self.mkr_btn.isChecked()
        self.mkr_lines[0].setVisible(on)
        self.mkr_lines[1].setVisible(on and self.mkr2_chk.isChecked())
        self.mkr_spins[1].setEnabled(self.mkr2_chk.isChecked())
        self.marker_refresh()

    def _mkr_from_line(self, i):
        sp_ = self.mkr_spins[i]
        sp_.blockSignals(True)
        sp_.setValue(self.mkr_lines[i].value())
        sp_.blockSignals(False)
        self.marker_refresh()

    def _mkr_from_spin(self, i, v):
        ln = self.mkr_lines[i]
        ln.blockSignals(True)
        ln.setValue(float(v))
        ln.blockSignals(False)
        self.marker_refresh()

    def _mkr_trace(self):
        try:
            x, y = self.curve.getData()
        except (TypeError, ValueError):            # pas encore de courbe
            return None, None
        return (None, None) if x is None or not isinstance(x, np.ndarray) else (x, y)

    def marker_to_peak(self, i=0):
        F, L = self._mkr_trace()
        pk = None if F is None else peak_near(F, L, self.mkr_spins[i].value())
        if pk is not None:
            self.mkr_spins[i].setValue(pk[0])

    def marker_refresh(self):
        if not getattr(self, "mkr_btn", None) or not self.mkr_btn.isChecked():
            return
        F, L = self._mkr_trace()
        f1 = self.mkr_spins[0].value()
        p1 = None if F is None else trace_at(F, L, f1)
        txt = f"M1 {f1:.3f} MHz " + (self.lvl(p1[1], suffix=True) if p1 else "—")
        if self.mkr2_chk.isChecked():
            f2 = self.mkr_spins[1].value()
            p2 = None if F is None else trace_at(F, L, f2)
            txt += f" · M2 {f2:.3f} · Δ {(f2 - f1) * 1000:+.0f} kHz"
            if p1 and p2:
                txt += f" / {p2[1] - p1[1]:+.1f} dB"
        ow = None if F is None else occupied_width(F, L, f1, self.mkr_drop.value())
        if ow:
            txt += f" · largeur {(ow[1] - ow[0]) * 1000:.0f} kHz"
        self.mkr_lbl.setText(txt)
        self.mkr_lbl.setToolTip(txt)

    def open_spectrum_legend(self):
        d = getattr(self, "_legend", None)
        if d is None:
            d = self._legend = SpectrumLegendDialog(self)        # gardée (cachée à la fermeture) : ses liens
        d.show()
        d.raise_()

    def reset_max(self):
        self.maxhold.clear()
        for w in self.watch:
            w["max"] = None
            w["occw"].clear()
        self.update_watch_table(force=True)
        self.update_plot()

    # ---------------------------------------------------------------- thème
    def apply_theme(self):
        t = self.theme
        app = QtWidgets.QApplication.instance()
        app.setStyle("Fusion")
        app.setPalette(build_palette(t))
        app.setStyleSheet(make_stylesheet(t) + qss_icons(t))
        try:
            for w in (self.spec, self.wf, self.bandw):
                w.setBackground(t["plot_bg"])
                pi = w.getPlotItem()
                for ax in ("bottom", "left"):
                    a = pi.getAxis(ax)
                    a.setPen(pg.mkPen(t["plot_fg"]))
                    a.setTextPen(pg.mkPen(t["plot_fg"]))
            crt = t.get("plot_style") == "crt"
            self.curve.setPen(pg.mkPen(t["curve"], width=1.8 if crt else 1.6))
            # 7.54.2 (fluidité, mesuré en démo à 1920 × 1080) : la grille fine (sous-graduations) coûtait ~16 % de
            # processeur à elle seule -> grands carreaux seulement, pour tous les thèmes (59 % -> 43 %). Le halo du
            # phosphore (stylo de plus d'1 px sous la trace) doublait le coût du dessin (43 % -> 87 %) : retiré.
            self.spec.getPlotItem().showGrid(x=True, y=True, alpha=0.40 if crt else 0.25)
            for ax in ("bottom", "left"):
                a_ = self.spec.getPlotItem().getAxis(ax)
                a_.setStyle(maxTickLevel=0, maxTextLevel=0)
                a_.setTickDensity(2.6 if ax == "left" else 1.6)
            self.maxcurve.setPen(pg.mkPen(t["maxhold"], width=1))
            self.refcurve.setPen(pg.mkPen(t["ref"], width=1.3, style=Qt.PenStyle.DashLine))
            self.thr_line.setPen(pg.mkPen(t["thr"], width=1.5, style=Qt.PenStyle.DashLine))
            self.weak_line.setPen(pg.mkPen(t["thr_weak"], width=1.2, style=Qt.PenStyle.DotLine))
            if getattr(self, "auto_curve", None) is not None:
                self.auto_curve.setPen(pg.mkPen(t["thr"], width=1.3, style=Qt.PenStyle.DashLine))
            self.wf_img.setLookupTable(make_lut(t.get("wf", "Inferno")))
        except Exception:
            pass
        self._clear_marker_pool()
        self._clear_hist_pool()
        self._style_start(self.is_running())
        self.readout.setStyleSheet("font-family:Consolas,monospace;")
        self.update_strips()
        self.update_watch_table(force=True)
        self._update_markers()

    # ------------------------------------------------- pays / plan de fréquences
    def on_country(self, *_):
        self.rebuild_plan()

    def rebuild_plan(self):
        code = self.country_combo.currentData() or "FR"
        self.country = code
        self.plan = build_plan(code, self.plan_custom.get(code))
        self.tv = tv_channels(code)
        note = COUNTRY_NOTES.get(code, "")
        if code in self.plan_custom:
            note += "\n(plan modifié par toi)"
        self.country_note.setText(note + "\nIndicatif : vérifie toujours auprès du régulateur de ton pays.")
        rs = reg_summary(code, TR)
        self.reg_lbl.setToolTip(reg_detail(code, TR))
        a_, b_ = country_uhf(code)
        self.reg_lbl.setText(f"Micros autorisés (indicatif) : {rs}\nBalayé : {a_:g}-{b_:g} MHz (mesurer n'est pas "
                             f"émettre)." if rs else "⚠ Aucune liste de bandes autorisées pour ce pays : rien n'est "
                             "vérifié réglementairement.")
        self.update_strips()
        for w in self.watch:
            w["band"], w["cat"] = spectrum_info(w["freq"], self.plan, self.tv)
            w["sig"] = None
        self.update_watch_table(force=True)

    def edit_plan(self):
        code = self.country_combo.currentData() or "FR"
        name = dict(COUNTRIES).get(code, code)
        dlg = PlanDialog(self, name, plan_to_text(self.plan))
        if not dlg.exec():
            return
        txt = dlg.result_text()
        if txt.strip():
            self.plan_custom[code] = txt
        else:
            self.plan_custom.pop(code, None)
        self.rebuild_plan()

    def _update_legend(self):
        used = {e[3] for e in self.plan} | {e[3] for e in self.tv}
        lines = [f"<span style='color:{self.theme.get('bp_' + k, '#888')}'>■</span> {lab}"
                 for k, (lab, _c) in CATEGORIES.items() if k in used]
        self.legend_lbl.setText("<br>".join(lines))

    def update_strips(self, *_):
        pi = self.bandw.getPlotItem()
        for it in self._strip_rects:
            pi.removeItem(it)
        self._strip_rects = []
        rows = []
        if self.alloc_chk.isChecked() and self.plan:
            rows.append(self.plan)
        if self.tv_chk.isChecked() and self.tv:
            rows.append(self.tv)
        self._strip_rows = []
        self.bandw.setVisible(bool(rows))
        self._update_legend()
        if not rows:
            self.update_strip_labels()
            return
        n = len(rows)
        self.bandw.setFixedHeight(30 * n + 4)
        pi.setYRange(0, n, padding=0)
        th = self.theme
        edge = pg.mkPen(th["plot_bg"], width=1)
        for k, entries in enumerate(rows):
            y0 = n - 1 - k
            self._strip_rows.append((entries, y0))
            for (a, b, lab, cat, note) in entries:
                r = QtWidgets.QGraphicsRectItem(a, y0 + 0.06, b - a, 0.88)
                r.setBrush(pg.mkBrush(blend(th.get("bp_" + cat, "#64748b"), th["plot_bg"], 0.62)))
                r.setPen(edge)
                pi.addItem(r, ignoreBounds=True)
                self._strip_rects.append(r)
        self.update_strip_labels()

    def update_strip_labels(self):
        if not self._strip_rows:
            for lb in self._strip_labels:
                lb.setVisible(False)
            return
        pi = self.bandw.getPlotItem()
        x0, x1 = pi.vb.viewRange()[0]
        px = max(50.0, float(pi.vb.width())) / max(1e-6, x1 - x0)     # pixels par MHz
        th, k = self.theme, 0
        for entries, y0 in self._strip_rows:
            for (a, b, lab, cat, note) in entries:
                if b < x0 or a > x1:
                    continue
                lo, hi = max(a, x0), min(b, x1)
                nch = int((hi - lo) * px / 6.4)
                lab = TR(lab)                             # libellé dessiné (pas un widget Qt) : traduit ici
                if lab.startswith("CH "):
                    txt = lab if nch >= 5 else lab[3:]
                    if nch < 2 or len(txt) > nch:
                        continue
                else:
                    if nch < 4:
                        continue
                    txt = lab if len(lab) <= nch else lab[:nch - 1] + "…"
                while len(self._strip_labels) <= k:
                    t = pg.TextItem("", anchor=(0.5, 0.5))
                    t.setFont(QtGui.QFont("Segoe UI", 8))
                    t.setZValue(5)
                    pi.addItem(t, ignoreBounds=True)
                    self._strip_labels.append(t)
                t = self._strip_labels[k]
                t.setText(txt, color=contrast_text(blend(th.get("bp_" + cat, "#64748b"), th["plot_bg"], 0.62)))
                t.setPos((lo + hi) / 2.0, y0 + 0.5)
                t.setVisible(True)
                k += 1
        for t in self._strip_labels[k:]:
            t.setVisible(False)

    def on_mouse_band(self, evt):
        pos = evt[0]
        if not self.bandw.sceneBoundingRect().contains(pos):
            return
        self._show_band_info(self.bandw.getPlotItem().vb.mapSceneToView(pos).x())

    def _show_band_info(self, f):
        if f > 0:
            self.band_lbl.setText(describe_freq(f, self.plan, self.tv))

    # --------------------------------------------------- options de détection
    def reeval(self, *_):
        if self.latest:
            self.update_watch_levels()
        self.update_watch_table(force=True)

    def on_occ_window(self, *_):
        m = int(self.occ_combo.currentData() or 60)
        for w in self.watch:
            w["occw"].minutes = m
        self.update_watch_table(force=True)

    # ------------------------------------------------------ courbe de référence
    def _set_ref(self, curves):
        self.ref_curves = curves
        if curves:
            F = np.concatenate([c[0] for c in curves])
            L = np.concatenate([c[1] for c in curves])
            o = np.argsort(F)
            self._ref_F, self._ref_L = F[o], L[o]
        else:
            self._ref_F = self._ref_L = None
        self.update_ref_curve()

    def update_ref_curve(self):
        if not self.ref_curves or not self.showref_chk.isChecked():
            self.refcurve.setData([], [])
            return
        nan = np.array([np.nan])
        xs, ys = [], []
        for f, l in sorted(self.ref_curves, key=lambda c: c[0][0]):
            xs += [f, nan]
            ys += [l, nan]
        self.refcurve.setData(np.concatenate(xs), np.concatenate(ys))

    def capture_ref(self, src):
        curves = []
        for k in sorted(self.latest):
            f, l = self.latest[k]
            if src == "max":
                mh = self.maxhold.get(k)
                if mh is not None and mh.shape == l.shape:
                    l = mh
            curves.append((np.array(f, dtype=float), np.array(l, dtype=float)))
        if not curves:
            QtWidgets.QMessageBox.information(self, APP_NAME, "Lance d'abord un balayage (▶ Démarrer).")
            return
        self._set_ref(curves)
        self._save_ref_file(REF_PATH)
        self.reeval()
        self.set_status("Référence enregistrée (" + ("max hold" if src == "max" else "balayage actuel") +
                        "). Coche « Seuil = courbe de référence + » pour l'utiliser.")

    def _save_ref_file(self, path):
        try:
            Path(path).parent.mkdir(parents=True, exist_ok=True)
            data = dict(version=1, created=datetime.now().isoformat(timespec="seconds"),
                        curves=[dict(f=np.round(f, 6).tolist(), l=np.round(l, 1).tolist())
                                for f, l in self.ref_curves])
            Path(path).write_text(json.dumps(data), encoding="utf-8")
            return True
        except Exception as e:
            self.set_status(f"Référence non enregistrée : {e}")
            return False

    def _load_ref_file(self, path, silent=False):
        try:
            data = json.loads(Path(path).read_text(encoding="utf-8"))
            curves = []
            for c in data["curves"]:
                f, l = np.array(c["f"], dtype=float), np.array(c["l"], dtype=float)
                if len(f) and len(f) == len(l):
                    curves.append((f, l))
            if not curves:
                raise ValueError("aucune courbe dans ce fichier")
        except FileNotFoundError:
            return False
        except Exception as e:
            if not silent:
                QtWidgets.QMessageBox.warning(self, APP_NAME, f"Référence illisible :\n{e}")
            return False
        self._set_ref(curves)
        return True

    def save_ref_as(self):
        if not self.ref_curves:
            QtWidgets.QMessageBox.information(self, APP_NAME, "Aucune référence : capture-en une d'abord.")
            return
        d = CFG_PATH.parent / "references"
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Enregistrer la référence",
                                                        str(d / "reference_lieu.json"), "Référence (*.json)")
        if path and self._save_ref_file(path):
            self.set_status(f"Référence enregistrée : {path}")

    def load_ref_dialog(self):
        path, _ = QtWidgets.QFileDialog.getOpenFileName(self, "Charger une référence",
                                                        str(CFG_PATH.parent / "references"),
                                                        "Référence (*.json);;Tous les fichiers (*)")
        if path and self._load_ref_file(path):
            self._save_ref_file(REF_PATH)
            self.reeval()
            self.set_status(f"Référence chargée : {os.path.basename(path)}")

    def clear_ref(self):
        self._set_ref([])
        try:
            REF_PATH.unlink()
        except Exception:
            pass
        self.reeval()
        self.set_status("Référence effacée.")

    # --------------------------------------------------------- export du scan
    def export_scan(self):
        if not self.latest:
            QtWidgets.QMessageBox.information(self, APP_NAME, "Lance d'abord un balayage (▶ Démarrer).")
            return
        dlg = ExportScanDialog(self, self.export_prefs)
        if not dlg.exec():
            return
        v = dlg.values()
        self.export_prefs = {k: x for k, x in v.items() if k not in ("lo", "hi")}
        if v["scope"] == "view" and self.view_id in self.latest:
            keys = [self.view_id]
        else:
            keys = list(self.latest)
        keys.sort(key=lambda k: float(self.latest[k][0][0]))
        fs, live, mxs = [], [], []
        for k in keys:
            f, l = self.latest[k]
            mh = self.maxhold.get(k)
            fs.append(f)
            live.append(l)
            mxs.append(mh if (mh is not None and mh.shape == l.shape) else l)
        F, LV, MX = np.concatenate(fs), np.concatenate(live), np.concatenate(mxs)
        o = np.argsort(F, kind="stable")
        F, LV, MX = scan_crop(F[o], LV[o], MX[o], lo=v.get("lo"), hi=v.get("hi"))     # plage choisie
        if not len(F):
            QtWidgets.QMessageBox.information(self, APP_NAME, "Rien de mesuré dans cette plage.")
            return
        cols, names = [], []
        if v["src"] in ("live", "both"):
            cols.append(LV)
            names.append("Niveau (dBm)")
        if v["src"] in ("max", "both"):
            cols.append(MX)
            names.append("Max hold (dBm)")
        text = scan_csv(F, cols, v["unit"], v["delim"], v["dec"], v["header"], names)
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, "Exporter le scan", f"scan_{datetime.now():%Y%m%d_%H%M%S}"
            + (f"_{rbw_tag(self.live_rbw()[0])}" if rbw_tag(self.live_rbw()[0]) else "") + ".csv", "CSV (*.csv)")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8-sig") as fh:
                fh.write(text)
            self.set_status(f"Scan exporté ({len(F)} points) : {path}")
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, APP_NAME, f"Export impossible :\n{e}")

    # --------------------------------------------------- mur / journal auto
    def open_wall(self):
        """Le mur est un panneau : on l'affiche (en onglet à côté du spectre, ou là où tu l'as rangé)."""
        self.dock_wall.show()
        self.dock_wall.raise_()
        self.wall.rebuild()

    # ------------------------------------------------------- vocabulaire / saisie assistée
    def vocab_all(self, kind):
        """Mots proposés pour nommer : liste de base + mots appris + ce qui existe déjà."""
        base = {"name": NAME_WORDS, "scene": SCENE_WORDS, "group": GROUP_WORDS}[kind]
        extra = list(self.vocab_user.get(kind, []))
        if kind == "name":
            extra += label_words([w["name"] for w in self.watch])
        elif kind == "scene":
            extra += [s["name"] for s in self.scenes]
        else:
            extra += [g["name"] for s in self.scenes for g in s["groups"]]
        out, seen = [], set()
        for w in list(base) + extra:
            k = w.strip().lower()
            if k and k not in seen:
                seen.add(k)
                out.append(w.strip())
        return out

    def learn_word(self, kind, word):
        word = str(word).strip()
        if word and word.lower() not in {w.lower() for w in self.vocab_all(kind)}:
            lst = self.vocab_user.setdefault(kind, [])
            lst.append(word)
            del lst[:-300]

    def name_suggestions(self):
        return name_candidates(self.vocab_all("name"), [w["name"] for w in self.watch])

    def ask_name(self, kind, title, label, text=""):
        dlg = NameDialog(self, title, label, self.vocab_all(kind), text)
        if dlg.exec():
            return dlg.value(), True
        return "", False

    def edit_vocab(self):
        cur = "\n".join(self.vocab_user.get("name", []))
        txt, ok = QtWidgets.QInputDialog.getMultiLineText(
            self, "Mon vocabulaire", "Un mot par ligne (ex. Bolero, Cor anglais…). Ils seront proposés quand tu "
                                     "nommes une fréquence. Les mots de base (MIC, HF, IEM, Intercom…) y sont déjà.", cur)
        if ok:
            words = [x.strip() for x in txt.splitlines() if x.strip()]
            self.vocab_user["name"] = []
            for w in words:
                self.learn_word("name", w)
            self.set_status(f"Vocabulaire enregistré ({len(self.vocab_user['name'])} mot(s) à toi).")

    def quick_name_dialog(self, rows=None):
        rows = list(rows) if rows else self._sel_rows()
        if not rows:
            rows = [i for i, w in enumerate(self.watch) if self.in_scope(w)]
            if not rows:
                self.set_status("Aucune fréquence à nommer.")
                return
            self.set_status(f"Aucune ligne sélectionnée : on nomme les {len(rows)} fréquence(s) de la couche active.")
        dlg = QuickNameDialog(self, rows)
        if not dlg.exec():
            return
        names = dlg.names()
        if not names:
            return
        for i, nm in zip(rows, names):
            self.watch[i]["name"] = nm
            self.watch[i]["sig"] = None
        if dlg.learn_chk.isChecked():
            self.learn_word("name", dlg.word())
        self.update_watch_table(force=True)
        self._update_markers()
        self.set_status(f"{len(rows)} fréquence(s) nommée(s) : {names[0]} … {names[-1]}")

    def fill_down_names(self, rows=None):
        rows = list(rows) if rows else self._sel_rows()
        if len(rows) < 2:
            self.set_status("Sélectionne au moins 2 lignes : la 1ʳᵉ donne le nom de départ (ex. HF 1) et les "
                            "suivantes prennent HF 2, HF 3…")
            return
        names = number_run(self.watch[rows[0]]["name"], len(rows))
        for i, nm in zip(rows, names):
            self.watch[i]["name"] = nm
            self.watch[i]["sig"] = None
        self.update_watch_table(force=True)
        self._update_markers()
        self.set_status(f"Numérotées : {names[0]} … {names[-1]}")

    # ------------------------------------------------------- intermodulation / secours
    def fresh_FL(self, use_max=False, any_age=False):
        """Spectre actuel (toutes les bandes récentes) : (F trié, L) ou (None, None)."""
        now = time.time()
        stale = max(15.0, 4 * self.last_cycle)
        keys = [k for k in self.latest if k != ZOOM_ID and (any_age or now - self.latest_t.get(k, 0) <= stale)]
        if not keys:
            return None, None
        Fs, Ls = [], []
        for k in keys:
            f, l = self.latest[k]
            mh = self.maxhold.get(k) if use_max else None
            Fs.append(f)
            Ls.append(mh if (mh is not None and mh.shape == l.shape) else l)
        F, L = np.concatenate(Fs), np.concatenate(Ls)
        o = np.argsort(F)
        return F[o], L[o]

    def view_range(self, a, b, msg=None):
        self._fit_x = False
        self.spec.getPlotItem().setXRange(a, b, padding=0)
        self.set_status((msg + " : " if msg else "") + f"vue sur {a:g} – {b:g} MHz.")

    def open_intermod(self):
        self._im_dlg = IntermodDialog(self)
        self._im_dlg.show()

    def open_intermod_for(self, f):
        self._im_dlg = IntermodDialog(self, origin=f)
        self._im_dlg.show()

    def manual_path(self):
        """Le manuel (docs/manuel.html, en anglais docs/manual_en.html) : embarqué dans l'exe, ou à côté du
        script. None s'il manque."""
        names = (["manual_en.html"] if self.lang == "en" else []) + ["manuel.html"]
        for name in names:
            for base in (getattr(sys, "_MEIPASS", None), Path(__file__).resolve().parent):
                if base:
                    p_ = Path(base) / "docs" / name
                    if p_.is_file():
                        return p_
        return None

    def set_language(self, code):
        """Langue de l'interface : enregistrée tout de suite, appliquée au prochain démarrage (proposé)."""
        if code == self.lang:
            return
        self.lang = code
        self._save_config()
        if QtWidgets.QMessageBox.question(
                self, APP_NAME, "La langue changera au prochain démarrage. Redémarrer maintenant ?\n"
                                "The language will change at the next start. Restart now?") \
                != QtWidgets.QMessageBox.StandardButton.Yes:
            return
        if self.close() and not restart_app():
            QtWidgets.QMessageBox.information(None, APP_NAME, "Relance l'appli à la main pour changer de langue.\n"
                                              "Restart the app by hand to change the language.")

    def open_manual(self, chapter=None):
        p_ = self.manual_path()
        if p_ is None:
            QtWidgets.QMessageBox.information(self, APP_NAME, "Manuel introuvable à côté de l'appli : il est aussi "
                                              "dans le dépôt GitHub, fichier docs/manuel.html.")
            return
        url = QtCore.QUrl.fromLocalFile(str(p_))
        if chapter:                               # 7.59 : ❓ d'une fenêtre -> son chapitre
            url.setFragment(str(chapter))
        QtGui.QDesktopServices.openUrl(url)
        self.set_status("Manuel ouvert dans le navigateur.")

    def show_about(self):
        fw = self.info_lbl.text().strip() or "pas encore connecté"
        fw2 = f"<br>2ᵉ tinySA : {getattr(self, 'dev2_info', '') or '—'}" if self.dev2.get("on") else ""
        QtWidgets.QMessageBox.information(
            self, f"À propos de {APP_NAME}",
            f"<b>{APP_NAME}</b> version <b>{APP_VER}</b><br>"
            f"<i>{TR('Anciennement « TinySA Monitor » (jusqu’à la 8.0).')}</i><br>"
            f"Python {sys.version.split()[0]} · Qt {QtCore.qVersion()}<br><br>"
            f"tinySA : {fw}{fw2}<br><br>"
            f"Config : {CFG_PATH}<br>Journaux : {self.log_dir}<br><br>"
            f"<small>{COORD_NOTE}<br>{TRADEMARKS}</small>")

    def set_watch_freq(self, w, v):
        """Change la fréquence d'une ligne (mesures remises à zéro, liste retriée)."""
        k0, k1 = int(round(w["freq"] * 1000)), int(round(float(v) * 1000))
        for st in self.states:                     # 📸 elle reste dans ses états
            if k0 in st["keys"]:
                st["keys"] = sorted((set(st["keys"]) - {k0}) | {k1})
        w.update(freq=float(v), level=None, max=None, state=None, t_acc=None)
        w["occw"].clear()
        self.sort_watch()
        QtCore.QTimer.singleShot(0, self.rebuild_watch_table)
        self._update_markers()

    def open_listen(self, rows=None):
        self.sdr_timer()                                 # étape 12 : ménage des enregistrements
        if getattr(self, "_listen", None) is not None and self._listen.worker is not None:
            self._listen.raise_()
            self._listen.activateWindow()
            return
        self._listen = ListenDialog(self, rows if rows is not None else self._sel_rows())
        self._listen.show()

    def open_realtime(self, center=None):
        rt = getattr(self, "_rt", None)
        if rt is not None and rt.isVisible():
            if center is not None and rt.worker is None:
                rt.center_spin.setValue(center)
            rt.raise_()
            rt.activateWindow()
            return
        if center is None:
            rows = self._sel_rows()
            if rows:
                center = self.watch[rows[0]]["freq"]
            elif self._zoom:
                center = (self._zoom[0] + self._zoom[1]) / 2.0
            else:
                b = next((b for b in self.bands if b["enabled"]), None)
                center = (b["start"] + b["stop"]) / 2.0 if b else 600.0
        self._rt = RealtimeDialog(self, center)
        self._rt.show()

    def open_sdr(self):
        d = SdrDialog(self)
        if d.exec() == QtWidgets.QDialog.DialogCode.Accepted:
            self.sdr_cfg.update(d.values())
            for w in self.workers:
                w.sdr_dir = self.sdr_cfg.get("dir", "")
            self.set_status("Réglages SDR enregistrés" + (" (appliqués au prochain cycle)." if self.is_running()
                                                          else "."))

    # ---------------------------------------------------------------- V8 étape 6 : écouter de partout
    def sdr_model_for(self, kind):
        """Étape 7 : fiche du modèle choisi pour ce genre de SDR (⚙ Réglages SDR), sinon le modèle par défaut."""
        return sdr_model_of(kind, self.sdr_cfg.get("models"))

    def sdr_gains(self, kind):
        """Gains à passer aux outils pour ce genre de SDR, d'après son modèle."""
        return sdr_gains_for(self.sdr_model_for(kind), self.sdr_cfg.get("gains"),
                             {k: self.sdr_cfg[k] for k in ("lna", "vga", "amp") if k in self.sdr_cfg})

    def sdr_offset(self, kind):
        """Correction dBFS -> dBm du modèle (0 pour un appareil calibré)."""
        if kind == "demo":                              # étape 21 : SDR démo
            return DEMO_DBM
        m = self.sdr_model_for(kind)
        if m is None or m.get("cal"):
            return 0.0
        return float((self.sdr_cfg.get("offsets") or {}).get(m["key"], 0.0))

    def listen_freq(self, f, w=None):
        """🎧 Écouter une fréquence (FREQ_ACTIONS : alarme, tuile, chasse ; téléphone). Fréquence de la liste ou non."""
        d = getattr(self, "_listen", None)
        if d is not None:
            try:
                d.close()
            except RuntimeError:
                pass
        i = next((k for k, x in enumerate(self.watch) if x is w), None) if w is not None else None
        if i is None:
            i = next((k for k, x in enumerate(self.watch) if abs(x["freq"] - float(f)) < 0.0005), None)
        self._listen = ListenDialog(self, rows=[i] if i is not None else [], freqs=[] if i is not None else [float(f)])
        self._listen.show()
        self._listen.raise_()
        self._listen.toggle()
        return self._listen

    def sdr_burst_conflict(self, kind, w, ev):
        """Étape 8 : signal bref vu par le temps réel sur une fréquence « doit rester libre » -> alarme CONFLIT (clé
        « BREF » : pas effacée par le balayage suivant, qui ne l'a pas vu) qui se termine seule après 60 s."""
        if not self.is_keep_free(w.get("status")) or w.get("off"):
            return False
        now = time.time()
        fk = int(round(w["freq"] * 1000))
        key = ("BREF", fk)
        dur = max(0.0, ev["t1"] - ev["t0"])
        lvl = float(ev["peak"]) + self.sdr_offset(kind)
        prio = self.freq_prio(w)
        info = TR("signal bref de {} s vu par le SDR (temps réel)").format(f"{dur:.2f}")
        if not self.alarms.raise_(key, "CONFLIT", w["name"], w["freq"], prio, now, lvl, self.layer_text(w), info):
            return False
        self.log_event(dict(w, note=info), lvl, "CONFLIT")
        self._alarm_sound(prio)
        self.refresh_alarms()
        QtCore.QTimer.singleShot(60000, lambda k_=key: (self.alarms.clear(k_, time.time()), self.refresh_alarms()))
        return True

    def analyze_freq(self, f, w=None):
        """🔎 Étape 8 (FREQ_ACTIONS) : « c'est quoi ce signal ? » -> temps réel centré sur f, analyse affichée."""
        self.open_realtime(float(f))
        rt = getattr(self, "_rt", None)
        if rt is not None:
            rt._ana_f = float(f)
            if rt.worker is None and rt._src is None:
                rt.toggle()
        return rt

    SDR_LISTEN_ID = -40                     # étape 7 : « bande » des mesures venues du flux d'écoute / temps réel

    def sdr_listen_feed(self, kind, F, L, bid=None):
        """Étape 7 (Clément : surveiller ET écouter en même temps) : le spectre de la fenêtre écoutée (dBFS + correction
        du modèle, ou dBm d'un WiNRADiO) sert à surveiller les fréquences qui y tombent, SI aucun autre appareil ne
        balaye (un tinySA garde la main : pas de mélange dBFS / dBm). -> True si utilisé."""
        if any(w.isRunning() and not getattr(w, "paused", False) for w in self.workers):
            return False
        F = np.asarray(F, dtype=float)
        L = np.asarray(L, dtype=float) + self.sdr_offset(kind)
        if len(F) < 2:
            return False
        bid = self.SDR_LISTEN_ID if bid is None else bid       # étape 17 : une « bande » par poste SDR
        self.latest[bid] = (F, L)
        self.latest_t[bid] = time.time()
        try:
            self.update_watch_levels()
            self.update_watch_table()
            if self._hunt is not None and self._hunt.isVisible():   # 13. chasse (et carte de chaleur) avec le SDR
                self._hunt.feed(F, L)
        except Exception:  # noqa: BLE001
            pass
        return True

    def sdr_listen_clear(self, bid=None):
        bid = self.SDR_LISTEN_ID if bid is None else bid
        self.latest.pop(bid, None)
        self.latest_t.pop(bid, None)

    def open_multimon(self):
        """📡 V8 étape 9 : moniteur multicanal SDR (fenêtre gardée : rouverte telle quelle)."""
        self.sdr_timer()
        d = getattr(self, "_multimon", None)
        if d is None:
            d = self._multimon = MultiMonitorDialog(self)
        d.show()
        d.raise_()
        d.activateWindow()
        return d

    def rt_freq(self, f, w=None):
        """⏱ Temps réel autour d'une fréquence (FREQ_ACTIONS)."""
        self.open_realtime(float(f))

    def listen_web_push(self, b):
        """Son de l'écoute -> téléphone (vue 🎧 Écoute), seulement si quelqu'un la regarde."""
        if self.web is None or not self.web.watching(("ecoute",)):
            return
        if getattr(self, "_v8_ring", None) is None:
            self._v8_ring, self._v8_ring_lock = PcmRing(), threading.Lock()
        pcm = pcm_mono16k(b)
        with self._v8_ring_lock:
            self._v8_ring.push(pcm)

    def listen_web_clear(self):
        if getattr(self, "_v8_ring", None) is not None:
            with self._v8_ring_lock:
                self._v8_ring.clear()

    def web_listen_pcm(self, qs):
        """GET /ecoute.pcm?s=n (fil du serveur web) : le son arrivé après le morceau n."""
        n = next((v for k, _, v in (p.partition("=") for p in qs.split("&")) if k == "s"), "0")
        try:
            n = int(n)
        except ValueError:
            n = 0
        if getattr(self, "_v8_ring", None) is None:
            return pcm_packet(0, LISTEN_WEB_RATE, b""), "application/octet-stream"
        with self._v8_ring_lock:
            seq, data = self._v8_ring.since(n)
        return pcm_packet(seq, LISTEN_WEB_RATE, data), "application/octet-stream"

    def web_listen_json(self, qs):
        """GET /ecoute.json : ce que le PC écoute (fil du serveur web : lit un dict remplacé d'un bloc)."""
        st = dict(getattr(self, "_v8_listen", None) or dict(on=False))
        return json.dumps(st, ensure_ascii=False).encode("utf-8"), "application/json; charset=utf-8"

    def web_listen_do(self, cmd):
        """Commande 🎧 du téléphone (code PIN vérifié par le serveur), dans le fil de l'interface."""
        if cmd.get("action") == "stop":
            d = getattr(self, "_listen", None)
            if d is not None and d.worker is not None:
                d.stop()
            self.set_status(TR("📱 Écoute arrêtée depuis le téléphone."))
            return
        f = cmd["f"]
        d = self.listen_freq(f)
        if cmd.get("mode"):
            k = d.mode_combo.findData(cmd["mode"])
            if k >= 0 and d.worker is None:
                d.mode_combo.setCurrentIndex(k)
        self.set_status(TR("📱 Écoute demandée depuis le téléphone : {} MHz").format(f"{f:.3f}"))

    # ------------------------------------------------------- 🆘 7.62 : remplacer un micro en un clic
    def replace_args(self, w):
        """Tout ce qu'il faut (préparé dans le fil de l'interface) pour chercher des remplaçantes de w : le plan actif,
        l'appareil de chaque fréquence (bande comprise), ce que le tinySA voit occupé, les bandes du pays."""
        ws = [x for x in self.watch if x is w or not x.get("off")]
        i = next(k for k, x in enumerate(ws) if x is w)
        po = self.plan_opts
        dflt = dict(sep=po.get("sep", 300) / 1000.0, filt=float(po.get("filt", 32.0)), tol=IM_TOL_PRESETS[0][1],
                    step=po.get("step", 25) / 1000.0)
        P = [rx_profile(self.rx_of(x)) or dflt for x in ws]
        busy = None
        Fm, Lm = self.fresh_FL(use_max=True)
        if Fm is not None:
            lim = self.busy_limit(Lm, weak=True)
            busy = busy_pred(Fm, Lm, lim, max(0.05, self.win_spin.value() / 1000.0))
        F, B = [x["freq"] for x in ws], [float(x.get("bw") or 0.0) for x in ws]
        bd = rx_band(P[i])
        ext = self._band_extent()
        return dict(i=i, F=F, T=[not self.is_keep_free(x["status"]) for x in ws], B=B, sep=[q["sep"] for q in P],
                    tol=[q["tol"] for q in P], filt=[q["filt"] for q in P],
                    img=[float(q.get("img") or 0.0) for q in P], step=P[i].get("step", 0.025), busy=self.reg_busy(busy),
                    near=band_clip(F[i] - 10.0, F[i] + 10.0, bd, B[i]),
                    ext=band_clip(ext[0], ext[1], bd, B[i]) if ext else (band_clip(bd[0], bd[1], bd, B[i]) if bd else None),
                    band=bd, Fm=Fm, Lm=Lm)

    @staticmethod
    def replace_compute(a, n=3):
        """Calcul PUR (peut tourner dans un fil à part) : jusqu'à n remplaçantes, les plus proches d'abord.
        Rien avec toutes les règles (plan très chargé : les 3 TX recouvrent tout) -> nouvel essai en 2A − B seulement,
        signalé (relaxed). -> [(MHz, écart, relaxed)]."""
        st = float(a["step"] or 0.025)
        step = st * max(1, math.ceil(0.025 / st - 1e-9))     # au moins 25 kHz, multiple du pas de l'appareil (rapide)
        gap = max(0.2, float(a["sep"][a["i"]] or 0.0))         # 3 propositions vraiment différentes

        def spread(sg, have):
            out = list(have)
            for c, d in sg:
                if all(abs(c - x[0]) >= gap - 1e-9 for x in out):
                    out.append((c, d))
            return out

        tol2 = [dict(t, **{"3tx3": 0.0, "5": 0.0, "7": 0.0}) for t in a["tol"]]
        kw = dict(n=14 * n, busy=a["busy"], step=step, filt=a["filt"], img=a["img"], max_check=80)
        f0, bd = a["F"][a["i"]], a["band"]
        wins = []
        for half in (10.0, 40.0):
            win = band_clip(f0 - half, f0 + half, bd, a["B"][a["i"]])
            if a["ext"] and win:                      # pas au-delà des bandes balayées (rien de mesuré)
                win = (max(win[0], a["ext"][0]), min(win[1], a["ext"][1]))
            if win and win[1] > win[0]:
                wins.append(win)
        for tol, rel in ((a["tol"], False), (tol2, True)):   # règles complètes, sinon 2A − B seulement (signalé)
            got = []
            for win in wins:                          # près d'abord, plus loin pour compléter
                got = spread(pf_suggest(a["i"], a["F"], a["T"], a["B"], a["sep"], tol, None, lo=win[0], hi=win[1], **kw),
                             got)
                if len(got) >= n:
                    break
            if got:
                got.sort(key=lambda x: abs(x[1]))
                return [(c, d, rel) for c, d in got[:n]]
        return []

    def replace_decorate(self, a, sg, w):
        """Propositions -> [dict(f, d, level, tag)] (niveau mesuré, réserve réglementaire)."""
        out = []
        for c, d, rel in sg:
            lv = level_at(a["Fm"], a["Lm"], c, 0.1) if a["Fm"] is not None else None
            tag = self.reg_tag(c, float(w.get("bw") or 0.0))
            if rel:
                tag = "règles allégées : 2A − B seulement" + (f" · {tag}" if tag else "")
            out.append(dict(f=round(float(c), 4), d=float(d), level=lv, tag=tag, relaxed=rel))
        return out

    def suggest_replacements(self, w, n=3):
        """Version directe (fil de l'interface) : page Tech, tests."""
        a = self.replace_args(w)
        return self.replace_decorate(a, self.replace_compute(a, n), w)

    def replace_watch(self, w, f, how="🆘 remplacement"):
        """Remplace la fréquence de w par f : alarmes de l'ancienne effacées, journal « NOUVELLE FRÉQUENCE »."""
        if not any(x is w for x in self.watch):
            return False
        old = w["freq"]
        k0 = int(round(old * 1000))
        now = time.time()
        for kind in ("CONFLIT", "ABSENT"):
            self.alarms.clear((kind, k0), now)
        self.set_watch_freq(w, f)
        self.log_event(dict(name=w["name"], freq=0.0, note=f"{old:.3f} → {f:.3f} MHz ({how})"), 0.0, "NOUVELLE FRÉQUENCE")
        self.refresh_alarms()
        self.undo_track()
        self.set_status(TR("🆘 {} : {} → {} MHz. Règle l'émetteur ET le récepteur sur la nouvelle fréquence.").format(
            w["name"], f"{old:.3f}", f"{f:.3f}"))
        return True

    def open_replace(self, w=None):
        """🆘 Fenêtre « Remplacer ce micro » : w = la fréquence (sinon celle choisie dans la liste, sinon l'alarme)."""
        if w is None:
            rows = self._sel_rows()
            w = self.watch[rows[0]] if rows else self._alarm_watch()
        if w is None:
            self.set_status("Choisis d'abord le micro à remplacer (dans la liste ou dans les alarmes).")
            return None
        if self._replace is not None:
            try:
                self._replace.close()
            except RuntimeError:
                pass
        self._replace = ReplaceDialog(self, w)
        self._replace.show()
        return self._replace

    def _alarm_watch(self):
        """La fréquence de la liste liée à l'alarme choisie (sinon la plus récente non acquittée)."""
        ids = self._alarm_selected_ids()
        items = self.alarms.listing()
        a = next((x for x in items if ids and x["id"] == ids[0]), None) or next(
            (x for x in items if x["t_end"] is None and not x["acked"] and x.get("freq")), None)
        if a is None or not a.get("freq"):
            return None
        return min(self.watch, key=lambda x: abs(x["freq"] - a["freq"]), default=None) if any(
            abs(x["freq"] - a["freq"]) < 0.0015 for x in self.watch) else None

